window.PORTAX_DATA={"note":"합성 사례, 실제 주최 서류 아님. 판정 문장·근거 번호는 실측-2026-10-20 케이스 원본 그대로.","laws":{"portact":{"id":"portact","name":"선박의 입항 및 출항 등에 관한 법률 시행규칙","effective":"20241113","promulgated":"20241113","articles":{"제1조":{"title":"목적","head":"제1조(목적) 이 규칙은 「선박의 입항 및 출항 등에 관한 법률」 및 같은 법 시행령에서 위임된 사항과 그 시행에 필요한 사항을 규정함을 목적으로 한다.","paras":[]},"제2조":{"title":"위험물의 범위","head":"제2조(위험물의 범위) 「선박의 입항 및 출항 등에 관한 법률」(이하 \"법\"이라 한다) 제2조제12호 본문에서 \"해양수산부령으로 정하는 것\"이란 「위험물 선박운송 및 저장규칙」 제2조제1호에 따른 위험물 및 같은 조 제2호에 따른 산적액체위험물(이하 \"산적액체위험물\"이라 한다)을 말한다.","paras":[]},"제3조":{"title":"선박 출입 신고서 등","head":"제3조(선박 출입 신고서 등)","paras":[{"no":"①","text":"① 법 제4조제1항에 따라 무역항의 수상구역등에 출입하려는 「선박의 입항 및 출항 등에 관한 법률 시행령」(이하 \"영\"이라 한다) 제2조제1호에 따른 내항선의 선장은 별지 제1호서식에 따른 내항선 출입신고서를 지방해양수산청장, 특별시장ㆍ광역시장ㆍ도지사ㆍ특별자치도지사(이하 \"시ㆍ도지사\"라 한다) 또는 「항만공사법」에 따른 항만공사(이하 \"항만공사\"라 한다)에 제출하여야 한다. 이 경우 화물선의 선장은 출입신고서에 별지 제1호의2서식에 따른 승객 명부를 첨부하여야 한다. <개정 2018.7.4>","items":[]},{"no":"②","text":"② 법 제4조제1항에 따라 무역항의 수상구역등에 출입하려는 영 제2조제2호에 따른 외항선의 선장은 별지 제2호서식에 따른 외항선 출입신고서에 별지 제1호의2서식에 따른 승객 명부 및 별지 제2호의2서식에 따른 승무원 명부를 첨부하여 지방해양수산청장, 시ㆍ도지사 또는 항만공사에 제출하여야 한다. <개정 2020.5.7>","items":[{"no":"1.","text":"1. 삭제<2020.5.7>"},{"no":"2.","text":"2. 삭제<2020.5.7>"}]},{"no":"③","text":"③ 무역항의 수상구역등으로 입항하는 선박의 선장은 해당 선박의 출항 일시가 이미 정해진 경우에는 입항과 출항의 신고를 동시에 할 수 있다.","items":[]},{"no":"④","text":"④ 제1항부터 제3항까지에 따라 출입신고서를 제출한 선박의 선장은 해당 선박의 출입 일시가 변경된 경우에는 지체 없이 그 사실을 지방해양수산청장, 시ㆍ도지사 또는 항만공사에 신고하여야 한다.","items":[]}]},"제4조":{"title":"신고의 면제","head":"제4조(신고의 면제) 법 제4조제1항제4호에서 \"해양수산부령으로 정하는 선박\"이란 다음 각 호의 선박을 말한다. <개정 2017.7.28>","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 관공선, 군함, 해양경찰함정 등 공공의 목적으로 운영하는 선박"},{"no":"2.","text":"2. 도선선(導船船), 예선(曳船) 등 선박의 출입을 지원하는 선박"},{"no":"3.","text":"3. 「선박직원법 시행령」 제2조제1호에 따른 연안수역을 항행하는 정기여객선(「해운법」에 따라 내항 정기 여객운송사업에 종사하는 선박을 말한다)으로서 경유항(經由港)에 출입하는 선박"},{"no":"4.","text":"4. 피난을 위하여 긴급히 출항하여야 하는 선박"},{"no":"5.","text":"5. 그 밖에 항만운영을 위하여 지방해양수산청장이나 시ㆍ도지사가 필요하다고 인정하여 출입 신고를 면제한 선박"}]}]},"제5조":{"title":"출입 허가의 신청","head":"제5조(출입 허가의 신청) 법 제4조제3항에 따라 출입 허가를 받으려는 선박의 선장은 무역항의 수상구역등에 출입하기 3일 전까지 별지 제3호서식에 따른 출입 허가 신청서를 지방해양수산청장 또는 시ㆍ도지사에게 제출하여야 한다. <개정 2019.7.16>","paras":[]},"제6조":{"title":"정박지의 지정 신청","head":"제6조(정박지의 지정 신청)","paras":[{"no":"①","text":"① 영 제6조제1항에 따른 정박지의 지정 신청서는 「항만법 시행령」 제44조제1항에 따른 항만시설 사용허가신청서에 따른다. <개정 2020.7.30>","items":[]},{"no":"②","text":"② 법 제5조제2항 단서에서 \"해양수산부령으로 정하는 사유\"란 다음 각 호의 경우를 말한다.","items":[{"no":"1.","text":"1. 「해양사고의 조사 및 심판에 관한 법률」 제2조제1호에 따른 해양사고를 피하기 위한 경우"},{"no":"2.","text":"2. 선박의 고장이나 그 밖의 사유로 선박을 조종할 수 없는 경우"},{"no":"3.","text":"3. 인명을 구조하거나 급박한 위험이 있는 선박을 구조하는 경우"},{"no":"4.","text":"4. 해양오염 등의 발생 또는 확산을 방지하기 위한 경우"},{"no":"5.","text":"5. 그 밖에 선박의 안전운항을 위하여 지방해양수산청장 또는 시ㆍ도지사가 필요하다고 인정하는 경우"}]}]},"제7조":{"title":"선박계선의 신고","head":"제7조(선박계선의 신고)","paras":[{"no":"①","text":"① 법 제7조제1항에 따라 선박을 계선(繫船)하려는 자는 별지 제4호서식에 따른 선박계선 신고서를 지방해양수산청장 또는 시ㆍ도지사에게 제출하여야 한다.","items":[]},{"no":"②","text":"② 제1항에 따른 선박의 계선 신고를 받은 지방해양수산청장 또는 시ㆍ도지사는 별지 제4호서식에 따른 선박계선 신고서의 확인란에 날인하여 신고인에게 발급하여야 한다.","items":[]}]},"제8조":{"title":"항로 준수의 예외","head":"제8조(항로 준수의 예외) 법 제10조제2항 단서에서 \"해양수산부령으로 정하는 사유\"란 제6조제2항 각 호의 어느 하나에 해당하는 경우를 말한다.","paras":[]},"제9조":{"title":"예인선의 항법 등","head":"제9조(예인선의 항법 등)","paras":[{"no":"①","text":"① 법 제15조제1항에 따라 예인선이 무역항의 수상구역등에서 다른 선박을 끌고 항행하는 경우에는 다음 각 호에서 정하는 바에 따라야 한다.","items":[{"no":"1.","text":"1. 예인선의 선수(船首)로부터 피(被)예인선의 선미(船尾)까지의 길이는 200미터를 초과하지 아니할 것. 다만, 다른 선박의 출입을 보조하는 경우에는 그러하지 아니하다."},{"no":"2.","text":"2. 예인선은 한꺼번에 3척 이상의 피예인선을 끌지 아니할 것"}]},{"no":"②","text":"② 제1항에도 불구하고 지방해양수산청장 또는 시ㆍ도지사는 해당 무역항의 특수성 등을 고려하여 특히 필요한 경우에는 제1항에 따른 항법을 조정할 수 있다. 이 경우 지방해양수산청장 또는 시ㆍ도지사는 그 사실을 고시하여야 한다.","items":[]}]},"제10조":{"title":"예선업의 등록 신청 등","head":"제10조(예선업의 등록 신청 등)","paras":[{"no":"①","text":"① 법 제24조제1항에 따라 예선업의 등록을 하려는 자는 별지 제5호서식에 따른 예선업 등록신청서(전자문서를 포함한다)에 다음 각 호의 서류를 첨부하여 지방해양수산청장 또는 시ㆍ도지사에게 제출하여야 한다. <개정 2019.7.16>","items":[{"no":"1.","text":"1. 정관(법인인 경우만 해당한다)"},{"no":"2.","text":"2. 사업계획서"},{"no":"3.","text":"3. 예선의 척수(隻數), 제원(諸元) 현황 및 소화장비 등의 시설현황"},{"no":"4.","text":"4. 「한국해양교통안전공단법」에 따라 설립된 한국해양교통안전공단(이하 \"한국해양교통안전공단\"이라 한다) 또는 「선박안전법」 제60조제2항에 따른 선급법인(船級法人)(이하 \"선급법인\"이라 한다)이 발행한 예항력(曳航力) 증명서"}]},{"no":"②","text":"② 제1항에 따른 신청을 받은 지방해양수산청장 또는 시ㆍ도지사는 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 신청인의 법인 등기사항증명서(법인인 경우만 해당한다)를 확인하여야 한다.","items":[]},{"no":"③","text":"③ 법 제24조제1항에 따라 등록을 한 예선업자(이하 \"예선업자\"라 한다)는 등록사항을 변경하려는 경우에는 별지 제6호서식에 따른 예선업 등록사항 변경신청서에 변경 사실을 증명하는 서류를 첨부하여 지방해양수산청장 또는 시ㆍ도지사에게 제출하여야 한다. <개정 2017.9.21>","items":[]},{"no":"④","text":"④ 제1항제2호에 따른 사업계획서에는 다음 각 호의 사항이 포함되어야 한다.","items":[{"no":"1.","text":"1. 사업의 세부 추진계획 및 사업개시 예정일"},{"no":"2.","text":"2. 사업에 필요한 예선업 종사원 현황"},{"no":"3.","text":"3. 예선 현황"},{"no":"4.","text":"4. 그 밖에 예선의 관리ㆍ운영에 관한 사항"}]},{"no":"⑤","text":"⑤ 법 제24조제2항제1호에서 \"해양수산부령으로 정하는 무역항별 예선보유기준\"은 별표 1과 같다.","items":[]},{"no":"⑥","text":"⑥ 법 제24조제2항제2호에 따른 예선추진기형은 전(全)방향 회전속도가 60초 이내이여야 한다.","items":[]},{"no":"⑦","text":"⑦ 법 제24조제2항제3호에서 \"소화설비 등 해양수산부령으로 정하는 시설\"이란 별표 2의 시설을 말한다.","items":[]},{"no":"⑧","text":"⑧ 법 제24조제2항제4호 본문에서 \"해양수산부령으로 정하는 기준\"이란 30년 이하일 것을 말한다. 다만, 「선박안전법」 제8조부터 제10조까지의 규정에 따른 선박검사 및 법 제29조제2항에 따른 예항력검사에 합격한 예선의 경우에는 선령의 기준 연한(年限)을 5년의 범위에서 1년 단위로 연장할 수 있다. <신설 2018.7.4>","items":[]},{"no":"⑨","text":"⑨ 지방해양수산청장 또는 시ㆍ도지사는 제1항에 따라 예선업 등록 신청을 받은 경우 신청인이 법 제24조제2항에 따른 예선업 등록기준에 적합하고, 법 제25조에 따른 예선업 등록 제한 사유에 해당하지 아니하면 별지 제7호서식에 따른 예선업 등록증을 신청인에게 발급하여야 한다. <개정 2018.7.4>","items":[]},{"no":"⑩","text":"⑩ 지방해양수산청장 또는 시ㆍ도지사는 제9항에 따라 예선업 등록증을 발급하였을 때에는 예선업 등록대장에 다음 각 호의 사항을 기재하여야 한다. <개정 2018.7.4>","items":[{"no":"1.","text":"1. 사업을 영위하는 무역항명"},{"no":"2.","text":"2. 상호 및 주소"},{"no":"3.","text":"3. 대표자 및 임원의 성명"},{"no":"4.","text":"4. 예선의 척수 및 선박별 제원"}]}]},"제10조의2":{"title":"다른 무역항에 등록된 예선의 이용","head":"제10조의2(다른 무역항에 등록된 예선의 이용)","paras":[{"no":"①","text":"① 법 제24조제4항에 따라 다른 무역항에 등록된 예선을 이용하려는 무역항을 관할하는 지방해양수산청장 또는 시ㆍ도지사는 이용기간과 사유 등에 대하여 다른 무역항을 관할하는 지방해양수산청장 또는 시ㆍ도지사와 미리 협의한 후, 그 협의 결과를 첨부하여 해양수산부장관에게 예선의 이용을 신청하여야 한다.","items":[]},{"no":"②","text":"② 제1항에 따른 신청을 받은 해양수산부장관은 다음 각 호의 요건을 모두 갖춘 경우 다른 무역항에 등록된 예선을 이용하게 할 수 있다.","items":[{"no":"1.","text":"1. 다른 무역항에 등록된 예선을 이용하려는 무역항에 다음 각 목의 어느 하나에 해당하는 사유가 발생할 것 가. 무역항에 출입하는 선박이 일시적으로 급증하여 해당 무역항에 등록된 예선으로는 제때 예선업무를 수행하기 어려운 경우\n 나. 예선업자에 대한 사업정지 처분 등 예선업자의 사정으로 인하여 일시적으로 예선업무를 원활하게 수행하기 어려운 경우\n 다. 무역항의 운영상 사정 등 해양수산부장관이 인정하는 사유로 인하여 일시적으로 예선업무를 원활하게 수행하기 어려운 경우"},{"no":"2.","text":"2. 다른 무역항에 등록된 예선을 이용함으로써 다른 무역항의 예선업무 수행에 지장이 없을 것"}]},{"no":"③","text":"③ 해양수산부장관은 제2항에 따라 다른 무역항에 등록된 예선을 이용하게 하려는 경우 이를 제1항에 따른 다른 무역항에 등록된 예선의 이용을 신청하는 지방해양수산청장 또는 시ㆍ도지사 및 다른 무역항을 관할하는 지방해양수산청장 또는 시ㆍ도지사에게 통보하여야 한다.","items":[]},{"no":"④","text":"④ 제2항에 따라 등록된 무역항이 아닌 다른 무역항에서 예선업무를 수행하려는 예선업자는 해당 무역항에 입항하기 전에 그 사실을 해당 무역항을 관할하는 지방해양수산청장 또는 시ㆍ도지사에게 통보하여야 한다.","items":[]},{"no":"⑤","text":"⑤ 제1항부터 제4항까지에서 규정한 사항 외에 다른 무역항에 등록된 예선의 이용에 필요한 절차 및 방법 등에 관한 세부사항은 해양수산부장관이 정하여 고시한다.","items":[]}]},"제10조의3":{"title":"예선의 대기장소 부족으로 인한 예선업 등록 거부","head":"제10조의3(예선의 대기장소 부족으로 인한 예선업 등록 거부)","paras":[{"no":"①","text":"① 법 제25조제4항에서 \"해양수산부령으로 정하는 기준\"이란 항만 내 예선의 대기장소에 예선을 겹쳐서 접안(接岸)할 경우 3겹 이내로 겹쳐서 접안할 수 있을 것을 말한다. 다만, 항만 운영의 여건상 필요한 경우로서 예선의 대기장소에 설치된 계선주(繫船柱) 등 항만시설의 설계 기준 및 안전상 문제가 없다고 인정되는 경우에는 5겹 이내로 겹쳐서 접안할 수 있도록 예선의 대기장소에 관한 기준을 완화할 수 있다.","items":[]},{"no":"②","text":"② 지방해양수산청장 또는 시ㆍ도지사는 제1항에 따른 예선의 대기장소에 관한 기준을 고시하여야 한다.","items":[]}]},"제10조의4":{"title":"예선서비스평가위원회의 구성 및 운영","head":"제10조의4(예선서비스평가위원회의 구성 및 운영)","paras":[{"no":"①","text":"① 법 제25조의3제6항에 따른 예선서비스평가위원회(이하 이 조에서 \"위원회\"라 한다)는 위원장 1명을 포함하여 7명 이상 10명 이하의 위원으로 구성한다.","items":[]},{"no":"②","text":"② 위원회의 위원장(이하 이 조에서 \"위원장\"이라 한다)은 해양수산부의 항만운영 분야의 업무를 담당하는 고위공무원단에 속하는 일반직공무원이 되고, 위원은 다음 각 호의 어느 하나에 해당하는 사람 중에서 해양수산부장관이 임명 또는 위촉한다.","items":[{"no":"1.","text":"1. 항만운영 분야의 전문지식과 경험이 풍부한 사람"},{"no":"2.","text":"2. 항만운영 분야의 업무를 담당하는 해양수산부 소속 4급 이상 또는 4급 상당 이상의 공무원"},{"no":"3.","text":"3. 예선 사용자 단체에서 추천하는 사람"},{"no":"4.","text":"4. 예선업자 단체에서 추천하는 사람"}]},{"no":"③","text":"③ 위원장이 부득이한 사유로 직무를 수행할 수 없는 경우에는 위원장이 미리 지명한 위원이 그 직무를 대행한다.","items":[]},{"no":"④","text":"④ 제2항에 따라 위촉된 위원의 임기는 2년으로 한다.","items":[]},{"no":"⑤","text":"⑤ 위원회의 회의는 위원장이 소집하며, 재적위원 과반수의 출석으로 개의(開議)하고, 출석위원 과반수의 찬성으로 의결한다.","items":[]},{"no":"⑥","text":"⑥ 제1항부터 제5항까지에서 규정한 사항 외에 위원회의 구성 및 운영 등에 필요한 사항은 해양수산부장관이 정한다.","items":[]}]},"제11조":{"title":"등록의 취소 등 통보","head":"제11조(등록의 취소 등 통보) 지방해양수산청장 또는 시ㆍ도지사는 법 제26조에 따라 행정처분을 한 경우에는 그 처분의 내용을 지체 없이 처분대상자에게 통지하여야 한다.","paras":[]},"제12조":{"title":"과징금 납부통지 서식 등","head":"제12조(과징금 납부통지 서식 등)","paras":[{"no":"①","text":"① 영 제9조에 따른 과징금 납부통지서ㆍ영수통지서ㆍ납부영수증은 별지 제8호서식에 따른다.","items":[]},{"no":"②","text":"② 영 제10조제1항에 따른 독촉장은 별지 제9호서식에 따른다.","items":[]}]},"제13조":{"title":"예선의 예항력검사","head":"제13조(예선의 예항력검사)","paras":[{"no":"①","text":"① 법 제29조제2항에 따라 예선은 다음 각 호의 구분에 따른 예항력검사의 유효기간 내에 한국해양교통안전공단 또는 선급법인이 실시하는 정기 예항력검사를 받아야 한다. <개정 2019.7.16>","items":[{"no":"1.","text":"1. 검사 당시 예선의 선령이 25년 미만인 경우: 5년"},{"no":"2.","text":"2. 검사 당시 예선의 선령이 25년 이상인 경우: 3년"}]},{"no":"②","text":"② 지방해양수산청장 또는 시ㆍ도지사는 선사(船社), 도선사(導船士) 등 예선 사용자의 요청으로 예항력에 이상이 있다고 인정되는 예선에 대해서는 제1항 각 호의 구분에 따른 유효기간에도 불구하고 수시 예항력검사를 명할 수 있다.","items":[]},{"no":"③","text":"③ 예선업자는 제1항에 따른 정기 예항력검사를 받은 경우에는 유효기간 만료일 3개월 전부터 만료일까지, 제2항에 따른 수시 예항력검사를 받은 경우에는 검사 명령일부터 15일 이내에 예항력검사를 받고 그 결과를 지방해양수산청장 또는 시ㆍ도지사에게 제출하여야 한다.","items":[]},{"no":"④","text":"④ 제1항에 따른 정기 예항력검사의 유효기간은 제10조제1항제4호에 따른 예항력 증명서의 검사일부터 제1항 각 호의 구분에 따라 유효기간을 계산한다. 다만, 제2항에 따른 수시 예항력검사를 실시한 경우에는 본문에도 불구하고 수시 예항력검사를 받은 날부터 제1항 각 호의 구분에 따라 유효기간을 계산한다.","items":[]}]},"제13조의2":{"title":"예선의 공동 배정","head":"제13조의2(예선의 공동 배정)","paras":[{"no":"①","text":"① 예선업자는 법 제29조의2제1항 단서에 따라 예선을 공동 배정하려면 다음 각 호의 사항을 포함한 규약을 작성하여 지방해양수산청장 또는 시ㆍ도지사 및 영 제11조제1항에 따른 지방예선운영협의회(이하 \"지방협의회\"라 한다)에 제출하여야 한다.","items":[{"no":"1.","text":"1. 공동 배정에 참여하는 예선업자 및 이를 대표하는 예선업자"},{"no":"2.","text":"2. 공동 배정의 방법"},{"no":"3.","text":"3. 예선 사용의 조건"},{"no":"4.","text":"4. 공동 배정의 기간"}]},{"no":"②","text":"② 제1항에도 불구하고 해당 항만의 전체 예항력의 100분의 50을 넘는 예선을 공동 배정하려는 예선업자는 제1항에 따라 작성한 규약에 대하여 미리 지방협의회의 의견을 듣고, 그 결과를 규약과 함께 지방해양수산청장 또는 시ㆍ도지사에게 제출하여야 한다.","items":[]},{"no":"③","text":"③ 제1항 또는 제2항에 따라 공동 배정에 관한 규약을 제출한 예선업자는 예선 사용자 등이 확인할 수 있도록 해양수산부장관이 지정하는 전자매체에 해당 규약의 내용을 공표하여야 한다.","items":[]},{"no":"④","text":"④ 예선업자가 예선의 공동 배정을 조기에 종료하거나 공동 배정에 참여하는 예선업자를 변경하는 등 제3항에 따라 공표한 규약의 내용을 변경하려는 경우에는 제1항 및 제3항에 따른다.","items":[]}]},"제14조":{"title":"위험물 반입의 신고","head":"제14조(위험물 반입의 신고)","paras":[{"no":"①","text":"① 법 제32조제1항에 따라 위험물을 무역항의 수상구역등으로 들여오려는 자는 반입 24시간 전에 다음 각 호의 서류를 지방해양수산청장 또는 시ㆍ도지사에게 제출해야 한다. 다만, 위험물을 육상으로 반입하는 경우에는 무역항의 육상구역으로 위험물을 들여오기 전까지, 전(前) 출항지부터 반입항까지의 운항 시간이 24시간 이내이고 해상으로 위험물을 반입하는 경우에는 무역항의 수상구역등으로 위험물을 들여오기 전까지 위험물 반입신고서 등을 제출할 수 있다. <개정 2020.9.28>","items":[{"no":"1.","text":"1. 별지 제10호서식의 위험물 반입신고서"},{"no":"2.","text":"2. 별지 제11호서식의 위험물 일람표"},{"no":"3.","text":"3. 별지 제11호의2서식의 화물적부도[위험물 등 운송물의 선박 내 배치에 관한 도면을 말하며, 「위험물 선박운송 및 저장규칙」 제2조제12호ㆍ제13호에 따른 탱커 및 탱크선 중 화물창(貨物艙)이 두 개 이상인 선박의 경우에만 제출한다]"}]},{"no":"②","text":"② 제1항에 따른 신고서를 제출받은 지방해양수산청장 또는 시ㆍ도지사는 별지 제10호서식에 따른 위험물 반입신고서의 확인란에 날인하여 신고인에게 발급하여야 한다.","items":[]}]},"제15조":{"title":"위험물 반입의 제한","head":"제15조(위험물 반입의 제한)","paras":[{"no":"①","text":"① 지방해양수산청장 또는 시ㆍ도지사는 법 제32조제3항에 따라 다음 각 호의 어느 하나에 해당하는 위험물에 대해서는 그 반입을 제한할 수 있다. <개정 2019.7.16>","items":[{"no":"1.","text":"1. 「위험물 선박운송 및 저장규칙」 제3조제1호가목ㆍ나목ㆍ다목에 따른 화약류"},{"no":"2.","text":"2. 「위험물 선박운송 및 저장규칙」 제3조제6호나목에 따른 독물류"},{"no":"3.","text":"3. 「위험물 선박운송 및 저장규칙」 제3조제7호에 따른 방사성 물질"}]},{"no":"②","text":"② 지방해양수산청장 또는 시ㆍ도지사는 무역항의 수상구역등으로 반입된 위험물에 대하여 해당 위험물의 격리, 이동 또는 반출 등 안전에 필요한 조치를 할 수 있다.","items":[]}]},"제15조의2":{"title":"위험물의 통지","head":"제15조의2(위험물의 통지) 법 제32조제4항에 따른 위험물의 통지는 별지 제11호서식에 따른다.","paras":[]},"제16조":{"title":"자체안전관리계획의 승인 신청 및 승인 절차 등","head":"제16조(자체안전관리계획의 승인 신청 및 승인 절차 등)","paras":[{"no":"①","text":"① 법 제34조제1항 전단에 따른 자체안전관리계획(이하 \"자체안전관리계획\"이라 한다)의 승인, 같은 항 후단에 따른 자체안전관리계획의 변경승인 및 영 제14조제3항에 따른 자체안전관리계획의 갱신을 신청하려는 자는 다음 각 호의 구분에 따른 기간 내에 별지 제12호서식에 따른 자체안전관리계획 승인ㆍ변경승인ㆍ갱신 신청서에 자체안전관리계획을 첨부하여 지방해양수산청장 또는 시ㆍ도지사에게 제출하여야 한다.","items":[{"no":"1.","text":"1. 최초 자체안전관리계획의 승인: 위험물 하역 전"},{"no":"2.","text":"2. 자체안전관리계획의 변경승인: 변경사유가 발생한 날부터 1개월"},{"no":"3.","text":"3. 자체안전관리계획의 유효기간 만료에 따른 갱신: 영 제14조제3항에서 정한 기간"}]},{"no":"②","text":"② 제1항에 따라 승인 신청을 받은 지방해양수산청장 또는 시ㆍ도지사는 자체안전관리계획의 승인ㆍ변경승인 또는 갱신 여부를 검토하고 신청서 접수일부터 15일 이내에 그 결과를 신청인에게 통보하여야 한다.","items":[]}]},"제17조":{"title":"위험물 하역의 제한 등","head":"제17조(위험물 하역의 제한 등)","paras":[{"no":"①","text":"① 지방해양수산청장 또는 시ㆍ도지사가 법 제34조제3항에 따라 위험물의 하역을 금지 또는 중지하게 하거나 무역항의 수상구역등 외의 장소를 지정하여 하역하게 하는 경우에는 그 사유 등을 명시한 서면으로 통보하여야 한다. 다만, 긴급한 경우에는 구두(口頭)로 통보할 수 있다.","items":[]},{"no":"②","text":"② 법 제34조제4항에서 \"해양수산부령으로 정하는 장소\"란 총톤수 1천톤 이상의 위험물 운송선박이 접안할 수 있는 부두시설 및 위험물 하역작업에 필요한 시설을 갖추고, 산적액체위험물을 취급하는 장소를 말한다.","items":[]}]},"제18조":{"title":"위험물 안전관리자의 자격기준 등","head":"제18조(위험물 안전관리자의 자격기준 등)","paras":[{"no":"①","text":"① 위험물취급자가 확보하여야 하는 법 제35조제1항제1호 본문에 따른 위험물 취급에 관한 안전관리자(이하 \"위험물 안전관리자\"라 한다)의 자격 및 보유기준은 별표 3과 같다.","items":[]},{"no":"②","text":"② 위험물취급자가 제1항에 따른 위험물 안전관리자를 선임하는 경우에는 지방해양수산청장 또는 시ㆍ도지사에게 안전관리자 선임증 발급을 요청할 수 있다. 이 경우 지방해양수산청장 또는 시ㆍ도지사는 위험물취급자에게 별지 제13호서식에 따른 위험물 안전관리자 선임증을 발급할 수 있다.","items":[]}]},"제19조":{"title":"위험물 취급 시의 안전조치","head":"제19조(위험물 취급 시의 안전조치)","paras":[{"no":"①","text":"① 위험물취급자가 법 제35조제1항제1호 단서에 따라 안전관리 전문업체(이하 \"안전관리 전문업체\"라 한다)로 하여금 위험물 안전관리 업무를 대행하게 하는 경우 안전관리 전문업체는 원래의 위험물취급자를 기준으로 별표 3에 따른 위험물 안전관리자의 자격 및 보유기준에 적합하게 위험물 안전관리자를 확보하여야 하고, 위험물 안전관리자마다 위험물취급자를 지정하여 해당 위험물취급자의 안전관리 업무를 전담하게 하여야 한다.","items":[]},{"no":"②","text":"② 법 제35조제1항제2호에서 \"해양수산부령으로 정하는 위험물 운송선박\"이란 총톤수 1천톤 이상의 산적액체위험물을 운송하는 선박을 말한다.","items":[]},{"no":"③","text":"③ 법 제35조제1항제6호에서 \"해양수산부령으로 정하는 안전에 필요한 조치\"란 다음 각 호의 조치를 말한다.","items":[{"no":"1.","text":"1. 지방해양수산청장 또는 시ㆍ도지사가 승인한 자체안전관리계획서의 현장 비치"},{"no":"2.","text":"2. 안전점검 사실을 확인할 수 있는 서류의 작성 및 현장 비치"},{"no":"3.","text":"3. 그 밖에 지방해양수산청장 또는 시ㆍ도지사가 정하여 고시하는 사항"}]}]},"제19조의2":{"title":"위험물 안전관리자의 교육","head":"제19조의2(위험물 안전관리자의 교육) 위험물 안전관리자는 법 제35조제2항에 따라 별표 4에 따른 교육을 받아야 한다.","paras":[]},"제19조의3":{"title":"위험물 하역 관련 안전장비","head":"제19조의3(위험물 하역 관련 안전장비)","paras":[{"no":"①","text":"① 법 제35조제6항에서 \"해양수산부령으로 정하는 위험물\"이란 산적액체위험물을 말한다.","items":[]},{"no":"②","text":"② 법 제35조제6항에서 \"해양수산부령으로 정하는 안전장비\"란 다음 각 호의 장비를 말한다.","items":[{"no":"1.","text":"1. 접안하는 선박의 속도 등을 확인할 수 있는 선박접안속도계"},{"no":"2.","text":"2. 돌핀 계류시설에 외부 충격이 있을 경우 즉시 작동할 수 있는 자동경보시스템"},{"no":"3.","text":"3. 원격으로 위험물의 차폐(遮蔽)가 가능한 자동차단밸브"}]},{"no":"③","text":"③ 제2항제1호 및 제2호에 따른 선박접안속도계 및 자동경보시스템은 각 선석(선박을 매어두는 위치)마다 1개 이상 설치해야 하며, 같은 항 제3호에 따른 자동차단밸브는 육상구역의 관로마다 1개 이상 설치해야 한다. <개정 2021.6.30>","items":[]}]},"제19조의4":{"title":"위험물 관련 자료제출","head":"제19조의4(위험물 관련 자료제출)","paras":[{"no":"①","text":"① 관리청이 법 제35조의2제1항에 따라 관계 행정기관의 장에게 요청할 수 있는 자료는 다음 각 호와 같다.","items":[{"no":"1.","text":"1. 위험물의 적재(積載) 여부를 확인할 필요가 있는 선박에 대한 다음 각 목의 정보 가. 선박명 또는 선박번호 등 해당 선박의 식별을 위한 정보\n 나. 해당 선박의 국내 입항일과 입항 항만 등 운항 정보"},{"no":"2.","text":"2. 제1호에 해당하는 선박에 적재된 위험물의 선하증권(船荷證券) 번호 및 품목번호 등 위험물을 식별하기 위한 정보"},{"no":"3.","text":"3. 그 밖에 관리청이 선박에 적재된 위험물로 인한 사고를 예방하기 위하여 필요하다고 인정하는 정보"}]},{"no":"②","text":"② 관계 행정기관의 장은 법 제35조의2제1항에 따라 요청받은 자료를 제출하는 경우 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」 제2조제1항제1호에 따른 정보통신망 또는 법 제50조제1항에 따른 항만운영정보시스템을 이용하여 전자적 파일 형태로 제출해야 한다.","items":[]}]},"제20조":{"title":"교육기관의 지정 및 운영 등","head":"제20조(교육기관의 지정 및 운영 등)","paras":[{"no":"①","text":"① 법 제36조제1항에 따른 위험물 안전관리자의 교육을 위한 교육기관(이하 \"교육기관\"이라 한다)의 지정기준은 다음 각 호와 같다. <개정 2018.7.4>","items":[{"no":"1.","text":"1. 강의실 면적은 60제곱미터 이상으로서 교육생 1명당 1.2제곱미터 이상이 되는 시설물을 확보할 것. 이 경우 소유ㆍ전세ㆍ임대차 또는 사용대차 등의 방법으로 해당 시설물에 대한 사용권을 확보하여야 한다."},{"no":"2.","text":"2. 다음 각 목의 어느 하나에 해당하는 2명 이상의 강사를 확보할 것 가. 위험물 안전관리자로서 경력이 5년 이상인 사람\n 나. 교육기관에서 위험물 안전관리자에 대한 교육과정을 강의한 경력이 5년 이상인 사람"}]},{"no":"②","text":"② 교육기관으로 지정받으려는 자는 별지 제14호서식에 따른 교육기관 지정신청서에 다음 각 호의 서류를 첨부하여 해양수산부장관에게 제출하여야 한다.","items":[{"no":"1.","text":"1. 교육기관의 시설물 사용권 확보를 증명할 수 있는 서류(전세 또는 임대의 경우 계약서 사본 등) 1부"},{"no":"2.","text":"2. 강사 확보에 관한 증명서류(재직증명서 사본 등) 1부"},{"no":"3.","text":"3. 연간 교육일정, 교육장소, 강사진, 교육교재 등을 포함한 교육계획서"}]},{"no":"③","text":"③ 제2항에 따른 교육기관 지정신청서를 받은 해양수산부장관은 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 신청인의 법인 등기사항증명서(법인인 경우만 해당한다)를 확인하여야 한다.","items":[]},{"no":"④","text":"④ 해양수산부장관은 제2항에 따른 교육기관 지정신청서를 제출한 기관을 교육기관으로 지정하는 경우에는 별지 제15호서식에 따른 위험물 안전관리자 교육기관 지정서를 발급하여야 한다.","items":[]},{"no":"⑤","text":"⑤ 교육기관의 장은 교육기관의 명칭, 교육기관의 장 또는 교육기관의 주소 등이 변경된 경우에는 그 내용을 즉시 해양수산부장관에게 보고하여야 한다.","items":[]},{"no":"⑥","text":"⑥ 삭제 <2018.7.4>","items":[]},{"no":"⑦","text":"⑦ 교육기관의 장은 별표 4에 따른 교육과정을 수료한 사람에게 별지 제16호서식에 따른 수료증을 발급하여야 한다. <개정 2018.7.4>","items":[]},{"no":"⑧","text":"⑧ 교육기관의 장은 다음 각 호의 내용이 포함된 해당 연도의 교육 결과를 매년 12월 31일까지 해양수산부장관에게 보고하여야 한다.","items":[{"no":"1.","text":"1. 교육일시ㆍ장소 및 교육 예상인원 대비 교육 참석인원"},{"no":"2.","text":"2. 교육과목, 교육시간 및 강사"}]}]},"제21조":{"title":"선박수리 허가의 신청 등","head":"제21조(선박수리 허가의 신청 등)","paras":[{"no":"①","text":"① 법 제37조제1항 각 호 외의 부분 본문에 따라 선박수리 허가를 받으려는 선장 또는 같은 조 제3항에 따라 선박수리를 신고하려는 선장은 별지 제17호서식에 따른 선박수리 허가신청서ㆍ신고서에 다음 각 호의 서류를 첨부하여 지방해양수산청장 또는 시ㆍ도지사에게 제출하여야 한다.","items":[{"no":"1.","text":"1. 작업계획서(취급장비 명세를 포함한다)"},{"no":"2.","text":"2. 해당 작업에 필요한 작업자의 자격증 사본 1부(수리 대상 선박의 선원이 작업자인 경우는 제외한다)"}]},{"no":"②","text":"② 지방해양수산청장 또는 시ㆍ도지사는 제1항에 따라 신청받은 선박수리를 허가하거나 선박수리의 신고를 받은 경우에는 별지 제17호서식에 따른 선박수리 허가신청서ㆍ신고서의 확인란에 날인하여 신청인에게 발급하여야 한다.","items":[]},{"no":"③","text":"③ 법 제37조제1항 각 호 외의 부분 단서에서 \"해양수산부령으로 정하는 선박 내 위험구역\"이란 다음 각 호의 어느 하나에 해당하는 선박 내 구역을 말한다.","items":[{"no":"1.","text":"1. 윤활유탱크"},{"no":"2.","text":"2. 코퍼댐(coffer dam)"},{"no":"3.","text":"3. 공소(空所)"},{"no":"4.","text":"4. 축전지실"},{"no":"5.","text":"5. 페인트 창고"},{"no":"6.","text":"6. 가연성 액체를 보관하는 창고"},{"no":"7.","text":"7. 폐위(閉圍)된 차량구역"}]},{"no":"④","text":"④ 법 제37조제6항에 따라 지방해양수산청장 또는 시ㆍ도지사가 명할 수 있는 안전에 필요한 조치는 다음 각 호와 같다. <개정 2019.7.16>","items":[{"no":"1.","text":"1. 안전시설 및 인원의 보강"},{"no":"2.","text":"2. 작업시간의 조정"},{"no":"3.","text":"3. 수리장소의 일시적 변경"},{"no":"4.","text":"4. 그 밖에 선박안전을 위하여 필요한 사항"}]}]},"제22조":{"title":"위험 예방조치의 요청 등","head":"제22조(위험 예방조치의 요청 등)","paras":[{"no":"①","text":"① 법 제39조제2항에 따라 조난선(遭難船)의 선장이 「항로표지법」 제2조제1호에 따른 항로표지(이하 \"항로표지\"라 한다)의 설치나 그 밖에 다른 선박에 대한 위험을 예방하기 위하여 필요한 조치를 요청하는 경우에는 별지 제18호서식에 따른 위험 예방조치 요청서를 지방해양수산청장 또는 시ㆍ도지사에게 제출하여야 한다. 다만, 긴급한 경우에는 구두로 요청할 수 있다. <개정 2018.5.1>","items":[]},{"no":"②","text":"② 지방해양수산청장 또는 시ㆍ도지사는 제1항 단서에 따라 조난선 선장의 구두 요청을 받아 법 제39조제1항에 따른 위험 예방조치를 한 경우에는 제23조에 따른 위험 예방조치 비용의 산정을 위한 관계 서류의 보완을 해당 조난선의 선장에게 요청할 수 있다.","items":[]}]},"제23조":{"title":"위험 예방조치 비용의 산정 및 납부","head":"제23조(위험 예방조치 비용의 산정 및 납부)","paras":[{"no":"①","text":"① 법 제39조제3항에 따른 위험 예방조치 비용의 산정방법은 「항로표지법」 제14조제5항에 따른다. <개정 2018.5.1>","items":[]},{"no":"②","text":"② 법 제39조제3항에 따라 선박의 소유자 또는 임차인은 제1항에 따라 산정된 위험 예방조치 비용을 항로표지의 설치 등 위험 예방조치가 종료된 날부터 5일 이내에 지방해양수산청장 또는 시ㆍ도지사에게 납부하여야 한다.","items":[]}]},"제24조":{"title":"공매대행 수수료","head":"제24조(공매대행 수수료) 법 제40조제7항에 따른 수수료의 지급에 관해서는 「국세징수법 시행규칙」 제41조의5제1항 및 제2항을 준용한다.","paras":[]},"제25조":{"title":"공사 등의 허가 신청","head":"제25조(공사 등의 허가 신청)","paras":[{"no":"①","text":"① 법 제41조제1항에 따라 공사 또는 작업을 허가를 받으려는 자는 별지 제19호서식에 따른 공사ㆍ작업 허가신청서에 다음 각 호의 서류를 첨부하여 지방해양수산청장 또는 시ㆍ도지사에게 제출하여야 한다.","items":[{"no":"1.","text":"1. 작업계획서(취급장비 명세를 포함한다)"},{"no":"2.","text":"2. 해당 작업에 필요한 작업자의 자격증 사본 1부"}]},{"no":"②","text":"② 지방해양수산청장 또는 시ㆍ도지사는 제1항에 따라 신청을 받은 공사 또는 작업을 허가한 경우에는 별지 제19호서식에 따른 공사ㆍ작업 허가신청서의 확인란에 날인하여 신청인에게 발급하여야 한다.","items":[]}]},"제26조":{"title":"공사 등의 허가 범위","head":"제26조(공사 등의 허가 범위) 영 제18조제3호에서 \"해양수산부령으로 정하는 공사 또는 작업\"이란 「해양환경관리법 시행규칙」 별표 1 제1호에 따른 해양시설에 대하여 불꽃이나 열이 발생하는 용접 등의 방법으로 수리하는 공사 또는 작업을 말한다.","paras":[]},"제27조":{"title":"행사의 허가 신청","head":"제27조(행사의 허가 신청)","paras":[{"no":"①","text":"① 법 제42조제1항에 따라 선박경기 등의 행사 허가를 받으려는 자는 별지 제20호서식에 따른 행사 허가신청서에 행사계획서(위치도를 포함한다)를 첨부하여 지방해양수산청장 또는 시ㆍ도지사에게 제출하여야 한다.","items":[]},{"no":"②","text":"② 지방해양수산청장 또는 시ㆍ도지사는 제1항에 따라 신청받은 행사를 허가하는 경우 별지 제20호서식에 따른 행사 허가신청서의 확인란에 날인하여 신청인에게 발급하여야 한다.","items":[]}]},"제28조":{"title":"부유 등의 허가 신청","head":"제28조(부유 등의 허가 신청)","paras":[{"no":"①","text":"① 법 제43조제1항에 따라 무역항의 수상구역등에서 목재 등 선박교통의 안전에 장애가 되는 부유물(이하 \"부유물\"이라 한다)을 수상(水上)에 띄워 놓거나 운반 등을 하려는 자는 별지 제21호서식에 따른 부유 등 허가신청서를 지방해양수산청장 또는 시ㆍ도지사에게 제출하여야 한다.","items":[]},{"no":"②","text":"② 지방해양수산청장 또는 시ㆍ도지사는 제1항에 따라 신청을 받은 부유물의 부유 또는 운반 등을 허가한 경우에는 별지 제21호서식에 따른 부유 등 허가신청서의 확인란에 날인하여 신청인에게 발급하여야 한다.","items":[]}]},"제29조":{"title":"화재 시 경보방법","head":"제29조(화재 시 경보방법)","paras":[{"no":"①","text":"① 법 제46조제2항에 따라 화재를 알리는 경보는 기적(汽笛)이나 사이렌을 장음(4초에서 6초까지의 시간 동안 계속되는 울림을 말한다)으로 5회 울려야 한다.","items":[]},{"no":"②","text":"② 제1항의 경보는 적당한 간격을 두고 반복하여야 한다.","items":[]}]},"제30조":{"title":"출항 중지 통지서의 발급","head":"제30조(출항 중지 통지서의 발급)","paras":[{"no":"①","text":"① 지방해양수산청장 또는 시ㆍ도지사는 법 제47조에 따라 선박의 출항을 중지시키는 경우에는 별지 제22호서식에 따른 선박 출항 중지 통지서를 해당 선박의 선장에게 발급하여야 한다. 다만, 시간적 여유가 없거나 그 밖의 부득이한 경우에는 구두로 통보할 수 있다.","items":[]},{"no":"②","text":"② 지방해양수산청장 또는 시ㆍ도지사는 제1항 단서에 따라 구두로 선박의 출항 중지를 통보한 경우에는 지체 없이 제1항에 따른 선박 출항 중지 통지서를 해당 선박의 선장에게 발급하여야 한다.","items":[]}]},"제31조":{"title":"증표","head":"제31조(증표) 법 제48조제3항에 따라 선박에 출입하여 관계 서류 등을 검사ㆍ확인하는 공무원의 권한을 표시하는 증표는 별지 제23호서식에 따른다.","paras":[]},"제32조":{"title":"그 밖의 개선명령","head":"제32조(그 밖의 개선명령) 법 제49조제7호에서 \"해양수산부령으로 정하는 사항\"이란 다음 각 호의 사항을 말한다.","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 무역항의 수상구역등에서 선박 또는 승무원 및 승객에 대한 일시적인 출입제한"},{"no":"2.","text":"2. 작업 또는 행사의 일시적인 제한"},{"no":"3.","text":"3. 공사 또는 수리계획의 변경"}]}]},"제33조":{"title":"중계망사업자의 지정기준 등","head":"제33조(중계망사업자의 지정기준 등)","paras":[{"no":"①","text":"① 법 제50조제2항에 따른 중계망사업자(이하 \"중계망사업자\"라 한다)의 지정기준은 다음 각 호와 같다.","items":[{"no":"1.","text":"1. 「상법」에 따른 주식회사일 것"},{"no":"2.","text":"2. 납입자본금이 50억원 이상일 것"},{"no":"3.","text":"3. 법 제50조제2항에 따라 항만운영정보시스템과 사용자의 전자문서를 중계하는 망사업(이하 \"중계망사업\"이라 한다)을 영위하기 위하여 필요한 다음 각 목의 설비를 갖추거나 해당 설비에 대한 정당한 사용권을 가질 것 가. 중계망사업을 안정적으로 수행할 수 있는 충분한 속도 및 용량을 갖춘 전산설비\n 나. 전자문서를 변환ㆍ처리ㆍ전송 및 보관할 수 있는 소프트웨어\n 다. 전자문서를 전달하려는 자의 전산처리설비부터 해양수산부의 전산처리설비까지 전자문서를 안전하게 전송할 수 있는 통신설비 및 통신망\n 라. 전자문서의 변환ㆍ처리ㆍ전송ㆍ보관 및 데이터베이스의 안전한 운영과 보안을 위한 전산설비 및 소프트웨어\n 마. 전자문서 중계업무의 처리가 불가능한 경우를 대비한 원격지 재해복구시스템"},{"no":"4.","text":"4. 중계망사업을 영위하기 위하여 필요한 다음 각 목의 기술인력을 보유할 것 가. 중계망사업을 위한 표준전자문서의 개발 또는 전자문서 중계방식과 관련한 기술 분야에서 근무경력이 2년 이상인 사람 10명 이상\n 나. 전자문서와 데이터베이스의 보안 관리를 위한 전문요원 3명 이상"}]},{"no":"②","text":"② 제1항제3호 각 목 및 제4호 각 목의 세부적인 사항은 해양수산부장관이 정하여 고시한다.","items":[]},{"no":"③","text":"③ 중계망사업자로 지정을 받으려는 자는 별지 제24호서식에 따른 중계망사업자 지정신청서에 다음 각 호의 서류를 첨부하여 해양수산부장관에게 제출하여야 한다. 지정받은 사항을 변경하려는 경우에도 또한 같다.","items":[{"no":"1.","text":"1. 정관"},{"no":"2.","text":"2. 자본금ㆍ주주 현황 등 사업자의 일반 현황을 기재한 서류"},{"no":"3.","text":"3. 제1항제3호에 따른 설비를 갖추었음을 증명하는 서류"},{"no":"4.","text":"4. 제1항제4호에 따른 인력을 갖추었음을 증명하는 서류"},{"no":"5.","text":"5. 임원의 신원증명서"},{"no":"6.","text":"6. 사업계획서"},{"no":"7.","text":"7. 전자문서 중계망 운영에 관한 업무설명서"}]},{"no":"④","text":"④ 제3항에 따른 중계망사업자 지정신청서를 제출받은 해양수산부장관은 「전자정부법」 제36조제1항에 따른 행정정보의 공동이용을 통하여 신청인의 법인 등기사항증명서 및 외국인등록사실증명(외국인인 임원의 경우로서 신원증명서에 갈음하는 경우만 해당한다)을 확인하여야 한다. 다만, 신고인이 행정정보의 공동이용을 통한 외국인등록사실증명의 확인에 동의하지 아니하는 경우에는 그 사본을 첨부하게 하여야 한다.","items":[]},{"no":"⑤","text":"⑤ 해양수산부장관은 법 제50조제2항에 따라 중계망사업자를 지정한 경우에는 별지 제25호서식에 따른 중계망사업자 지정서를 신청인에게 발급하고, 그 지정사실을 관계 기관의 장에게 통지하여야 한다.","items":[]}]},"제34조":{"title":"수수료","head":"제34조(수수료)","paras":[{"no":"①","text":"① 법 제51조에 따른 수수료는 별표 5와 같다.","items":[]},{"no":"②","text":"② 제1항에 따른 수수료는 수입인지, 현금, 전자화폐 또는 전자결제 등의 방법으로 납부할 수 있다.","items":[]}]},"제35조":{"title":"규제의 재검토","head":"제35조(규제의 재검토) 해양수산부장관은 제10조에 따른 예선업의 등록 신청 등에 대하여 2016년 1월 1일을 기준으로 3년마다(매 3년이 되는 해의 1월 1일 전까지를 말한다) 그 타당성을 검토하여 개선 등의 조치를 해야 한다.","paras":[]}}},"hazmat":{"id":"hazmat","name":"위험물 선박운송 및 저장규칙","effective":"20220518","promulgated":"20220217","articles":{"제1조":{"title":"목적","head":"제1조(목적) 이 규칙은 「선박안전법」 제41조, 제41조의2 및 제65조에 따른 선박에 의한 위험물의 운송 및 저장, 위험물 취급자에 대한 위험물 안전운송 교육과 상용위험물의 취급에 관한 사항을 규정함을 목적으로 한다.","paras":[]},"제2조":{"title":"정의","head":"제2조(정의) 이 규칙에서 사용하는 용어의 뜻은 다음과 같다. <개정 2013.1.23, 2013.3.24, 2015.3.10, 2018.3.12, 2020.6.1, 2021.6.30>","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. \"위험물\"이란 다음 각 목에서 정하는 것을 말한다. 가. 화약류: 다음에 정하는 폭발성 물질(화학반응으로 주위환경에 손상을 줄 수 있는 온도ㆍ압력 및 속도를 가진 가스를 발생시키는 고체 물질, 액체 물질 또는 그 혼합물을 말한다. 이하 같다) 및 폭발성 제품(한 종류이상의 폭발성 물질을 포함한 제품을 말한다. 이하 같다)으로서 해양수산부장관이 고시하는 것\n   1) 대폭발(발화 시 해당 폭발성 물질 또는 폭발성 제품의 대부분이 동시에 폭발하는 것을 말한다. 이하 같다) 위험성이 있는 폭발성 물질 및 폭발성 제품\n   2) 대폭발위험성은 없으나 분사(발화 시 해당 폭발성 물질 또는 폭발성 제품이 연소되면서 빠른 속도로 가스를 내뿜는 것을 말한다. 이하 같다) 위험성이 있는 폭발성 물질 및 폭발성 제품\n   3) 대폭발위험성은 없으나 화재위험성ㆍ폭발위험성 또는 분사위험성이 있는 폭발성 물질 및 폭발성 제품: 화재 시 상당한 복사열을 발산하거나 약한 폭발 또는 분사를 하면서 연소되는 폭발성 물질 및 폭발성 제품\n   4) 대폭발위험성ㆍ분사위험성 또는 화재위험성은 적으나 민감한 폭발성 물질 및 폭발성 제품: 운송 중 발화하는 경우 위험성이 적은 폭발성 물질 및 폭발성 제품\n   5) 대폭발위험성이 있는 매우 둔감한 폭발성 물질: 대폭발위험성은 있으나 매우 둔감하여 통상적인 운송조건에서는 발화하기 어렵고 화재가 나도 폭발하기 어려운 폭발성 물질\n   6) 대폭발위험성이 없는 극히 둔감한 폭발성 제품: 극히 둔감한 폭발성 물질을 주성분으로 하여 만들어진 것으로서 우발적으로 발화하기 어려운 폭발성 제품\n 나. 고압가스: 섭씨 50도에서 0.30메가파스칼을 초과하는 증기압을 가진 물질 또는 섭씨 20도 및 압력 0.1013메가파스칼에서 완전히 기체인 물질 중 다음에 정하는 물질로서 해양수산부장관이 고시하는 것\n   1) 인화성 가스: 섭씨 20도와 압력 0.1013메가파스칼에서 해당 가스가 공기 중에 용적비로 13퍼센트 이하 혼합된 경우에도 발화되는 가스와 공기 중에서 인화될 수 있는 가스 농도의 최대값과 최소값의 차이가 12퍼센트 이상인 가스\n   2) 비(非) 인화성ㆍ비 독성 가스: 인화성 가스 또는 독성 가스가 아닌 가스\n   3) 독성 가스: 해당 가스를 흰쥐의 입을 통하여 투여한 경우 또는 피부에 24시간 동안 계속하여 접촉시키거나 1시간 동안 계속하여 흡입시킨 경우 그 흰쥐의 2분의 1 이상이 14일 이내에 죽게 되는 독량이 1세제곱미터당 5리터 이하인 가스\n 다. 인화성 액체류: 다음에 정하는 인화성 액체로서 해양수산부장관이 고시하는 것\n   1) 저인화점 인화성 액체: 인화점(밀폐용기 시험에 의한 인화점을 말한다. 이하 같다)이 섭씨 영하 18도 미만인 액체\n   2) 중인화점 인화성 액체: 인화점이 섭씨 영하 18도 이상 섭씨 23도 미만인 액체\n   3) 고인화점 인화성 액체: 인화점이 섭씨 23도 이상 섭씨 60도 이하인 액체(인화점이 섭씨 35도를 초과하는 액체로서 연소지속성이 없는 경우는 제외한다) 또는 인화점이 섭씨 60도를 초과하는 액체로서 인화점 이상의 온도로 운송되는 액체\n 라. 가연성 물질류: 다음의 물질로서 해양수산부장관이 고시하는 것\n   1) 가연성 물질: 화기 등으로 쉽게 점화되거나 연소하기 쉬운 물질, 자체반응 물질과 중합성(重合性) 물질 및 둔감화된 화약류\n   2) 자연발화성 물질: 자연발열이나 자연발화하기 쉬운 물질\n   3) 물 반응성 물질: 물과 반응하여 인화성 가스를 발생하는 물질\n 마. 산화성 물질류: 다음의 물질로서 해양수산부장관이 고시하는 것과 제200조 각 호에서 정하는 것\n   1) 산화성 물질: 다른 물질을 산화시키는 성질을 가진 물질(유기과산화물은 제외한다)\n   2) 유기과산화물: 쉽게 활성산소를 방출하여 다른 물질을 산화시키는 성질을 가진 유기물질\n 바. 독물류: 다음에서 정하는 것\n   1) 독물: 인체에 독작용을 미치는 물질로서 해양수산부장관이 고시하는 것\n   2) 병독(病毒)을 옮기기 쉬운 물질: 살아있는 병원체, 살아있는 병원체를 함유하고 있는 물질이나 살아있는 병원체가 붙어있다고 인정되는 것\n 사. 방사성 물질: 「원자력안전법」 제2조제5호에 따른 방사성물질(방사성물질에 오염된 것을 포함한다)\n 아. 부식성(腐蝕性) 물질: 부식성을 가진 물질로서 해양수산부장관이 고시하는 것\n 자. 유해성 물질: 가목부터 아목까지의 물질 외에 사람에게 해를 끼치거나 다른 물건을 손상시킬 우려가 있는 물질로서 해양수산부장관이 고시하는 것"},{"no":"2.","text":"2. \"산적액체위험물\"이란 산적(散積)하여 운송되는 액체 물질로서 다음 각 목에서 정하는 것을 말한다. 가. 액화가스 물질: 섭씨 37.8도에서 0.28메가파스칼을 넘는 증기압력을 갖는 액체 및 이와 유사한 성질ㆍ상태를 갖는 물질\n 나. 액체 화학품: 섭씨 37.8도에서 0.28메가파스칼 이하의 증기압력을 갖는 물질로서 다음의 성질을 갖는 액체 상태의 물질(「해양환경관리법」 제2조에 따른 기름은 제외한다)\n   1) 부식성\n   2) 인체에 대한 독성\n   3) 인화성\n   4) 자연발화성\n   5) 위험한 반응성\n 다. 인화성 액체 물질: 다음에서 정하는 것\n   1) 인화성 액체류로서 가목과 나목에서 정한 물질 외의 액체 상태 물질\n   2) 「해양환경관리법」 제2조제5호에 따른 기름 중 액체 상태 물질(인화성 액체류는 제외한다)\n 라. 유해성 액체 물질: 유해성 물질로서 가목부터 다목까지에서 정하는 물질 외의 액체 상태 물질"},{"no":"3.","text":"3. \"상용위험물\"이란 선박의 항해나 인명의 안전을 유지하기 위하여 해당 선박에서 사용하는 위험물을 말한다."},{"no":"4.","text":"4. \"소형용기\"란 용기의 용적이 450리터 이하의 용기로서 중형산적용기 외의 용기를 말한다."},{"no":"5.","text":"5. \"중형산적용기\"란 금속 용기ㆍ연성형(軟性形) 용기ㆍ경질(硬質) 플라스틱 용기ㆍ플라스틱 내용기를 수납한 복합용기ㆍ화이버보드(FIBER BOARD) 용기 또는 목재 용기로서 해양수산부장관이 고시하는 것을 말한다."},{"no":"6.","text":"6. \"대형용기\"란 하역(荷役)장치 사용에 적합하게 설계된 것으로서 용적이 450리터를 넘거나 허용순질량이 400킬로그램을 넘는 용기로서 용적이 3세제곱미터 이하인 용기를 말한다."},{"no":"7.","text":"7. \"대형금속용기\"란 용기의 용적이 450리터를 넘는 금속용기로서 중형산적용기 외의 용기를 말한다."},{"no":"7.","text":"7의2. \"금속수소화물 저장장치\"란 수소를 운송하기 위하여 금속과 수소의 화학반응에 의한 화합물을 저장하는 용기를 말하며, 금속수소화물, 압력안전장치, 차단밸브, 부속설비 및 내부 부속품을 포함한다."},{"no":"8.","text":"8. \"압력용기\"란 고압가스를 수납하는 용기로서 실린더ㆍ튜브ㆍ압력드럼ㆍ밀폐저온용기ㆍ실린더 다발 및 금속수소화물 저장장치를 말한다."},{"no":"9.","text":"9. \"집합형압력용기\"란 매니폴드(여러 개의 가지관)로 서로 연결되어 있는 실린더ㆍ튜브 및 실린더 다발의 집합체를 말한다."},{"no":"10.","text":"10. \"갑판상부적재\"란 위험물을 노출갑판 위에 적재하는 것과 개방된 선루(船樓), 갑판실 또는 이와 유사한 장소에 적재하는 것을 말한다."},{"no":"11.","text":"11. \"갑판하부적재\"란 갑판상부적재 외의 적재를 말한다."},{"no":"12.","text":"12. \"탱커\"란 위험물인 액체 화물을 선체의 일부를 구성하는 탱크에 산적하여 운송하거나 저장하는 선박을 말한다. 다만, 부선(艀船)은 제외한다."},{"no":"13.","text":"13. \"탱크선\"이란 위험물인 액체 화물을 선체의 일부를 구성하지 아니하는 탱크(노출갑판 상부에 설치한 것은 제외한다)에 산적하여 운송하거나 저장하는 선박을 말한다. 다만, 부선은 제외한다."},{"no":"14.","text":"14. 삭제<2018.3.12>"},{"no":"15.","text":"15. \"탱크컨테이너\"란 위험물인 액체 또는 기체의 화물을 직접 수용하는 컨테이너를 말한다."},{"no":"16.","text":"16. \"외장용기\"란 하나의 용기 안에 하나 이상의 용기를 수납하는 경우 가장 바깥쪽의 용기를 말하며, 그 안쪽의 용기를 수납하고 보호하기 위하여 사용된 흡수재와 완충재를 포함한다."},{"no":"17.","text":"17. \"내용기\"란 수납을 위하여 외장용기를 필요로 하는 용기를 말한다."},{"no":"18.","text":"18. \"내장용기\"란 운송을 위하여 외장용기를 필요로 하는 용기를 말한다."},{"no":"19.","text":"19. \"중간용기\"란 내장용기와 외장용기 또는 위험물과 외장용기의 사이에 사용되는 용기를 말한다."},{"no":"20.","text":"20. \"결합용기\"란 운송을 위하여 외장용기 안에 1개 이상의 내장용기를 수납한 용기를 말한다."},{"no":"21.","text":"21. \"단일용기\"란 결합용기 외의 용기를 말한다."},{"no":"22.","text":"22. \"복합용기\"란 하나의 외장용기 안에 하나의 내용기를 수납함으로써 하나의 완전한 용기를 구성하여 그 상태로 운송에 사용되는 용기를 말한다."},{"no":"23.","text":"23. \"회수용기\"란 손상되거나 결함이 있는 위험물 용기 또는 유출된 위험물을 회수ㆍ폐기 또는 운송하기 위한 용기를 말한다."},{"no":"23.","text":"23의2. \"회수압력용기\"란 손상이나 결함이 있는 등 부적합한 상태인 압력용기를 회수 또는 처분하기 위해 운송하는 경우에 사용하는 압력용기를 말한다."},{"no":"24.","text":"24. \"V표시 용기\"란 내장용기의 종류와 관계없이 결합용기를 구성할 수 있는 외장용기를 말한다."},{"no":"25.","text":"25. \"W표시 용기\"란 해양수산부장관이 고시하는 소형용기, 중형산적용기 및 대형용기의 설계 및 구조기준과 일치하지 아니하나, 제205조의2에 따른 용기 및 포장의 안전성에 대한 검사기준에 적합한 용기를 말한다."},{"no":"26.","text":"26. \"순화약질량\"(純火藥質量)이란 포장용기, 외피(casing) 및 이와 유사한 것을 제외한 화약류의 질량을 말한다."},{"no":"27.","text":"27. \"중합성 물질\"이란 안정화되지 않은 상태에서 더 큰 분자 또는 중합체(重合體)를 형성하여 강한 발열반응을 일으킬 수 있는 물질을 말한다."},{"no":"28.","text":"28. \"덧 포장\"(OVERPACK)이란 단일 송하인이 운송 중 취급과 적재의 편의를 위해 1개 이상의 포장화물을 하나의 단위(UNIT)로 추가 포장한 것을 말한다."},{"no":"29.","text":"29. \"제어온도\"(Control temperature)란 위험물을 안전하게 운송할 수 있는 최고 온도를 말한다."},{"no":"30.","text":"30. \"비상온도\"(Emergency temperature)란 위험물의 온도 제어에 실패하여 비상절차를 이행해야 하는 온도를 말한다."}]}]},"제3조":{"title":"위험물의 분류","head":"제3조(위험물의 분류) 위험물은 다음 각 호와 같이 분류한다.","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 제1급 화약류 가. 등급 1.1: 대폭발위험성이 있는 폭발성 물질 및 폭발성 제품\n 나. 등급 1.2: 대폭발위험성은 없으나 분사위험성이 있는 폭발성 물질 및 폭발성 제품\n 다. 등급 1.3: 대폭발위험성은 없으나 화재위험성ㆍ폭발위험성 또는 분사위험성이 있는 폭발성 물질 및 폭발성 제품\n 라. 등급 1.4: 대폭발위험성ㆍ분사위험성 또는 화재위험성은 적으나 민감한 폭발성 물질 및 폭발성 제품\n 마. 등급 1.5: 대폭발위험성이 있는 매우 둔감한 폭발성 물질\n 바. 등급 1.6: 대폭발위험성이 없는 극히 둔감한 폭발성 제품"},{"no":"2.","text":"2. 제2급 고압가스 가. 제2.1급: 인화성 가스\n 나. 제2.2급: 비(非) 인화성ㆍ비 독성 가스\n 다. 제2.3급: 독성가스"},{"no":"3.","text":"3. 제3급 인화성 액체류"},{"no":"4.","text":"4. 제4급 가연성 물질류 가. 제4.1급: 가연성 물질\n 나. 제4.2급: 자연발화성 물질\n 다. 제4.3급: 물 반응성 물질"},{"no":"5.","text":"5. 제5급 산화성 물질류 가. 제5.1급: 산화성 물질\n 나. 제5.2급: 유기과산화물"},{"no":"6.","text":"6. 제6급 독물류 가. 제6.1급: 독물\n 나. 제6.2급: 병독을 옮기기 쉬운 물질"},{"no":"7.","text":"7. 제7급 방사성 물질"},{"no":"8.","text":"8. 제8급 부식성 물질"},{"no":"9.","text":"9. 제9급 유해성 물질"}]}]},"제4조":{"title":"반입의 제한","head":"제4조(반입의 제한)","paras":[{"no":"①","text":"① 다음 각 호의 경우를 제외하고는 상용위험물 외의 위험물은 선박에 반입해서는 아니 된다. <개정 2013.3.24>","items":[{"no":"1.","text":"1. 위험물을 운송하거나 저장하기 위해 선박에 반입하는 경우"},{"no":"2.","text":"2. 해양수산부장관이 정하는 위험물을 선장의 허가를 받아 반입하는 경우"},{"no":"3.","text":"3. 제1호 및 제2호에서 규정한 경우 외에 법령으로 정하는 경우"}]},{"no":"②","text":"② 선장은 제1항제2호에 따른 허가를 할 경우에는 해당 위험물의 용기ㆍ포장 및 적재장소에 관하여 필요한 지시를 할 수 있다.","items":[]}]},"제5조":{"title":"공사 등","head":"제5조(공사 등)","paras":[{"no":"①","text":"① 화약류를 적재하거나 저장한 선박에서는 공사[용접, 리벳(둥근 버섯모양의 굵은 못) 용접 또는 그 밖에 불꽃이나 발열을 수반하는 공사를 말한다. 이하 같다]를 해서는 안 된다. <개정 2021.6.30>","items":[]},{"no":"②","text":"② 화약류 외의 위험물이나 인화성 또는 폭발성이 있는 증기를 발생하는 물질을 적재하였거나 저장하고 있는 화물창(貨物艙)이나 구획 또는 이에 인접한 장소에서 공사를 해서는 아니 된다.","items":[]},{"no":"③","text":"③ 화약류ㆍ산화성 물질류 또는 가연성 물질류를 적재하거나 저장하였던 화물창이나 구획에서 공사를 할 경우에는, 공사시행자는 사전에 해당 위험물의 잔재물로 인한 폭발 또는 화재의 위험에 대하여 선박소유자나 선장의 확인을 받아야 한다.","items":[]},{"no":"④","text":"④ 인화성 액체류나 인화성 또는 폭발성이 있는 증기를 발생하는 물질을 적재하거나 저장하였던 화물창이나 구획에서 공사나 청소, 그 밖의 작업을 할 경우에는 공사시행자나 그 밖의 작업시행자는 사전에 가스를 측정하여, 폭발 또는 화재의 위험에 대하여 선박소유자나 선장의 확인을 받아야 한다.","items":[]},{"no":"⑤","text":"⑤ 제1항과 제2항은 상용위험물에 대해서는 적용하지 아니한다. 이 경우 공사시행자가 사전에 폭발이나 화재의 위험이 없음을 확인하여야 한다.","items":[]},{"no":"⑥","text":"⑥ 고압가스, 부식성 물질, 독물 및 인화성 액체류로서 인체에 유해한 가스가 발생되는 것을 적재하였거나 저장하였던 탱커, 탱크선 또는 부선의 탱크 안에서 공사, 청소 또는 그 밖의 작업을 할 경우에는 공사시행자나 그 밖의 작업시행자는 사전에 가스를 측정하고, 해당 탱크 안에 위험한 양(量)의 가스가 없음을 확인하여야 한다.","items":[]}]},"제5조의2":{"title":"빈 용기","head":"제5조의2(빈 용기) 위험물(방사성물질은 제외한다. 다만 제20조제1항의 경우에는 방사성물질을 포함한다. 이하 같다)의 운송 또는 저장에 사용되었던 빈 용기가 세정되지 아니하여 잔류 위험물이 남아 있는 경우에는 해당 위험물이 들어있는 용기로 보고 이 규칙(제204조와 제205조는 제외한다)을 적용한다.","paras":[]},"제6조":{"title":"용기ㆍ포장ㆍ표시ㆍ적재방법 등","head":"제6조(용기ㆍ포장ㆍ표시ㆍ적재방법 등)","paras":[{"no":"①","text":"① 선박으로 위험물을 운송하는 경우에 송하인(送荷人, 타인에게 운송을 위탁하지 아니하고 운송하는 경우의 본인을 포함한다. 이하 같다)은 그 용기ㆍ포장 및 별지 제1호도식의 표찰에 대해, 선장은 그 적재방법에 대해 위험물별로 해양수산부장관이 정하는 기준에 따라야 한다. <개정 2013.3.24>","items":[]},{"no":"②","text":"② 제1항의 송하인은 해당 운송이 국제항해(「선박안전법 시행규칙」 제2조제4호에 따른 국제항해를 말한다. 이하 같다)에 관련되는 경우에는 위험물의 용기(포장되어 있는 경우를 제외한다) 또는 포장에 해당 위험물의 품명 및 국제연합번호(화약류에 대해서는 품명ㆍ국제연합번호ㆍ순화약질량 및 총질량을 말한다)를 표시해야 하며, 덧 포장한 경우에는 덧 포장에도 해당 사항을 표시하고 \"덧 포장(OVERPACK)\" 표시를 해야 한다. <개정 2018.3.12, 2020.6.1>","items":[]},{"no":"③","text":"③ 제1항의 송하인은 해양수산부장관이 정하는 위험물 외의 위험물을 소형용기ㆍ중형산적용기ㆍ대형용기ㆍ대형금속용기ㆍ압력용기 또는 집합형압력용기로 운송하는 경우에는 다음 각 호의 어느 하나에 해당하는 용기를 사용하여야 한다. <개정 2013.3.24>","items":[{"no":"1.","text":"1. 제205조의2에 따른 용기 검사를 받고 검사 합격 표시가 붙어 있는 용기"},{"no":"2.","text":"2. 「해상에서의 인명안전을 위한 국제협약」을 체결한 국가의 정부가 위험물의 용기에 관한 해당 국가의 법령에 적합하다고 인정하는 유효한 증명 또는 표시가 되어 있는 용기"}]},{"no":"④","text":"④ 제1항에 따른 표찰, 제2항에 따른 품명 및 국제연합번호의 표시는 해당 표찰 또는 표시가 3개월간 바닷물에 잠긴 후에도 그 기재내용을 식별할 수 있는 것이어야 한다.","items":[]},{"no":"⑤","text":"⑤ 해양수산부장관은 제3항에 따른 다음 각 호의 용기에 대하여 용기를 사용할 수 있는 위험물의 종류, 용기의 종류 또는 사용기준, 위험물의 국제연합번호, 용기등급 및 사고 시 비상조치에 관한 사항을 정하여 고시한다. <개정 2013.3.24>","items":[{"no":"1.","text":"1. 소형용기"},{"no":"2.","text":"2. 중형산적용기"},{"no":"3.","text":"3. 대형용기"},{"no":"4.","text":"4. 대형금속용기"},{"no":"5.","text":"5. 압력용기"},{"no":"6.","text":"6. 집합형압력용기"}]},{"no":"⑥","text":"⑥ 대형금속용기의 표시와 표찰에 관하여는 제33조를 준용한다.","items":[]},{"no":"⑦","text":"⑦ 컨테이너에 냉각이나 온도조절을 목적으로 사용하는 위험물이 투입된 용기나 포장을 수납하는 경우에는 해당 용기나 포장에 투입된 위험물의 품명을 표시하여야 하고, 위험물의 품명 바로 다음에 \"AS COOLANT\" 또는 \"AS CONDITIONER\" 문자를 기재하여야 한다. <신설 2015.3.10>","items":[]},{"no":"⑧","text":"⑧ 회수압력용기는 수용량이 3천 리터를 초과해서는 안 된다. <신설 2020.6.1>","items":[]}]},"제7조":{"title":"용기 및 포장의 특례","head":"제7조(용기 및 포장의 특례) 제6조의 용기 및 포장에 관한 규정에도 불구하고 해양수산부장관이 정하는 위험물을 국내 각 항간에서 운송하는 경우에는 해양수산부장관이 정하는 용기 또는 포장으로 할 수 있다. <개정 2013.3.24>","paras":[]},"제8조":{"title":"표찰의 특례","head":"제8조(표찰의 특례)","paras":[{"no":"①","text":"① 제6조의 표찰에 관한 규정에도 불구하고 동일품명의 위험물(가솔린ㆍ석유증유물 및 등유는 제외한다)만을 연해구역(국내 항해만 해당한다. 이하 같다)에서 운송하는 경우나 고압가스ㆍ부식성 물질ㆍ가솔린ㆍ고인화점 인화성액체ㆍ가연성 물질류 또는 산화성 물질을 평수구역(平水區域)에서 운송하는 경우에는 표찰을 생략할 수 있다.","items":[]},{"no":"②","text":"② 제6조의 표찰에 관한 규정에도 불구하고 가솔린, 석유증류물(石油蒸溜物) 및 등유(燈油)만을 연해구역에서 운송할 경우나 이들과 인화성 액체류 외의 석유계생성품(石油系生成品)만을 연해구역에서 운송할 경우에는 표찰을 생략할 수 있다. 다만, 이들의 품명이 용기 또는 포장에 표시되어 있는 경우만 해당한다.","items":[]}]},"제8조의2":{"title":"표시의 특례","head":"제8조의2(표시의 특례) 다음 각 호의 어느 하나에 해당하는 경우에는 제6조의 표시에 관한 규정에도 불구하고 표찰ㆍ품명ㆍ국제연합번호ㆍ순화약질량 및 총질량의 표시를 생략할 수 있다. <개정 2013.3.24, 2018.3.12, 2020.6.1>","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 해양수산부장관이 정하는 소량의 위험물이나 극소량의 위험물로서 용기 또는 포장에 소량의 위험물 또는 극소량의 위험물임을 나타내는 표시가 되어 있거나 품명과 국제연합번호가 표시되어 있는 위험물을 운송하는 경우"},{"no":"2.","text":"2. 위험물을 적재하는 항만을 관할하는 지방해양수산청장(해양수산사무소장을 포함한다. 이하 \"관할지방해양수산청장등\"이라 한다)이 안전에 지장이 없다고 인정한 경우"}]}]},"제9조":{"title":"적재방법의 특례","head":"제9조(적재방법의 특례) 제6조의 적재방법에 관한 규정에도 불구하고 여객선 외의 선박으로 호수ㆍ하천ㆍ항내에서 위험물을 운송하는 경우에는 갑판상부적재할 수 있다.","paras":[]},"제10조":{"title":"적재방법의 특례","head":"제10조(적재방법의 특례)","paras":[{"no":"①","text":"① 위험물을 부선으로써 평수구역과 그 평수구역으로부터 그 부선으로 1시간 내에 도달할 수 있는 구역에서 운송할 경우와 화약고에 적재해야 하는 화약류 외의 위험물을 부선 외의 선박으로서 화물창의 각 현에 갑판이 없는 것 또는 창구의 각 현에서의 갑판의 폭이 그 선박 폭의 10분의 1 이하 또는 60센티미터 이하의 것[이하 \"총해치선(總Hatch船)등\"이라 한다]으로 평수구역에서 운송할 경우에는 제6조의 적재방법에 대한 규정은 적용하지 않는다. 다만, 여객을 승선시키고 있을 경우에는 그렇지 않다. <개정 2021.6.30>","items":[]},{"no":"②","text":"② 제1항에 따라 위험물을 운송하는 경우에는 해당 위험물에 다른 화물 등이 떨어지거나 충돌하지 아니하도록 예방조치를 하고, 직사일광이나 파랑(波浪)에 의한 피해를 방지하기 위하여 해당 위험물을 덮개 등으로 씌워야 한다.","items":[]},{"no":"③","text":"③ 제1항에 따라 총해치선등으로 액화석유가스를 운송하는 경우에는 제62조제2항 및 제148조를 준용한다. <개정 2021.6.30>","items":[]}]},"제11조":{"title":"적재방법의 특례","head":"제11조(적재방법의 특례) 제6조에도 불구하고 해양수산부장관이 정하는 위험물을 해양수산부장관이 정하는 적재방법에 따라 운송하는 경우에는 여객선 외의 선박에 산적하여 운송할 수 있다. 이 경우에는 다음의 각 호에 따라야 한다. <개정 2013.3.24>","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 위험물을 적재하는 장소는 적재하기 전에 청소할 것"},{"no":"2.","text":"2. 동일한 화물창이나 구획에는 동일한 품명의 위험물만을 적재할 것"}]}]},"제12조":{"title":"적재방법의 특례","head":"제12조(적재방법의 특례)","paras":[{"no":"①","text":"① 제6조에도 불구하고 해양수산부장관이 정하는 위험물로서 동일 품명의 위험물을 운송하는 경우에는 비 개방형구조의 금속재 컨테이너에 산적하여 운송할 수 있다. <개정 2013.3.24>","items":[]},{"no":"②","text":"② 위험물을 바다에 폐기하기 위하여 운송하는 경우와 그 밖에 제6조의 적재방법 외의 다른 방법으로 운송하려는 경우로서 관할지방해양수산청장등이 승인한 경우에는 그 다른 방법에 따라 위험물을 적재할 수 있다. <개정 2020.6.1>","items":[]}]},"제13조":{"title":"포장방법","head":"제13조(포장방법)","paras":[{"no":"①","text":"① 위험물의 용기 및 포장은 누출(漏出)이나 손상될 위험이 없고 해당 위험물에 안전한 것이어야 한다.","items":[]},{"no":"②","text":"② 염소산염류(鹽素酸鹽類)나 액체의 폭발성분을 포함한 화약류의 용기 또는 포장으로 사용했던 것은 위험물의 용기 또는 포장에 사용해서는 아니 된다.","items":[]},{"no":"③","text":"③ 액체 상태(液狀)의 위험물이 든 용기를 포장할 경우에 사용하는 흡수재나 완충재는 용기의 이동을 방지하며 항상 용기를 에워싸고 있도록 배치하고, 용기가 파손되는 경우에도 해당 액체 상태의 위험물을 충분히 흡수할 수 있어야 한다. 다만, 해당 위험물을 국내항 간에서 운송할 경우에는 그러하지 아니하다.","items":[]}]},"제14조":{"title":"혼합포장","head":"제14조(혼합포장)","paras":[{"no":"①","text":"① 혼합포장은 혼합포장되는 개개의 용기 또는 포장이 파손될 염려가 없도록 하여야 한다.","items":[]},{"no":"②","text":"② 표찰을 붙여야 할 위험물의 혼합포장에는 혼합포장되는 개개의 용기 또는 포장에 표시된 표찰이 외부에서 쉽게 보일 경우를 제외하고는 해당 위험물을 표시하는 표찰을 붙여야 한다.","items":[]},{"no":"③","text":"③ 품명 및 국제연합번호를 표시하여야 하는 위험물의 혼합포장에는 혼합포장되는 개개의 용기 또는 포장에 표시된 품명 및 국제연합번호가 외부에서 쉽게 보이는 경우 외에는 그 혼합포장의 외부에 해당 위험물의 품명 및 국제연합번호를 표시하여야 한다.","items":[]}]},"제15조":{"title":"혼합포장의 제한","head":"제15조(혼합포장의 제한)","paras":[{"no":"①","text":"① 품명이 다른 위험물 또는 위험물과 위험물 외의 화물이 상호작용으로 발열, 가스 발생, 부식작용 또는 그 밖에 위험한 물리적 작용이나 화학적 작용을 일으킬 우려가 있을 경우에는 혼합포장을 해서는 아니 된다.","items":[]},{"no":"②","text":"② 제20조에 따라 서로 격리되어야 하는 위험물은 혼합포장을 해서는 아니 된다.","items":[]}]},"제16조":{"title":"위험물 명세서 등","head":"제16조(위험물 명세서 등)","paras":[{"no":"①","text":"① 위험물 및 산적액체위험물의 송하인은 운송위탁을 하기 전에 다음 각 호의 사항을 기재한 위험물명세서를 선박소유자 또는 선장에게 제출하여야 한다. 다만, 제27조제6항에 따른 자동차 위험물 명세서나 제34조제1항에 따른 컨테이너 위험물 명세서를 제출하는 경우와 국내 항 간에 위험물을 운송하는 경우에는 그러하지 아니하다. <개정 2018.3.12>","items":[{"no":"1.","text":"1. 송하인의 성명 또는 명칭 및 주소"},{"no":"2.","text":"2. 수하인(受荷人)의 성명 또는 명칭 및 주소(화약류ㆍ고압가스ㆍ독물ㆍ인화성 액체류 중 저인화점 인화성 액체 및 중인화점 인화성 액체 또는 유기과산화물을 운송하는 경우만 해당한다)"},{"no":"3.","text":"3. 위험물의 분류ㆍ항목ㆍ품명ㆍ부(副)위험성(품명에 해당 위험물의 부위험성을 나타내는 말이 없는 경우만 해당한다. 이하 같다)ㆍ국제연합번호ㆍ용기등급 또는 격리구분과 용기 및 포장의 명칭"},{"no":"4.","text":"4. 수량 및 질량(화약류에 대해서는 순화약질량을 말한다) 또는 용적"}]},{"no":"②","text":"② 제1항의 위험물 명세서에는 해당 위험물의 용기, 포장, 표찰 및 표시가 제6조에 적합하고 운송에 적합한 상태에 있음을 덧붙여 적거나 이것을 증명할 서류를 첨부하여야 한다.","items":[]},{"no":"③","text":"③ 위험물을 다른 선박에 옮겨 실을 경우에는 옮겨 주는 선박의 선박소유자 또는 선장은 해당 위험물 명세서를 옮겨 실을 선박의 선박소유자 또는 선장에게 내주어야 한다.","items":[]},{"no":"④","text":"④ 위험물의 송하인은 제1항에 따른 위험물 명세서 외에 위험물의 사고에 대비하기 위하여 필요한 다음 각 호의 사항을 기재한 서류를 선장에게 제출하여야 한다.","items":[{"no":"1.","text":"1. 위험물의 운송 및 취급에 필요한 정보"},{"no":"2.","text":"2. 위험물의 유출 및 화재 등 비상 시의 조치에 관한 사항"},{"no":"3.","text":"3. 위험물 피해에 대한 의료응급조치에 관한 사항"}]},{"no":"⑤","text":"⑤ 선장은 제1항에 따른 위험물명세서가 제출되지 아니하거나 위험물의 안전운송에 지장이 있다고 인정되는 경우에는 해당 위험물의 선적을 거부할 수 있다.","items":[]},{"no":"⑥","text":"⑥ 해당 위험물이 해양오염물질, 폐기물, 소량의 위험물 또는 극소량의 위험물인 경우에는 위험물 명세서에 각각 \"해양오염물질(MARINE POLLUTANT)\" 또는 \"해양오염물질/환경유해물질(MARINE POLLUTANT/ENVIRONMENT HAZARDOUS)\", \"폐기물(WASTE)\", \"소량의 위험물(limited quantity 또는 LTD QTY)\" 또는 \"극소량의 위험물(dangerous goods in excepted quantities)\"로 기재하고, 해당 용기가 회수용기, 회수압력용기 또는 세정되지 아니한 빈 용기(이하 \"비세정빈용기\"라 한다)인 경우에는 위험물 명세서에 각각 \"회수용기(SALVAGE PACKAGING)\", \"회수압력용기(SALVAGE PRESSURE RECEPTACLE)\" 또는 \"비세정빈용기(EMPTY UNCLEANED 또는 RESIDUE- LAST CONTAINED)\"로 기재해야 한다. <개정 2015.3.10, 2018.3.12, 2020.6.1>","items":[]},{"no":"⑦","text":"⑦ 해당 위험물이 다음 각 호의 어느 하나에 해당하는 물질인 경우에는 위험물 명세서에 제어온도와 비상온도를 각각 기재해야 한다. <신설 2020.6.1>","items":[{"no":"1.","text":"1. 운송 중 온도관리가 필요한 제4.1급의 자체반응 물질, 중합성 물질 또는 제5.2급의 유기과산화물"},{"no":"2.","text":"2. 제6조제2항에 따른 품명에 \"안정화된 것(STABILIZED)\"이라는 문구가 포함되어 있는 위험물 중 온도제어를 통해 안정화가 이루어지는 위험물"}]}]},"제17조":{"title":"하역","head":"제17조(하역) 위험물의 선적, 양륙(선박으로부터 화물 등을 육상으로 옮기는 것)이나 그 밖의 하역을 할 경우에 선장 또는 그 직무를 대행하는 사람은 그 하역에 참관해야 한다. <개정 2021.6.30>","paras":[]},"제18조":{"title":"선장의 의무","head":"제18조(선장의 의무)","paras":[{"no":"①","text":"① 선장은 위험물을 선적할 경우에는 그 용기, 포장 및 표찰이 이 규칙에 적합하고 위험물 명세서의 기재사항과 일치한다는 것을 확인하여야 한다.","items":[]},{"no":"②","text":"② 제1항에 따라 확인하는 경우에 그 용기, 포장 및 표찰이 이 규칙에 위반된다고 인정될 경우에는 증인이 참관한 상태에서 포장을 풀어 검사할 수 있다.","items":[]},{"no":"③","text":"③ 선장은 다음 각 호의 위험물 중 화학적으로 불안정한 위험물을 운송하는 경우 송하인이 위험한 분해 또는 중합(重合)반응을 방지하기 위해 온도제어, 반응 억제제 사용 등 적절한 예방조치를 취했는지 확인해야 한다. <신설 2020.6.1>","items":[{"no":"1.","text":"1. 제2급 고압가스"},{"no":"2.","text":"2. 제3급 인화성 액체류"},{"no":"3.","text":"3. 제6.1급 독물"},{"no":"4.","text":"4. 제8급 부식성 물질"}]}]},"제19조":{"title":"적재상의 주의","head":"제19조(적재상의 주의) 방수성이 없는 용기 또는 포장의 위험물을 갑판상부적재하는 경우에는 파랑 등에 따른 피해를 방지하기 위하여 해당 위험물을 덮개 등으로 씌워야 한다.","paras":[]},"제20조":{"title":"위험물의 격리","head":"제20조(위험물의 격리)","paras":[{"no":"①","text":"① 동일한 선박에 분류가 다르거나 항목이 다른 위험물을 적재하는 경우에는 해양수산부장관이 정하는 기준에 따라 서로 격리하여야 한다. <개정 2013.3.24, 2020.6.1>","items":[]},{"no":"②","text":"② 동일한 선박에 품명이 다른 화약류를 적재하는 경우에는 해양수산부장관이 정하는 기준에 따라 서로 격리하여야 한다. <개정 2013.3.24>","items":[]},{"no":"③","text":"③ 관할지방해양수산청장등이 제1항과 제2항의 격리방법 외에 다른 방법에 따른 위험물의 격리를 승인한 경우에는 그 다른 방법으로 위험물을 격리시킬 수 있다. <개정 2020.6.1>","items":[]}]},"제21조":{"title":"위험물 적하일람표","head":"제21조(위험물 적하일람표)","paras":[{"no":"①","text":"① 선장은 연해구역에서 운송하는 경우(국내항간에서 운송하는 경우만 해당한다)를 제외하고, 해당 선박에 적재한 위험물에 대하여 다음 각 호의 사항을 기재한 위험물 적하일람표 2통을 작성하여 그 중 1통을 선박소유자에 발급하고, 다른 1통을 선박 안에 해당 운송이 끝날 때까지 보관하여야 한다. <개정 2018.3.12>","items":[{"no":"1.","text":"1. 선박의 명칭ㆍ국적ㆍ번호 및 용도"},{"no":"2.","text":"2. 적재ㆍ환적(換積)ㆍ양하의 항명 및 연월일"},{"no":"3.","text":"3. 송하인의 성명 또는 명칭과 주소"},{"no":"4.","text":"4. 수하인의 성명 또는 명칭과 주소(화약류ㆍ고압가스ㆍ독물ㆍ인화성 액체류 중 저인화점 인화성 액체 및 중인화점 인화성 액체 또는 유기과산화물을 운송하는 경우만 해당한다)"},{"no":"5.","text":"5. 위험물의 분류ㆍ항목ㆍ품명ㆍ부위험성ㆍ국제연합번호 및 용기등급 또는 격리구분"},{"no":"6.","text":"6. 개수 및 질량(화약류에 대해서는 순화약질량을 말한다) 또는 용적"},{"no":"7.","text":"7. 적재장소 및 상태"}]},{"no":"②","text":"② 제1항 각 호에 열거한 사항이 명시된 화물적재도로서 같은 항의 위험물 적하일람표를 대체할 수 있다.","items":[]},{"no":"③","text":"③ 선박소유자는 제1항과 제2항에 따라 발급받은 위험물 적하일람표 또는 화물적재도를 육상의 사무소에 1년간 보관하여야 한다.","items":[]}]},"제22조":{"title":"표지","head":"제22조(표지) 「선박안전법」(이하 \"법\"이라 한다)에 적용되는 선박으로서 호(湖), 천(川) 및 항내에서 항행하거나 정박하는 선박이 화물로서 화약류, 인화성 액체류, 독물, 고압가스, 방사성 물질 또는 유기과산화물을 적재한 경우에는 마스트(MAST)나 그 밖의 보기 쉬운 장소에 주간에는 적색기를 게양하고 야간에는 적색등을 켜두어야 한다.","paras":[]},"제23조":{"title":"위험물 취급지침의 제공","head":"제23조(위험물 취급지침의 제공)","paras":[{"no":"①","text":"① 제204조제1항 각 호에 따른 위험물을 운송하는 선박과 산적액체위험물을 운송하는 선박의 소유자는 해당 위험물의 운송으로 발생하는 위험을 방지하기 위하여 해당 위험물에 관한 성질ㆍ상태, 작업의 방법, 재해발생 시의 조치나 그 밖의 주의사항을 상세히 기록한 위험물취급지침을 작성하여 해당 선박의 선장에게 제공하여야 한다.","items":[]},{"no":"②","text":"② 선장은 제1항의 위험물취급지침에 기술된 사항을 해당 선박의 선원 및 해당 작업을 하는 작업원에게 주지시키고 이를 준수하게 하여야 한다.","items":[]},{"no":"③","text":"③ 제1항의 위험물 외의 위험물을 운송하는 경우(국내항 간에 컨테이너 외의 수단으로 운송하는 경우는 제외한다)에 송하인은 선박소유자 또는 선장(위험물을 자동차에 적재하거나 컨테이너에 수납하여 운송하는 경우로서 선박소유자가 적재하거나 수납할 경우에는 선박소유자만 해당한다)에게 해당 위험물에 관하여 재해발생시의 조치에 관한 정보를 기재한 서류를 제출하여야 한다. 다만, 위험물을 적재하는 항만의 관할지방해양수산청장등이 안전에 지장이 없다고 인정한 경우에는 그러하지 아니하다. <개정 2020.6.1>","items":[]},{"no":"④","text":"④ 선장은 제3항의 서류(사본 등을 포함한다. 이하 이 조에서 같다)를 해당 운송이 종료할 때까지 선박 안에 보관하여야 한다.","items":[]},{"no":"⑤","text":"⑤ 위험물을 다른 선박에 옮겨 실을 경우에는 옮겨 주는 선박의 소유자 또는 선장은 제3항의 서류를 옮겨 실을 선박의 소유자 또는 선장에게 내주어야 한다.","items":[]}]},"제24조":{"title":"운송 중의 조치","head":"제24조(운송 중의 조치)","paras":[{"no":"①","text":"① 선장은 선박에 적재한 위험물로 인한 재해가 발생하지 아니하도록 충분한 주의를 하여야 한다.","items":[]},{"no":"②","text":"② 선장은 인명, 선박 또는 다른 화물에 대한 위험을 피하기 위하여 필요하다고 인정할 때는 선박에 적재한 위험물을 폐기할 수 있다.","items":[]}]},"제24조의2":{"title":"방화장치 등의 구비","head":"제24조의2(방화장치 등의 구비)","paras":[{"no":"①","text":"① 위험물(병독을 옮기기 쉬운 물질과 유해성 물질을 제외한다)을 적재하는 길이 12미터 이상의 선박은 위험물과 화물구역의 종류별로 방화ㆍ화재탐지 및 소화장치 등(이하 \"방화장치등\"이라 한다)을 갖춰 두어야 한다. 다만, 관할지방해양수산청장등이 안전에 지장이 없다고 인정하는 경우에는 그러하지 아니하다. <개정 2020.6.1>","items":[]},{"no":"②","text":"② 제1항에 따른 위험물과 화물구역의 종류별 방화장치등의 기준은 해양수산부장관이 정한다. <개정 2013.3.24>","items":[]}]},"제24조의3":{"title":"위험물운송적합증의 발급 등","head":"제24조의3(위험물운송적합증의 발급 등)","paras":[{"no":"①","text":"① 제24조의2에 따른 방화장치등을 갖춘 선박의 소유자는 별지 제1호서식의 위험물운송적합증 발급신청서를 관할지방해양수산청장등에게 제출하여야 한다. <개정 2020.6.1>","items":[]},{"no":"②","text":"② 관할지방해양수산청장등은 제1항에 따른 신청서를 받은 경우에는 제24조의2의 요건에 적합한지의 여부를 조사ㆍ확인한 후 해당 선박이 운송할 수 있는 위험물 및 위험물의 적재장소를 지정하고 별지 제1호의2서식의 위험물운송적합증을 발급하여야 한다. <개정 2020.6.1>","items":[]},{"no":"③","text":"③ 제2항에 따라 위험물운송적합증을 발급받은 선박의 선장은 이를 선내에 갖춰 두어야 한다.","items":[]},{"no":"④","text":"④ 선장은 위험물운송적합증을 발급받지 아니한 선박으로 위험물을 운송해서는 아니 된다.","items":[]},{"no":"⑤","text":"⑤ 선장은 제2항에 지정된 내용에 따라 위험물을 운송하여야 한다.","items":[]},{"no":"⑥","text":"⑥ 국제항해에 종사하는 선박의 소유자가 「선박안전법 시행규칙」 별지 제20호서식의 위험물운송적합증서를 발급받은 경우에는 제2항에 따른 위험물운송적합증을 발급받은 것으로 본다.","items":[]},{"no":"⑦","text":"⑦ 「1974년 해상에서의 인명안전을 위한 국제협약」의 체약국 또는 체약국 정부가 인정하는 단체가 발급한 위험물운송적합서류는 제2항에 따른 위험물운송적합증으로 본다.","items":[]}]},"제24조의4":{"title":"위험물운송적합증의 재발급 등","head":"제24조의4(위험물운송적합증의 재발급 등)","paras":[{"no":"①","text":"① 선박의 소유자는 위험물운송적합증에 적힌 내용 중 변경사항이 있는 경우에는 그 사유가 생긴 날부터 20일 이내에 별지 제1호서식의 위험물운송적합증 재발급신청서에 해당 위험물운송적합증과 변경사유를 기재한 서류를 첨부하여 관할지방해양수산청장등에게 제출하여야 한다. <개정 2020.6.1>","items":[]},{"no":"②","text":"② 선박의 소유자는 위험물운송적합증을 잃어버렸거나 위험물운송적합증이 헐어 못쓰게 된 경우에는 별지 제1호서식의 위험물운송적합증 재발급신청서에 분실사유서 또는 헐어 못쓰게 된 위험물운송적합증을 첨부하여 관할지방해양수산청장등에게 제출하여야 한다. <개정 2020.6.1>","items":[]}]},"제24조의5":{"title":"위험물운송적합증의 반납","head":"제24조의5(위험물운송적합증의 반납) 선박의 소유자는 다음 각 호의 어느 하나의 사유에 해당하는 경우에는 그 사유가 발생한 날부터 30일 이내에 위험물운송적합증을 관할지방해양수산청장등에게 반납하여야 한다. <개정 2020.6.1>","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 선박이 멸실(滅失)ㆍ침몰 또는 해체된 때"},{"no":"2.","text":"2. 선박이 위험물을 영구히 적재하지 아니하게 된 때"}]}]},"제24조의6":{"title":"검사ㆍ승인 신청 서식","head":"제24조의6(검사ㆍ승인 신청 서식) 법 제41조제2항에 따른 위험물의 적재ㆍ운송 및 저장 방법의 적합 여부에 관한 검사 또는 승인을 법 제65조제1항에 따른 위험물검사등대행기관에 신청하는 경우 제24조의3제1항, 제24조의4제1항 및 제2항에도 불구하고 해당 조항의 서식 외에 해양수산부장관이 정하여 고시하는 통합서식을 이용할 수 있다.","paras":[]},"제24조의7":{"title":"전자증서의 발급","head":"제24조의7(전자증서의 발급) 제24조의3제2항에 따른 위험물운송적합증은 해양수산부장관이 정하여 고시하는 바에 따라 전자적 형태의 증서로 발급할 수 있다.","paras":[]},"제25조":{"title":"사고보고","head":"제25조(사고보고) 선장은 운송하는 위험물로 인명, 선박 또는 다른 화물에 재해가 발생한 경우 또는 위험물이 선외로 유실되었거나 유실될 우려가 있는 사고가 발생한 경우에는 해당 재해 또는 사고가 발생한 지역이나 해당 재해 또는 사고가 발생한 후 최초로 입항한 지역의 관할지방해양수산청장등을 거쳐 해양수산부장관에게 해당 재해 또는 사고가 발생한 날짜와 시간, 장소 및 원인과 해당 위험물의 품명, 수량, 용기, 포장 및 적재방법을 적은 서면(전자문서를 포함한다)을 제출해야 한다. 다만, 「선원법」에 따라 보고한 경우에는 그렇지 않다. <개정 2013.3.24, 2020.6.1>","paras":[]},"제26조":{"title":"수출입의 경우 등의 특례","head":"제26조(수출입의 경우 등의 특례)","paras":[{"no":"①","text":"① 위험물을 국내항과 외국항 간에운송하는 경우 또는 외국의 각 항 간에 운송하는 경우에는 용기ㆍ포장 및 표찰, 자동차(「자동차관리법」에 따른 자동차를 말한다. 이하 같다)에 냉동장치를 부착한 경우 냉동능력ㆍ적재방법 및 자동차의 표시, 컨테이너의 구조ㆍ수납방법ㆍ표시ㆍ적재방법 등은 이 규칙에도 불구하고 해양수산부장관이 고시하는 외국의 위험물 운송관련규칙에 따를 수 있다. <개정 2013.3.24>","items":[]},{"no":"②","text":"② 부식성 물질ㆍ인화성 액체류ㆍ가연성 물질류ㆍ산화성 물질류ㆍ유해성 물질 또는 병독을 옮기기 쉬운 물질을 외국항으로부터 국내항으로 운송하거나 외국항간에 운송하는 경우로서 이 규칙과 제1항에 따른 고시에 따르기 곤란한 경우 선장이 안전상 필요하다고 인정하여 지시하는 경우에는 그 지시에 따라야 한다.","items":[]},{"no":"③","text":"③ 선장은 제1항과 제2항에 따라 위험물을 운송하는 경우에는 위험물 적하일람표 또는 이에 대체되는 화물적재도에 제1항의 경우에는 해당 외국규칙의 명칭을 기록하고, 제2항의 경우에는 그 지시내용을 기록하여야 한다.","items":[]}]},"제27조":{"title":"위험물을 적재한 자동차의 운송","head":"제27조(위험물을 적재한 자동차의 운송)","paras":[{"no":"①","text":"① 국제항해에 종사하는 선박 외의 선박으로 위험물을 적재한 자동차를 운송하는 경우 자동차의 송하인은 해당 자동차가 위험물을 적재하고 있음을 선적하기 전에 선장에게 알려야 한다.","items":[]},{"no":"②","text":"② 제1항의 경우에 해당 위험물에 대하여는 이 장을 적용하지 아니한다. 다만, 제17조, 제22조부터 제24조까지, 제24조의2부터 제24조의5까지, 제25조, 제39조, 제49조, 제50조, 제64조 및 제146조는 그러하지 아니하다.","items":[]},{"no":"③","text":"③ 제1항의 위험물이 화약류인 경우에는 해당 위험물의 포장ㆍ표지ㆍ적재방법ㆍ혼재방법과 차량의 표지는「총포ㆍ도검ㆍ화약류 등의 안전관리에 관한 법률」에서 정하는 바에 따른다. <개정 2018.3.12>","items":[]},{"no":"④","text":"④ 국제항해에 종사하는 선박 외의 선박으로서 여객(해당 선박이 운송하는 자동차의 운전자ㆍ승무원 및 그 밖에 화물감시를 위하여 승차하는 사람은 제외한다)이 승선하고 있는 선박에는 여객선에 적재하는 것이 금지되어 있는 위험물을 적재한 자동차와 다음 각 호의 위험물을 적재한 탱크자동차(탱크로리를 포함한다) 또는 탱크차를 적재해서는 아니 된다.","items":[{"no":"1.","text":"1. 액체산소"},{"no":"2.","text":"2. 액체암모니아"},{"no":"3.","text":"3. 염산"},{"no":"4.","text":"4. 황산"},{"no":"5.","text":"5. 알코올류"},{"no":"6.","text":"6. 아세트산비닐"},{"no":"7.","text":"7. 석유증류물(저인화점 인화성 액체인 것만 해당한다)"},{"no":"8.","text":"8. 톨루엔"}]},{"no":"⑤","text":"⑤ 제1항의 경우에 선장은 다음 사항을 준수하여야 한다.","items":[{"no":"1.","text":"1. 적재 및 양하 시를 제외하고는 자동차의 원동기 및 차등(車燈)을 끄고 제동을 걸어 놓을 것"},{"no":"2.","text":"2. 필요한 경우에는 운전자를 차안에 있도록 하거나 점검을 시킬 것"},{"no":"3.","text":"3. 자동차가 이동하거나 넘어지지 아니하도록 고정하고 외부로부터 충격을 받지 아니하도록 조치할 것"},{"no":"4.","text":"4. 운송 중 자동차의 수리를 하지 말 것"},{"no":"5.","text":"5. 적재장소와 그 부근에는 필요하지 아니한 자의 출입을 금지시킬 것"}]},{"no":"⑥","text":"⑥ 위험물을 자동차에 적재하여 국제항해에 종사하는 선박으로 운송하는 경우에는 제31조부터 제35조까지, 제36조제2항, 제38조와 제205조를 준용한다. 이 경우 제31조부터 제35조까지, 제38조제1항 및 제205조 중 \"컨테이너\"는 \"자동차\"로, \"수납\"은 \"적재\"로 보고, 제36조제2항 중 \"수밀(水密: 물이 통과하는 것을 막은 것)의 금속재컨테이너\" 및 \"컨테이너\"는 각각 \"자동차\"로 보며, 제38조제2항 중 \"수밀컨테이너(물이 통과하는 것을 막은 컨테이너를 말하며, 탱크컨테이너는 제외한다)\"는 \"자동차의 수밀화물적재함(물이 통과하는 것을 막은 화물적재함)\"으로, \"수납\"은 \"적재\"로 보고, 같은 조 제3항 중 \"수밀의 금속재컨테이너\"는 \"자동차의 수밀금속화물적재함\"으로, \"수납\"은 \"적재\"로 본다. <개정 2018.3.12, 2021.6.30>","items":[]},{"no":"⑦","text":"⑦ 위험물을 자동차에 적재하여 국제항해에 종사하는 선박으로 운송하는 경우에 송하인(선박소유자가 위험물을 자동차에 적재하는 경우에는 해당 선박소유자를 말한다)은 냉동장치의 냉동능력(자동차에 적재하는 위험물을 냉동하는 경우만 해당한다) 및 위험물의 적재방법에 대하여 해양수산부장관이 고시로 정하는 기준에 따라야 하며, 선장은 자동차의 적재방법에 대하여 제5항을 준수하여야 한다. <개정 2013.3.24>","items":[]}]},"제28조":{"title":"인양한 화약류의 운송","head":"제28조(인양한 화약류의 운송) 수중에서 인양한 화약류를 그것이 있던 해역으로부터 운송하는 경우에는 해당 화약류에 대하여 이 장(제17조, 제24조 및 제25조는 제외한다)을 적용하지 아니한다.","paras":[]},"제29조":{"title":"","head":"제29조 삭제 <1998.1.8>","paras":[]},"제30조":{"title":"컨테이너의 요건","head":"제30조(컨테이너의 요건)","paras":[{"no":"①","text":"① 위험물의 운송에 사용되는 컨테이너는 「1972년 안전한 컨테이너를 위한 국제협약」에 적합하여야 한다.","items":[]},{"no":"②","text":"② 냉동장치가 설치되어 있는 컨테이너(탱크컨테이너는 제외한다)로 위험물을 운송하는 경우 해당 컨테이너의 냉동능력 및 위험물의 적재방법은 해양수산부장관이 고시하는 기준에 적합하여야 한다. <개정 2013.3.24>","items":[]}]},"제31조":{"title":"위험물의 수납방법","head":"제31조(위험물의 수납방법)","paras":[{"no":"①","text":"① 컨테이너는 위험물을 수납하기 전에 충분히 청소 및 건조되어야 한다.","items":[]},{"no":"②","text":"② 위험물을 컨테이너에 수납할 경우에는 해당 위험물의 이동, 전도(轉倒), 충격, 마찰, 압력손상, 누출 등으로 위험이 발생할 우려가 없도록 하고, 해당 위험물의 어느 부분도 외부로 돌출하지 아니하도록 수납한 후에 컨테이너의 문을 닫아야 한다.","items":[]},{"no":"③","text":"③ 위험물을 컨테이너의 일부에만 수납하는 경우에는 위험물을 컨테이너의 문과 가까운 곳에 수납하여야 한다.","items":[]},{"no":"④","text":"④ 컨테이너를 여닫는 문의 잠금장치 및 봉인은 비상시에 지체 없이 열 수 있는 구조이어야 한다.","items":[]}]},"제32조":{"title":"수납금지","head":"제32조(수납금지)","paras":[{"no":"①","text":"① 품명이 다른 위험물 또는 위험물과 위험물 외의 화물이 상호작용으로 발열, 가스 발생, 부식 작용을 일어나게 하거나 그 밖의 위험한 물리적 또는 화학적 작용을 일어나게 할 우려가 있는 경우에는 동일한 컨테이너에 수납해서는 아니 된다.","items":[]},{"no":"②","text":"② 제20조에 따라 서로 격리하여야 하는 위험물은 동일한 컨테이너에 수납해서는 아니 된다.","items":[]}]},"제33조":{"title":"표시","head":"제33조(표시)","paras":[{"no":"①","text":"① 컨테이너에는 컨테이너에 수납되어 있는 위험물(해양수산부장관이 정하는 위험물은 제외한다)의 품명을 양측면의 보기 쉬운 위치에 표시하고, 표찰(등급이 다른 화약류를 수납하는 경우에는 최고의 위험성을 나타내는 등급의 표찰을 말한다)을 앞뒤와 양측 면에 붙이거나 동일한 표시를 하여야 한다. <개정 2013.3.24>","items":[]},{"no":"②","text":"② 4천킬로그램을 초과하는 동일 품명의 위험물(화약류와 제8조의2제1호에 정하는 위험물은 제외한다)을 동일한 컨테이너에 수납하는 경우에는 별지 제2호도식의 기준에 따라 위험물의 국제연합번호를 품명 또는 표찰에 가깝게 붙이거나 동일한 표시를 하여야 한다.","items":[]},{"no":"③","text":"③ 다음 각 호의 어느 하나에 해당하는 위험물이 수납되어 있는 컨테이너에는 해당 물질에 따라 별지 제1호도식의 고온주의(高溫注意) 부표찰, 해양오염물질 부표찰(副標札) 또는 소량의 위험물 부표찰을 앞뒤와 양측 면에 붙여야 한다.","items":[{"no":"1.","text":"1. 섭씨 100도 이상의 액체위험물"},{"no":"2.","text":"2. 섭씨 240도 이상의 고체위험물"},{"no":"3.","text":"3. 해양오염물질"},{"no":"4.","text":"4. 소량의 위험물"}]},{"no":"④","text":"④ 컨테이너에 수납되어 있는 화물에 훈증소독을 실시한 경우에는 해당 컨테이너 문의 보기 쉬운 위치에 별지 제1호도식의 훈증소독주의 부표찰을 붙여야 한다.","items":[]},{"no":"⑤","text":"⑤ 컨테이너에 위험물(컨테이너의 냉각이나 온도조절을 목적으로 사용하는 위험물만 해당한다)이 수납되어 있는 경우에는 해당 컨테이너의 보기 쉬운 위치에 별지 제1호도식의 냉각제(冷却劑) 주의 부표찰을 붙여야 한다. <신설 2015.3.10>","items":[]},{"no":"⑥","text":"⑥ 컨테이너로부터 위험물 또는 위험물의 잔재물을 완전히 출하한 경우에는 지체 없이 해당 위험물에 관한 표찰 또는 표시를 제거하여야 한다. <개정 2015.3.10>","items":[]}]},"제34조":{"title":"컨테이너 위험물 명세서","head":"제34조(컨테이너 위험물 명세서)","paras":[{"no":"①","text":"① 위험물을 컨테이너에 수납하여 운송할 경우에는(선박소유자가 위험물을 컨테이너에 수납하는 경우를 제외한다) 위험물의 송하인은 사전에 다음 각 호의 사항을 기재한 컨테이너 위험물 명세서를 매 컨테이너마다 작성하여 선박소유자 또는 선장에게 제출하여야 한다. <개정 2018.3.12>","items":[{"no":"1.","text":"1. 컨테이너번호"},{"no":"2.","text":"2. 송하인의 성명 또는 명칭 및 주소"},{"no":"3.","text":"3. 수하인의 성명 또는 명칭 및 주소(화약류, 고압가스, 독물, 인화성 액체류 중 저인화점 인화성 액체 및 중인화점 인화성 액체, 유기과산화물 또는 방사성물질을 운송하는 경우만 해당한다)"},{"no":"4.","text":"4. 위험물의 분류, 항목, 품명, 부위험성, 국제연합번호, 용기등급 또는 격리구분과 용기 및 포장의 명칭"},{"no":"5.","text":"5. 위험물의 수량 및 질량(화약류에 대해서는 순화약질량을 말한다) 또는 용적"}]},{"no":"②","text":"② 위험물을 컨테이너에 수납하여 운송하는 경우에 선박소유자가 위험물을 컨테이너에 수납한 경우에는 선박소유자는 성명 또는 명칭 및 주소와 제1항 각 호의 사항을 기재한 컨테이너 위험물 명세서를 매 컨테이너마다 작성하여 사전에 선장에게 발급하여야 한다.","items":[]},{"no":"③","text":"③ 제1항의 컨테이너 위험물 명세서에는 해당 위험물의 용기, 포장, 표찰, 표시 및 수납방법과 컨테이너의 표시가 이 규칙에 적합하며 운송에 적합한 상태에 있음을 덧붙여 적거나 이를 증명할 서류를 첨부하며, 제2항의 컨테이너 위험물 명세서에는 제16조의 위험물 명세서(같은 조 제2항에 따라 첨부된 서류를 포함한다)를 첨부함과 아울러, 해당 위험물의 수납방법 및 컨테이너의 표시가 이 규칙에 적합하며 운송에 적합한 상태에 있음을 덧붙여 적거나 이를 증명하는 서류를 첨부하여야 한다.","items":[]},{"no":"④","text":"④ 위험물이 수납되어 있는 컨테이너를 다른 선박에 옮겨 실을 경우에는 옮겨 주는 선박의 선박소유자 또는 선장은 해당 컨테이너의 컨테이너 위험물 명세서를 옮겨 실을 선박의 선박소유자 또는 선장에게 발급하여야 한다.","items":[]},{"no":"⑤","text":"⑤ 해당 위험물이 해양오염물질, 폐기물, 소량의 위험물 또는 극소량의 위험물인 경우 컨테이너 위험물 명세서에 각각 \"해양오염물질(MARINE POLLUTANT)\" 또는 \"해양오염물질/환경유해물질(MARINE POLLUTANT/ENVIRONMENT HAZARDOUS)\", \"폐기물(WASTE)\", \"소량의 위험물(limited quantity 또는 LTD QTY)\" 또는 \"극소량의 위험물(dangerous goods in excepted quantities)\"로 기재하고, 해당 용기가 회수용기, 회수압력용기 또는 비세정빈용기인 경우에는 컨테이너 위험물 명세서에 각각 \"회수용기(SALVAGE PACKAGING)\", \"회수압력용기(SALVAGE PRESSURE RECEPTACLE)\" 또는 \"비세정빈용기(EMPTY UNCLEANED 또는 RESIDUE - LAST CONTAINED)\"로 기재해야 한다. <개정 2015.3.10, 2018.3.12, 2020.6.1>","items":[]},{"no":"⑥","text":"⑥ 컨테이너에 냉각이나 온도조절을 목적으로 사용하는 위험물이 투입된 용기나 포장을 수납하여 냉각 또는 온도조절 목적이 달성된 후, 컨테이너 내부에 해당 위험물이 완전히 환기(換氣)되지 아니한 경우에는 해당 컨테이너 관련 서류의 \"UN\"문자 다음에 국제연합번호 및 위험물의 품명을 기재하여야 하고, 바로 그 다음에 \"AS COOLANT\" 또는 \"AS CONDITIONER\" 문자를 기재하여야 한다. <신설 2015.3.10>","items":[]},{"no":"⑦","text":"⑦ 해당 위험물이 다음 각 호의 어느 하나에 해당하는 물질인 경우에는 컨테이너 위험물 명세서에 제어온도와 비상온도를 각각 기재해야 한다. <신설 2020.6.1>","items":[{"no":"1.","text":"1. 운송 중 온도관리가 필요한 제4.1급의 자체반응 물질, 중합성 물질 또는 제5.2급의 유기과산화물"},{"no":"2.","text":"2. 제6조제2항에 따른 품명에 \"안정화된 것(STABILIZED)\"이라는 문구가 포함되어 있는 위험물 중 온도제어를 통해 안정화가 이루어지는 위험물"}]}]},"제35조":{"title":"컨테이너의 적재 전 확인 등","head":"제35조(컨테이너의 적재 전 확인 등)","paras":[{"no":"①","text":"① 선장은 위험물이 수납되어 있는 컨테이너를 선적할 경우에는 컨테이너의 표시가 컨테이너 위험물 명세서의 기재사항과 일치하다는 것을 확인하는 동시에 컨테이너의 손상, 위험물의 누출 등 이상 유무를 조사하여야 한다.","items":[]},{"no":"②","text":"② 선장은 제1항에 따른 조사 결과, 위험물의 용기, 포장, 표찰, 표시 및 수납방법과 컨테이너 표시가 이 규칙에 위반될 염려가 있다고 인정될 경우에는 증인이 참관한 상태에서 컨테이너를 개방하고, 컨테이너내의 화물을 풀어 조사할 수 있다.","items":[]},{"no":"③","text":"③ 선장은 훈증소독된 컨테이너를 선적하는 경우에는 훈증제가 컨테이너에 투입되고 최소 24시간이 지난 후에 선적해야 하며, 해당 컨테이너에 제33조제4항에 따른 훈증소독주의 부표찰이 부착되어 있는지 확인해야 한다. <신설 2020.6.1>","items":[]},{"no":"④","text":"④ 송하인은 훈증소독된 컨테이너를 선적하는 경우에는 훈증소독을 실시한 날짜와 시간, 사용한 훈증제의 종류와 양(量) 등 관련 정보를 사전에 선장에게 제공해야 한다. <신설 2020.6.1>","items":[]}]},"제36조":{"title":"적재방법","head":"제36조(적재방법)","paras":[{"no":"①","text":"① 위험물이 수납되어 있는 컨테이너를 적재할 경우에는 이동, 전도, 손상, 압력손상 등이 생기지 아니하도록 적재하여야 한다.","items":[]},{"no":"②","text":"② 위험물이 수납되어 있는 수밀(水密: 물이 통과하는 것을 막은 것)의 금속재컨테이너를 컨테이너만을 적재하기 위한 설비를 한 화물창이나 구획에 적재할 경우에는 제20조에도 불구하고 해양수산부장관이 정하는 기준에 따를 수 있다. <개정 2013.3.24, 2018.3.12, 2021.6.30>","items":[]}]},"제37조":{"title":"","head":"제37조 삭제 <1992.7.15>","paras":[]},"제38조":{"title":"적용제외 등","head":"제38조(적용제외 등)","paras":[{"no":"①","text":"① 위험물을 컨테이너에 수납하여 운송할 경우에는 제18조, 제48조제1항, 제98조제2항제1호 및 제121조제2항제1호는 적용하지 아니한다.","items":[]},{"no":"②","text":"② 위험물을 수밀컨테이너(물이 통과하는 것을 막은 컨테이너를 말하며, 탱크컨테이너는 제외한다)에 수납하여 운송할 경우에는 제121조제2항제2호는 적용하지 않는다. <개정 2021.6.30>","items":[]},{"no":"③","text":"③ 위험물을 수밀의 금속재컨테이너에 수납하여 운송할 경우에는 제98조제1항제4호를 적용하지 아니한다. <개정 2018.3.12>","items":[]}]},"제39조":{"title":"운송금지","head":"제39조(운송금지)","paras":[{"no":"①","text":"① 다음 각 호의 화약류는 선박으로 운송해서는 안 된다. <개정 2013.3.24, 2021.6.30>","items":[{"no":"1.","text":"1. 아질산아연암모늄"},{"no":"2.","text":"2. 아질산암모늄"},{"no":"3.","text":"3. 염소산암모늄"},{"no":"4.","text":"4. 수분함유율 30퍼센트 미만의 피크르산은"},{"no":"5.","text":"5. 수분함유율 40퍼센트 미만의 디아조디니트로페놀 및 육질산만니톨"},{"no":"6.","text":"6. 수분함유율 30퍼센트 미만의 구아닐니트로소아미노구아닐리덴히드라진 및 구아닐니트로소아미노구아닐테트라젠"},{"no":"7.","text":"7. 수분함유율 25퍼센트 미만 또는 감감제 함유율 15퍼센트 미만의 사질산펜타애리트리트"},{"no":"8.","text":"8. 수분함유율 20퍼센트 미만의 아지드화납ㆍ스티픈산납 및 풀민산수은"},{"no":"9.","text":"9. 감감제함유율 40퍼센트 미만의 니트로글리세린"},{"no":"10.","text":"10. 감감제함유율 25퍼센트 미만의 니트로글리콜"},{"no":"11.","text":"11. 암모늄염과 염소산염을 함유하는 화약류"},{"no":"12.","text":"12. 다음 각 목의 연화(煙火) 가. 백린(白燐)을 함유하는 연화\n 나. 지름 22.2밀리미터 이상의 크래커보올\n 다. 1개당 염소산칼륨과 계관석의 혼합물을 0.26그램 이상 함유하거나 염소산칼륨 및 황화안티몬과 황의 혼합물을 0.26그램 이상 함유하는 연화\n 라. 1알에 적린(赤燐)과 염소산칼륨의 혼합물의 함유량이 0.07그램을 초과하는 종이뇌관\n 마. 황산구리와 염소산염을 함유하는 연화\n 바. 뇌관이 화약 또는 폭약에 장치된 연화"},{"no":"13.","text":"13. 제1호부터 제12호까지에서 정한 것 외에 섭씨 75도에서 48시간 이내에 자연발화하거나 현저한 분해가 될 우려가 있는 화약류 및 그 밖에 해양수산부장관이 정하는 화약류"}]},{"no":"②","text":"② 해양수산부장관이 정하는 화약류는 여객선으로 운송해서는 아니 된다. <개정 2013.3.24>","items":[]}]},"제39조의2":{"title":"화약류 분류의 승인","head":"제39조의2(화약류 분류의 승인)","paras":[{"no":"①","text":"① 「해운법」 제2조제10호에 따른 화주는 화약류를 선박으로 운송하려는 경우 사전에 국제연합번호, 품명 등 「국제해상위험물규칙(IMDG Code)」(이하 \"국제해상위험물규칙\"이라 한다)에 따른 화약류 분류에 대해 관할지방해양수산청장등의 승인을 받아야 한다.","items":[]},{"no":"②","text":"② 제1항에 따라 화약류 분류의 승인을 받으려는 자는 별지 제1호의3서식의 화약류분류승인 신청서에 다음 각 호의 서류를 첨부하여 관할지방해양수산청장등에게 제출해야 한다. 다만, 제3호의 서류는 국내항 간의 운송의 경우에는 제외한다.","items":[{"no":"1.","text":"1. 유엔경제사회이사회(ECOSOC) 소속의 위험물운송 전문가 위원회(UNTDG)가 개발한 위험물 운송에 관한 권고(RTDG, Recommendations on the Transport of Dangerous Goods)에서 정하는 시험기준에 따른 화약류 분류 시험결과 또는 방위사업청 등 관계 중앙행정기관이 발급한 화약류의 국제연합번호가 기재된 서류"},{"no":"2.","text":"2. 해당 화약류의 물질안전보건자료(MSDS: Material Safety Data Sheet)"},{"no":"3.","text":"3. 「총포ㆍ도검ㆍ화약류 등의 안전관리에 관한 법률」 제9조제1항에 따른 화약류 수출 허가증, 「대외무역법」 제19조제2항에 따른 전략물자에 대한 수출 허가 서류 또는 「방위사업법」 제57조제2항에 따른 방산물자 및 국방과학기술 수출 허가서"},{"no":"4.","text":"4. 그 밖에 화약류 분류를 위해 관할지방해양수산청장등이 필요하다고 인정하여 공고하는 서류"}]},{"no":"③","text":"③ 관할지방해양수산청장등은 제2항에 따른 신청을 받은 경우 제출된 서류 등을 검토하여 분류가 적합한 경우 별지 제1호의4서식의 화약류분류승인서를 발급해야 한다.","items":[]},{"no":"④","text":"④ 관할지방해양수산청장등은 제3항에 따른 화약류 분류가 적합한지를 검토하기 위해 관계 전문가 또는 전문기관의 의견을 들을 수 있다.","items":[]}]},"제40조":{"title":"","head":"제40조 삭제 <1992.7.15>","paras":[]},"제41조":{"title":"적재장소의 제한 등","head":"제41조(적재장소의 제한 등)","paras":[{"no":"①","text":"① 화약류는 전등과 그 밖의 전기기구를 설치하고 있는 화물창이나 구획에 적재해서는 아니 된다. 다만, 이러한 장소 외에 쉽게 접근할 수 있는 장소에 개폐기를 설치하고, 이것을 확실히 개방하여 놓을 경우(제49조제1항에 따라 전등을 사용할 경우는 제외한다)에는 그러하지 아니하다.","items":[]},{"no":"②","text":"② 화약류는 화물구역과 기관구역 또는 화물구역과 거주 장소 사이에 있는 격벽(隔璧)으로부터 3미터 이상 떨어진 장소에 적재하여야 한다.","items":[]}]},"제42조":{"title":"화약류와 다른 위험물과의 관계","head":"제42조(화약류와 다른 위험물과의 관계)","paras":[{"no":"①","text":"① 화약류를 적재한 화약고가 있는 화물창이나 구획, 이에 인접한 화물창이나 구획과 해당 화약고가 있는 화물창이나 구획의 바로 위 갑판부분에는 인화성 액체류ㆍ산화성 물질류 또는 가연성 물질을 적재해서는 아니 된다.","items":[]},{"no":"②","text":"② 화약류ㆍ유기과산화물 또는 해양수산부장관이 정하는 인화성 고압가스를 동일한 선박에 적재할 경우에는 다음 각 호에 따라야 한다. <개정 2013.3.24>","items":[{"no":"1.","text":"1. 기관실이 중앙부에 있는 선박의 폭로 갑판상에 인화성 고압가스 또는 유기과산화물을 적재할 경우에는 화약류와 인화성 고압가스 또는 유기과산화물과는 기관실을 사이에 두고 적재할 것"},{"no":"2.","text":"2. 기관실이 뒷부분에 있는 선박의 폭로 갑판상에 인화성고압가스 또는 유기과산화물을 적재할 때는 화약류와 인화성 고압가스 또는 유기과산화물과는 선교구조물을 사이에 두고 하나의 화물창이나 하나의 구획을 띄워서 적재할 것"},{"no":"3.","text":"3. 선박의 갑판 아래에 인화성 고압가스 또는 유기과산화물을 적재할 때는 화약류와 인화성 고압가스 또는 유기과산화물과는 기관실을 사이에 두거나 하나의 화물창이나 하나의 구획을 띄워서 적재할 것"}]},{"no":"③","text":"③ 화약류를 적재한 화약고가 있는 화물창 및 구획이나 그 바로 위의 갑판부분에는 부식성 물질을 적재해서는 아니 된다.","items":[]},{"no":"④","text":"④ 화약류를 적재한 화약고가 있는 화물창 및 구획에는 독물, 방사성 물질 또는 유해성 물질을 적재해서는 아니 된다.","items":[]},{"no":"⑤","text":"⑤ 삭제 <2020.6.1>","items":[]}]},"제43조":{"title":"화약류와 석탄 또는 중량물과의 관계","head":"제43조(화약류와 석탄 또는 중량물과의 관계)","paras":[{"no":"①","text":"① 화약류는 석탄을 적재한 화물창이나 구획과 이에 인접한 화물창 및 구획에 적재해서는 아니 된다. 다만, 해당 석탄이 무연탄인 경우로서 관할지방해양수산청장등의 허가를 받았을 경우에는 그러하지 아니하다. <개정 2020.6.1>","items":[]},{"no":"②","text":"② 화약고에 적재하여야 할 화약류를 적재한 화약고는 항행 중 강재(鋼材), 기계 또는 그 밖의 중량물에 의하여 손상되지 아니하도록 충분한 조치를 마련하여야 한다.","items":[]}]},"제44조":{"title":"화약류 적재 전의 주의","head":"제44조(화약류 적재 전의 주의)","paras":[{"no":"①","text":"① 화약고, 화물창, 갑판, 창구 또는 그 밖에 화약류를 적재하거나 취급하는 장소의 공사는 화약류를 적재하기 전에 완성시켜야 한다.","items":[]},{"no":"②","text":"② 화약류를 적재하는 장소는 화약류를 적재하기 전에 청소하여야 한다.","items":[]},{"no":"③","text":"③ 화약류를 취급하는 장소의 갑판, 화물창 등에 있는 화물, 기구 등은 이동, 전도, 충격, 마찰 등으로 화약류에 위험이 파급될 우려가 없도록 사전에 충분한 조치를 마련하여야 한다.","items":[]},{"no":"④","text":"④ 화약류의 하역을 할 경우에는 사전에 하역설비와 기구를 점검하고 소방에 필요한 준비를 완료하여야 한다.","items":[]}]},"제45조":{"title":"화약류의 하역","head":"제45조(화약류의 하역)","paras":[{"no":"①","text":"① 화약류는 다른 화물과 동시에 하역을 해서는 아니 된다.","items":[]},{"no":"②","text":"② 화약류는 이를 던지거나, 떨어뜨리거나 또는 굴리는 등의 부주의한 취급을 해서는 아니 된다.","items":[]},{"no":"③","text":"③ 화약류의 하역에는 손 갈고리를 사용해서는 아니 된다.","items":[]},{"no":"④","text":"④ 화약류의 하역은 손으로 하거나 미끄럼틀 및 매트리스를 사용하여야 한다.","items":[]},{"no":"⑤","text":"⑤ 하역을 하려는 안벽(부두 벽) 또는 다른 선박과의 사이에 상당한 높이의 차가 있을 경우나 그 밖에 제4항을 따르기 곤란한 경우에는 하역기계(자동차는 제외한다)를 사용할 수 있다. 이 경우에는 관할지방해양수산청장등의 허가를 받은 경우를 제외하고는 다음 각 호에 따라야 한다. <개정 2018.3.12, 2020.6.1, 2021.6.30>","items":[{"no":"1.","text":"1. 1회에 취급하는 화약류의 순화약질량은 1.125킬로그램을 초과하지 아니할 것"},{"no":"2.","text":"2. 바구니(籠), 로프네트슬링(ROPE NET SLING), 판(判)목고를 사용할 것"},{"no":"3.","text":"3. 화약류에 지나친 하중을 가하거나 불안정하게 쌓아 올리지 말 것"}]},{"no":"⑥","text":"⑥ 제1항, 제4항 및 제5항에도 불구하고 화약류가 수납되어 있는 컨테이너를 하역할 경우에는 다음 각 호에 따라야 한다. <개정 2020.6.1>","items":[{"no":"1.","text":"1. 다른 컨테이너 또는 화물과 동시에 하역하지 말 것"},{"no":"2.","text":"2. 컨테이너 전용 크레인을 사용할 것. 다만, 관할지방해양수산청장등이 허가한 경우에는 그러하지 아니하다."}]}]},"제46조":{"title":"미끄럼틀의 구조","head":"제46조(미끄럼틀의 구조)","paras":[{"no":"①","text":"① 미끄럼틀은 두께 25밀리미터 이상의 평면 목판으로 하고 밑판의 양측에는 100밀리미터 이상 높이의 측판을 붙여야 한다.","items":[]},{"no":"②","text":"② 미끄럼틀에 사용되는 못의 종류는 철제여서는 아니 된다.","items":[]},{"no":"③","text":"③ 미끄럼틀의 밑판에는 그 전체 길이에 150밀리미터 이하의 간격으로 반원의 목재를 아교나 나무못으로 붙여야 한다.","items":[]},{"no":"④","text":"④ 미끄럼틀의 네 모퉁이에는 결박용의 둥근 고리를 각각 1개 이상 부착시켜야 한다.","items":[]}]},"제47조":{"title":"미끄럼틀의 설치","head":"제47조(미끄럼틀의 설치)","paras":[{"no":"①","text":"① 미끄럼틀을 설치할 경우에는 화약류에 위험을 미칠 수 있는 경사로가 되도록 해서는 아니 된다.","items":[]},{"no":"②","text":"② 미끄럼틀의 양 끝은 견고히 결박하여야 한다.","items":[]}]},"제48조":{"title":"적재방법","head":"제48조(적재방법)","paras":[{"no":"①","text":"① 화약류는 이동, 전도, 충격, 마찰, 압력손상, 누출 등이 없도록 하고 깔판을 사용하여 적재하여야 한다.","items":[]},{"no":"②","text":"② 화약류를 갑판 상에 적재할 때는 다음 각 호에 따라야 한다. 다만, 등급 1.4의 화약류의 경우에는 제3호 및 제5호를 적용하지 않는다. <개정 2020.6.1>","items":[{"no":"1.","text":"1. 선원이 작업을 할 경우에 통행에 방해되지 아니하는 장소에 적재할 것"},{"no":"2.","text":"2. 화약류의 주위에는 선원의 작업으로 위험이 생기지 아니하도록 3미터 이상의 공간을 남겨 놓을 것"},{"no":"3.","text":"3. 선교(船橋), 거주 장소, 구명정, 구명뗏목, 구조정 및 승정(乘艇) 장소로부터 수평거리 12미터 이상의 거리를 유지할 것"},{"no":"4.","text":"4. 불꽃을 낼 수 있는 설비, 기관배기구, 주방통풍구, 가연성 물품창고 또는 점화원으로부터 수평거리 6미터 이상의 거리를 유지할 것"},{"no":"5.","text":"5. 선측으로부터 선박 너비의 8분의 1 또는 2.4미터 중 짧은 길이 이상의 거리를 두어 적재할 것"}]}]},"제49조":{"title":"조명, 공구류의 제한","head":"제49조(조명, 공구류의 제한)","paras":[{"no":"①","text":"① 화약류의 하역을 할 경우에는 전등 외의 조명을 사용해서는 아니 된다.","items":[]},{"no":"②","text":"② 화약류를 적재한 장소에서는 방폭형(防爆型)의 회중전등 외의 조명을 사용해서는 아니 된다.","items":[]},{"no":"③","text":"③ 화약류의 하역을 하고 있는 장소 또는 이를 적재하고 있는 장소 및 이들의 부근에서는 성냥, 포장되지 아니한 철제공구 및 그 밖에 불꽃을 내기 쉬운 물품을 소지하거나 쇠굽이 붙어 있는 신발류를 신어서는 아니 된다.","items":[]}]},"제50조":{"title":"화기취급의 제한","head":"제50조(화기취급의 제한)","paras":[{"no":"①","text":"① 화약류의 하역을 하고 있는 장소 또는 이것을 적재한 장소 및 이 부근에서는 흡연을 하거나 화기를 취급해서는 아니 된다. 다만, 선장이 이러한 행위가 특히 필요하다고 인정한 경우로서 위험을 방지하기 위한 충분한 조치를 마련한 경우에는 그러하지 아니하다.","items":[]},{"no":"②","text":"② 선장은 제1항의 장소에 흡연 또는 화기의 취급을 금지하는 표시를 하여야 한다.","items":[]}]},"제51조":{"title":"하역 후의 청소","head":"제51조(하역 후의 청소) 화약류의 하역을 종료한 경우에는 화약류를 취급하였던 장소를 청소하여야 한다.","paras":[]},"제52조":{"title":"창구 등의 폐쇄","head":"제52조(창구 등의 폐쇄) 화약류를 적재한 화물창이나 구획 및 재화문(載貨門)은 화물의 하역을 할 경우를 제외하고는 닫아두어야 한다. 이 경우에 폭로 갑판의 창구에는 덮개를 씌워두고 눌러두어야 한다.","paras":[]},"제53조":{"title":"화약고의 종류","head":"제53조(화약고의 종류) 화약고는 밀폐형 화약고 및 화물창형 화약고의 2종으로 한다.","paras":[]},"제54조":{"title":"","head":"제54조 삭제 <2005.12.5>","paras":[]},"제55조":{"title":"밀폐형 화약고","head":"제55조(밀폐형 화약고) 밀폐형 화약고는 「선박안전법」 제23조제4항 전단에 따른 검정기준에 적합한 것으로서 다음 각 호의 요건을 갖추어야 한다.","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 바람과 비를 막을 수 있는 항구적인 구조(직물은 제외한다)로서 견고하여야 하며, 청결하고 녹이 없을 것"},{"no":"2.","text":"2. 바닥을 목재로 하거나, 화물이 적재된 부분을 목재격자, 목재팔레트 또는 목재깔개로 할 것"}]}]},"제56조":{"title":"화물창형 화약고","head":"제56조(화물창형 화약고) 화물창형 화약고는 갑판하부 또는 화물창과 같은 선박의 일부를 화약고로 사용하는 경우로서 다음 각 호의 요건을 갖추어야 한다.","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 바람과 비를 막을 수 있는 구조로서 견고하여야 하며, 청결하고 녹이 없을 것"},{"no":"2.","text":"2. 바닥을 목재로 하거나, 화물이 적재된 부분을 목재격자, 목재팔레트 또는 목재깔개로 할 것"},{"no":"3.","text":"3. 잠금장치가 견고할 것"}]}]},"제57조":{"title":"","head":"제57조 삭제 <2018.3.12>","paras":[]},"제58조":{"title":"화약고의 표시","head":"제58조(화약고의 표시) 화약고(「선원법」에 따른 선원이 승선하지 아니하는 선박의 화약고만 해당한다)에는 그 바깥쪽 면의 보기 쉬운 장소에 \"화약고\"와 \"화기엄금\"의 표시를 하여야 한다.","paras":[]},"제59조":{"title":"용기","head":"제59조(용기)","paras":[{"no":"①","text":"① 삭제 <2003.10.15>","items":[]},{"no":"②","text":"② 밸브가 외부에 돌출한 고압가스의 용기에는 밸브 보호 마개가 있어야 한다. <개정 2010.8.6>","items":[]},{"no":"③","text":"③ 액화시안화수소 또는 호스캔 용기의 밸브 보호 마개에는 공기통이나 그 밖의 구멍이 있는 것은 아니 된다. <개정 2010.8.6>","items":[]},{"no":"④","text":"④ 산소용기의 밸브류에는 윤활제로서 유지류(油脂類)를 사용해서는 아니 된다. <개정 2010.8.6>","items":[]},{"no":"⑤","text":"⑤ 아세틸렌 또는 암모니아의 용기(밸브류를 포함한다)는 구리의 함유량이 70퍼센터 이상인 재료를 사용해서는 아니 된다. <개정 2010.8.6>","items":[]},{"no":"⑥","text":"⑥ 삭제 <2003.10.15>","items":[]},{"no":"⑦","text":"⑦ 삭제 <2003.10.15>","items":[]}]},"제60조":{"title":"충전","head":"제60조(충전)","paras":[{"no":"①","text":"① 선박 안에서는 고압가스를 충전하거나 고압가스를 다른 용기에 주입해서는 아니 된다. <개정 2010.8.6>","items":[]},{"no":"②","text":"② 압축가스ㆍ용해가스 또는 액화가스를 충전한 용기의 내부압력과 용기에 충전하는 액화가스의 질량은 해양수산부장관이 정하는 값을 초과해서는 아니 된다. <개정 2010.8.6, 2013.3.24>","items":[]},{"no":"③","text":"③ 삭제 <1996.2.23>","items":[]},{"no":"④","text":"④ 삭제 <1996.2.23>","items":[]},{"no":"⑤","text":"⑤ 삭제 <1996.2.23>","items":[]},{"no":"⑥","text":"⑥ 삭제 <1996.2.23>","items":[]},{"no":"⑦","text":"⑦ 용해가스를 충전한 용기를 적재하는 장소는 항시 섭씨 40도 이하로 유지하여야 한다. <개정 2010.8.6>","items":[]}]},"제61조":{"title":"표시","head":"제61조(표시) 고압가스를 충전한 용기에는 고압가스의 품명과 충전한 자의 성명 또는 명칭을 표시하여야 한다. 다만, 제206조제2항에 해당하는 경우에는 그러하지 아니하다.","paras":[]},"제62조":{"title":"적재방법","head":"제62조(적재방법)","paras":[{"no":"①","text":"① 고압가스가 충전되어 있는 용기를 적재할 경우에는 다음 각 호에 따라야 한다.","items":[{"no":"1.","text":"1. 이동, 전도, 충격, 마찰 등이 일어나지 아니하도록 고정할 것"},{"no":"2.","text":"2. 선체의 강재부분과 직접 접촉하지 아니하도록 할 것"},{"no":"3.","text":"3. 중량물을 포개어 쌓지 말 것"},{"no":"4.","text":"4. 화기나 열기의 우려가 없고 거주 장소로부터 떨어져 있는 장소에 적재할 것"},{"no":"5.","text":"5. 석탄고나 석탄을 적재한 화물창이나 이 장소의 바로 위 갑판부분에 적재하지 말 것"},{"no":"6.","text":"6. 갑판상부적재하는 경우에는 직사 일광을 받지 아니하도록 할 것"}]},{"no":"②","text":"② 인화성고압가스를 갑판하부적재하는 경우에는 제1항 외에 다음 각 호에 따라야 한다.","items":[{"no":"1.","text":"1. 인화성 고압가스가 충전되어 있는 용기는 선적하기 전에 밸브가 완전히 닫혀있는 것을 확인하고 밸브를 점검할 수 있도록 적재할 것"},{"no":"2.","text":"2. 하역 중에는 주기관과 보조기관을 운전하지 말 것"},{"no":"3.","text":"3. 인화성 고압가스의 하역을 종료한 경우에는 즉시 하역을 한 상갑판 아래 장소에서 폭발이나 화재의 위험을 제거하기 위하여 가스측정을 할 것"},{"no":"4.","text":"4. 상갑판 아래의 장소에서는 흡연을 하거나 화기를 취급하지 말 것. 다만, 가스측정을 하여 폭발이나 화재의 위험이 없는 것을 확인한 후 기관을 시동하거나 조리를 위하여 화기를 취급하는 경우에는 그러하지 아니하다."}]},{"no":"③","text":"③ 인화성 고압가스를 운송하는 경우에는 제148조를 준용한다.","items":[]}]},"제63조":{"title":"하역","head":"제63조(하역) 고압가스는 관(管)장치를 사용하여 하역을 해서는 아니 된다.","paras":[]},"제64조":{"title":"화기사용의 제한 등","head":"제64조(화기사용의 제한 등) 인화성 고압가스에 대해서는 제49조 및 제50조를 준용한다.","paras":[]},"제65조":{"title":"","head":"제65조 삭제 <1992.7.15>","paras":[]},"제66조":{"title":"","head":"제66조 삭제 <1992.7.15>","paras":[]},"제67조":{"title":"","head":"제67조 삭제 <1992.7.15>","paras":[]},"제68조":{"title":"","head":"제68조 삭제 <1992.7.15>","paras":[]},"제69조":{"title":"","head":"제69조 삭제 <1992.7.15>","paras":[]},"제70조":{"title":"","head":"제70조 삭제 <1992.7.15>","paras":[]},"제71조":{"title":"","head":"제71조 삭제 <1992.7.15>","paras":[]},"제72조":{"title":"","head":"제72조 삭제 <1992.7.15>","paras":[]},"제73조":{"title":"","head":"제73조 삭제 <1992.7.15>","paras":[]},"제74조":{"title":"","head":"제74조 삭제 <1992.7.15>","paras":[]},"제75조":{"title":"","head":"제75조 삭제 <1992.7.15>","paras":[]},"제76조":{"title":"","head":"제76조 삭제 <1992.7.15>","paras":[]},"제77조":{"title":"","head":"제77조 삭제 <1992.7.15>","paras":[]},"제78조":{"title":"","head":"제78조 삭제 <1992.7.15>","paras":[]},"제79조":{"title":"","head":"제79조 삭제 <1992.7.15>","paras":[]},"제80조":{"title":"","head":"제80조 삭제 <1992.7.15>","paras":[]},"제81조":{"title":"","head":"제81조 삭제 <1992.7.15>","paras":[]},"제82조":{"title":"","head":"제82조 삭제 <1992.7.15>","paras":[]},"제83조":{"title":"","head":"제83조 삭제 <1992.7.15>","paras":[]},"제84조":{"title":"","head":"제84조 삭제 <1992.7.15>","paras":[]},"제85조":{"title":"","head":"제85조 삭제 <1992.7.15>","paras":[]},"제86조":{"title":"","head":"제86조 삭제 <1992.7.15>","paras":[]},"제87조":{"title":"","head":"제87조 삭제 <1992.7.15>","paras":[]},"제88조":{"title":"","head":"제88조 삭제 <1992.7.15>","paras":[]},"제89조":{"title":"","head":"제89조 삭제 <1992.7.15>","paras":[]},"제90조":{"title":"","head":"제90조 삭제 <1992.7.15>","paras":[]},"제91조":{"title":"","head":"제91조 삭제 <1992.7.15>","paras":[]},"제92조":{"title":"","head":"제92조 삭제 <1992.7.15>","paras":[]},"제93조":{"title":"","head":"제93조 삭제 <1992.7.15>","paras":[]},"제94조":{"title":"","head":"제94조 삭제 <1992.7.15>","paras":[]},"제95조":{"title":"","head":"제95조 삭제 <1992.7.15>","paras":[]},"제96조":{"title":"","head":"제96조 삭제 <1992.7.15>","paras":[]},"제97조":{"title":"","head":"제97조 삭제 <1992.7.15>","paras":[]},"제98조":{"title":"적재방법","head":"제98조(적재방법)","paras":[{"no":"①","text":"① 부식성 물질을 적재할 경우에는 다음 각 호에 따라야 한다.","items":[{"no":"1.","text":"1. 거주 장소나 식량 또는 유기물을 적재한 장소로부터 떨어진 장소에 적재할 것"},{"no":"2.","text":"2. 충분히 감시할 수 있도록 적재할 것"},{"no":"3.","text":"3. 다른 위험물이나 연소가 쉬운 화물의 상부에 적재하지 말 것"},{"no":"4.","text":"4. 다른 위험물의 부근에 적재하지 말 것"}]},{"no":"②","text":"② 부식성 물질을 갑판상부적재하는 경우에는 제1항에 따르는 외에 다음 각 호에 따라야 한다.","items":[{"no":"1.","text":"1. 깔판을 사용할 것"},{"no":"2.","text":"2. 급박한 위험이 있을 때에는 쉽게 선외에 버릴 수 있는 장소에 적재할 것"},{"no":"3.","text":"3. 누출된 부식성 물질이 선내의 다른 장소로 들어가지 아니하도록 충분한 조치를 마련하여 둘 것"},{"no":"4.","text":"4. 새어나온 부식성 물질을 신속히 물로 씻어 버릴 수 있도록 준비할 것"}]}]},"제98조의2":{"title":"전기장치","head":"제98조의2(전기장치) 인화점이 섭씨 23도 미만인 부식성 물질에 대해서는 제148조를 준용한다.","paras":[]},"제99조":{"title":"","head":"제99조 삭제 <1992.7.15>","paras":[]},"제100조":{"title":"","head":"제100조 삭제 <1992.7.15>","paras":[]},"제101조":{"title":"","head":"제101조 삭제 <1992.7.15>","paras":[]},"제102조":{"title":"","head":"제102조 삭제 <1992.7.15>","paras":[]},"제103조":{"title":"","head":"제103조 삭제 <1992.7.15>","paras":[]},"제104조":{"title":"","head":"제104조 삭제 <1992.7.15>","paras":[]},"제105조":{"title":"","head":"제105조 삭제 <1992.7.15>","paras":[]},"제106조":{"title":"","head":"제106조 삭제 <1992.7.15>","paras":[]},"제107조":{"title":"","head":"제107조 삭제 <1992.7.15>","paras":[]},"제108조":{"title":"","head":"제108조 삭제 <1992.7.15>","paras":[]},"제109조":{"title":"","head":"제109조 삭제 <1992.7.15>","paras":[]},"제110조":{"title":"","head":"제110조 삭제 <1992.7.15>","paras":[]},"제111조":{"title":"","head":"제111조 삭제 <1992.7.15>","paras":[]},"제112조":{"title":"","head":"제112조 삭제 <1992.7.15>","paras":[]},"제113조":{"title":"","head":"제113조 삭제 <1992.7.15>","paras":[]},"제114조":{"title":"","head":"제114조 삭제 <1992.7.15>","paras":[]},"제115조":{"title":"","head":"제115조 삭제 <1992.7.15>","paras":[]},"제116조":{"title":"","head":"제116조 삭제 <1992.7.15>","paras":[]},"제117조":{"title":"","head":"제117조 삭제 <1992.7.15>","paras":[]},"제118조":{"title":"","head":"제118조 삭제 <1992.7.15>","paras":[]},"제119조":{"title":"","head":"제119조 삭제 <1992.7.15>","paras":[]},"제120조":{"title":"","head":"제120조 삭제 <1992.7.15>","paras":[]},"제121조":{"title":"적재방법","head":"제121조(적재방법)","paras":[{"no":"①","text":"① 독물을 적재할 때는 다음 각 호에 따라야 한다.","items":[{"no":"1.","text":"1. 거주 장소나 식량을 적재하고 있는 장소로부터 떨어진 장소에 적재할 것"},{"no":"2.","text":"2. 충분히 감시할 수 있도록 적재할 것"},{"no":"3.","text":"3. 이동, 전도(轉倒), 충격, 마찰 등이 발생하지 아니하도록 용기를 고정할 것"},{"no":"4.","text":"4. 중량물을 포개어 쌓지 말 것"}]},{"no":"②","text":"② 독물을 갑판상부적재하는 경우에는 제1항에 따르는 외에 다음 각 호에 따라야 한다.","items":[{"no":"1.","text":"1. 깔판을 사용할 것"},{"no":"2.","text":"2. 방수가 되는 용기와 방수 포장재를 사용할 것"},{"no":"3.","text":"3. 급박한 위험이 있을 경우에는 쉽게 선외로 버릴 수 있는 장소에 적재할 것"},{"no":"4.","text":"4. 누출한 독물이 선내의 다른 장소에 들어가지 아니하도록 충분한 조치를 마련할 것"},{"no":"5.","text":"5. 누출한 독물을 신속히 물로 씻어 선외로 버릴 수 있도록 준비할 것"}]}]},"제121조의2":{"title":"전기장치","head":"제121조의2(전기장치) 인화점이 섭씨 23도 미만인 독물에 대해서는 제148조를 준용한다.","paras":[]},"제122조":{"title":"출입금지","head":"제122조(출입금지) 선장은 해양수산부장관이 정하는 독물을 적재하고 있는 장소에는 관계자 이외에는 출입을 금지하여야 한다. <개정 2013.3.24, 2018.3.12>","paras":[]},"제123조":{"title":"하역물의 청소","head":"제123조(하역물의 청소) 독물의 하역을 종료한 경우에는 독물을 취급한 장소를 청소하여야 한다.","paras":[]},"제123조의2":{"title":"병독을 옮기기 쉬운 물질의 용기 및 포장 등","head":"제123조의2(병독을 옮기기 쉬운 물질의 용기 및 포장 등)","paras":[{"no":"①","text":"① 선박으로 병독을 옮기기 쉬운 물질을 운송하는 경우에는 송하인은 그 용기ㆍ포장 및 표찰에 대하여, 선장은 그 적재방법에 대하여 각각 관할지방해양수산청장등의 지시에 따라야 한다. <개정 2020.6.1>","items":[]},{"no":"②","text":"② 병독을 옮기기 쉬운 물질의 송하인은 제6조에 따른 표찰 중 정표찰 6.2를 붙이고 그 운송이 국제항해에 관련된 경우에는 그 용기(포장되어 있는 경우를 제외한다) 또는 포장에 그 품명을 표시하여야 한다.","items":[]}]},"제124조":{"title":"","head":"제124조 삭제 <1992.7.15>","paras":[]},"제125조":{"title":"","head":"제125조 삭제 <1992.7.15>","paras":[]},"제126조":{"title":"","head":"제126조 삭제 <1992.7.15>","paras":[]},"제127조":{"title":"","head":"제127조 삭제 <1992.7.15>","paras":[]},"제128조":{"title":"","head":"제128조 삭제 <1992.7.15>","paras":[]},"제129조":{"title":"","head":"제129조 삭제 <1992.7.15>","paras":[]},"제130조":{"title":"","head":"제130조 삭제 <1992.7.15>","paras":[]},"제131조":{"title":"","head":"제131조 삭제 <1992.7.15>","paras":[]},"제132조":{"title":"","head":"제132조 삭제 <1992.7.15>","paras":[]},"제133조":{"title":"","head":"제133조 삭제 <1992.7.15>","paras":[]},"제134조":{"title":"","head":"제134조 삭제 <1992.7.15>","paras":[]},"제135조":{"title":"","head":"제135조 삭제 <1992.7.15>","paras":[]},"제136조":{"title":"","head":"제136조 삭제 <1992.7.15>","paras":[]},"제137조":{"title":"","head":"제137조 삭제 <1992.7.15>","paras":[]},"제138조":{"title":"","head":"제138조 삭제 <1992.7.15>","paras":[]},"제139조":{"title":"방사성물질의 용기ㆍ포장 및 적재방법 등","head":"제139조(방사성물질의 용기ㆍ포장 및 적재방법 등) 방사성 물질을 선박으로 운송하는 경우 그 용기ㆍ포장ㆍ표찰ㆍ적재방법 및 검사 등은 제20조제1항과 「원자력안전법」에서 정하는 바에 따른다. <개정 2018.3.12>","paras":[]},"제140조":{"title":"","head":"제140조 삭제 <1992.7.15>","paras":[]},"제141조":{"title":"","head":"제141조 삭제 <1992.7.15>","paras":[]},"제142조":{"title":"","head":"제142조 삭제 <1992.7.15>","paras":[]},"제143조":{"title":"","head":"제143조 삭제 <1992.7.15>","paras":[]},"제144조":{"title":"","head":"제144조 삭제 <1992.7.15>","paras":[]},"제145조":{"title":"","head":"제145조 삭제 <1992.7.15>","paras":[]},"제146조":{"title":"하역 전의 주의","head":"제146조(하역 전의 주의)","paras":[{"no":"①","text":"① 인화성 액체류를 하역할 경우에는 사전에 소방에 필요한 준비를 완료하여야 한다.","items":[]},{"no":"②","text":"② 인화성 액체를 하역할 경우에 있어 제1항의 준비를 할 경우에는 충분한 수의 운반할 수 있는 포말소화기 또는 같은 수준 이상의 효력을 갖고 있는 소화 장치를 갖춰 두어야 한다.","items":[]}]},"제147조":{"title":"적재방법","head":"제147조(적재방법)","paras":[{"no":"①","text":"① 인화성 액체류를 갑판상부적재할 경우에는 다음 각 호에 따라야 한다.","items":[{"no":"1.","text":"1. 선원이 작업을 할 경우에는 통행에 방해되지 않는 장소에 적재할 것"},{"no":"2.","text":"2. 구명정, 구명 뗏목, 구조정 및 승정 장소로부터 떨어진 곳에 적재할 것"},{"no":"3.","text":"3. 소화전, 측심관 및 공기관으로부터 떨어진 장소에 적재할 것"},{"no":"4.","text":"4. 여객선에 적재할 경우에는 여객이 사용하는 장소로부터 떨어진 곳에 적재할 것"}]},{"no":"②","text":"② 제1항 외의 적재방법으로 인화성 액체류를 적재할 경우에는 통풍장치를 가진 화물창이나 구획에 적재하여야 한다.","items":[]},{"no":"③","text":"③ 질량 1천킬로그램을 초과하는 저인화점 인화성 액체나 중인화점 인화성 액체(이하 \"저인화점인화성액체등\"이라 한다)를 적재한 화물창이나 구획과 이에 인접하는 화물창이나 구획에는 인화성 고압가스(액화석유가스는 제외한다)를 적재해서는 아니 된다. 다만, 관할지방해양수산청장등의 허가를 받은 경우에는 그러하지 아니하다. <개정 2020.6.1>","items":[]},{"no":"④","text":"④ 보일러실ㆍ기관실ㆍ석탄고 또는 조리실에 인접하는 화물창이나 구획에 저인화점인화성액체등을 적재할 경우에는 인접한 격벽으로부터 6미터 이상의 간격을 두어야 한다. 다만, 해당 격벽에 적당한 방열장치를 시공하였을 경우에는 그러하지 아니하다.","items":[]}]},"제148조":{"title":"전기장치","head":"제148조(전기장치)","paras":[{"no":"①","text":"① 저인화점인화성액체등을 적재하는 화물창이나 구획에 전기회로의 단자(端子)가 있을 경우에는 적재하기 전에 그 전기회로를 전원으로부터 차단하고, 해당 화물창이나 구획의 인화성 가스가 없어진 후가 아니면 전원(電源)을 접속시켜서는 아니 된다. 다만, 해당 화물창이나 구획에 부착시킨 전기기구가 방폭형(防爆型)일 경우에는 그러하지 아니하다. <개정 2010.8.6>","items":[]},{"no":"②","text":"② 삭제 <1992.7.15>","items":[]},{"no":"③","text":"③ 저인화점인화성액체등을 적재한 화물창이나 구획에서 방폭형의 회중전등(懷中電燈)과 이동등(移動燈) 외의 조명을 사용해서는 아니 된다. 다만, 관할지방해양수산청장등이 선박의 구조 등을 고려하여 지장이 없다고 인정하는 경우에는 그러하지 아니하다. <개정 2010.8.6, 2020.6.1>","items":[]},{"no":"④","text":"④ 제3항에 따른 이동등(移動燈)의 단자(端子)는 폭로갑판상에 설치하여야 한다. <개정 2010.8.6>","items":[]}]},"제149조":{"title":"거주 장소 등의 방호","head":"제149조(거주 장소 등의 방호) 거주 장소, 보일러실, 기관실, 석탄고 또는 조리실에 인접하는 화물창이나 구획에 인화성 액체류를 적재하는 경우에는 인접하고 있는 격벽 또는 갑판은 가스가 누출되지 않아야 한다.","paras":[]},"제150조":{"title":"통풍","head":"제150조(통풍) 화물창이나 구획에 질량 1천킬로그램을 초과하는 저인화점인화성액체등을 적재할 경우에는 해당 화물창이나 구획의 통풍통의 끝단에는 「산업표준화법」 제12조에 따른 한국산업표준(KS)에 적합한 철망(鐵網)으로서 표준체 840마이크로미터보다 더 작은 것을 이중으로 설치하여야 한다.","paras":[]},"제151조":{"title":"빌지","head":"제151조(빌지) 인화성 액체류를 적재한 화물창이나 구획으로부터 빌지(BILGE)가 기관실에 유입하지 아니하도록 충분한 조치를 마련하여야 한다.","paras":[]},"제152조":{"title":"화기 등의 사용제한","head":"제152조(화기 등의 사용제한)","paras":[{"no":"①","text":"① 인화성 액체류를 하역하는 장소, 적재한 장소, 이 부근 또는 인화성 액체류를 적재한 장소로부터 나와 있는 통풍통 부근에는 담배를 피우거나 또는 화기를 취급해서는 아니 된다.","items":[]},{"no":"②","text":"② 선장은 제1항의 장소에 흡연과 화기의 취급을 금지하는 표시를 하여야 한다.","items":[]},{"no":"③","text":"③ 기관을 시동하는데 불꽃 또는 전기점화장치를 사용하는 경우에는 인화성 가스의 상태에 대하여 충분한 주의를 하여야 한다.","items":[]},{"no":"④","text":"④ 제1항의 장소에서는 성냥, 철제공구나 그 밖에 불꽃을 내기 쉬운 물품을 소지하거나 쇠굽이 붙어있는 신발을 신어서는 아니 된다.","items":[]}]},"제153조":{"title":"하역","head":"제153조(하역) 인화성 액체류는 관장치를 사용하여 하역을 해서는 아니 된다.","paras":[]},"제154조":{"title":"하역물의 주의","head":"제154조(하역물의 주의) 인화성 액체류의 하역을 종료한 경우에는 인화성 액체류를 취급하였던 장소를 청소하고 환기하며 인화성 가스나 인화성 액체류가 남아 있지 아니한 것을 확인하여야 한다.","paras":[]},"제155조":{"title":"유탱커에 의한 인화성 액체류의 운송","head":"제155조(유탱커에 의한 인화성 액체류의 운송) 유(油)탱커의 탱크에 인화성 액체류를 적재하여 운송할 경우에는 제6조와 제147조부터 제154조까지에도 불구하고 제156조부터 제163조까지의 규정을 따라야 한다.","paras":[]},"제156조":{"title":"화기취급의 제한 등","head":"제156조(화기취급의 제한 등)","paras":[{"no":"①","text":"① 유탱커 안에서는 흡연하거나 화기를 취급해서는 아니 된다. 다만, 선장이 이러한 행위가 특별히 필요하다고 인정한 경우로서 위험을 방지하기 위한 충분한 조치를 마련한 경우에는 그러하지 아니하다.","items":[]},{"no":"②","text":"② 선장은 용무 없는 사람이 선내에 출입하는 것을 금지하여야 한다.","items":[]},{"no":"③","text":"③ 유탱커 안에서는 안전성냥 외의 성냥 및 순수한 철제공구나 그 밖에 불꽃을 내기 쉬운 물품을 소지하거나 쇠굽이 붙어있는 신발류를 신어서는 아니 된다.","items":[]},{"no":"④","text":"④ 선장은 선내의 적당한 장소에 제1항과 제2항의 금지사항을 표시하여야 한다.","items":[]},{"no":"⑤","text":"⑤ 유탱크와 코퍼댐에서는 방폭형의 회중전등 및 이동등 외의 조명을 사용해서는 아니 된다. 다만, 사전에 가스측정을 하여 폭발이나 화재의 우려가 없는 것을 선장이 확인한 경우에는 그러하지 아니하다.","items":[]},{"no":"⑥","text":"⑥ 유탱크 안의 가스를 뺀 경우에는 증기(蒸氣)이젝터(EJECTOR)를 사용하는 등 수증기를 고속으로 탱크 안에 분출하는 방법을 사용해서는 아니 된다.","items":[]}]},"제157조":{"title":"무선설비의 사용상의 주의","head":"제157조(무선설비의 사용상의 주의) 인화성 액체를 운송하는 유탱커의 선장은 하역 중에 무선설비의 사용을 금지하는 등의 무선설비의 사용에 관한 주의사항을 무선실에 게시하여야 한다.","paras":[]},"제158조":{"title":"창호의 개폐","head":"제158조(창호의 개폐)","paras":[{"no":"①","text":"① 탱크에 인화성 가스가 잔존하는 동안은 선장이나 선장이 지정하는 사람의 참관 없이는 탱크의 창구, 유면측정구(油面測定口), 세척구(洗滌口) 등을 열고 닫아서는 아니 되며, 그 창호는 방화(防火) 철망을 부착하지 아니하고 개방한 상태로 두어서는 아니 된다. <개정 2018.3.12>","items":[]},{"no":"②","text":"② 제1항에 따른 개폐는 불꽃을 발생시킬 우려가 있는 공구를 사용해서는 아니 된다.","items":[]}]},"제159조":{"title":"전기적 절연","head":"제159조(전기적 절연) 유탱커에서 인화성 액체류를 하역하려는 경우 유탱커의 화물유관(貨物油管)과 육상유관(陸上油管) 간에는 전기적으로 절연되어야 한다. 다만, 전기적으로 절연할 수 없는 경우에는 다음 각 호의 기준에 따라 전기적 연속을 유지할 수 있다.","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 화물유관과 육상유관을 연결하기 전에 충분히 전기적 연속을 하여 둘 것"},{"no":"2.","text":"2. 전기적 연속을 단절하기 전에 화물유관을 육상유관으로부터 해제하고 관의 내부에 인화성 액체류가 남아있지 아니한 것을 확인할 것"}]}]},"제160조":{"title":"하역","head":"제160조(하역)","paras":[{"no":"①","text":"① 유탱커에 인화성 액체류를 적재할 경우에는 사전에 하역에 관계되는 배수구 및 해수밸브를 완전히 닫아야 한다. 다만, 특히 필요한 경우에는 그러하지 아니한다.","items":[]},{"no":"②","text":"② 인화성 액체류의 하역에 사용되는 화물유관에는 이것을 완전히 지지할 수 있는 도르래 등을 사용하여야 한다.","items":[]},{"no":"③","text":"③ 화물유관의 연속개소는 기름의 누출이 없도록 하고 그 밑에 받는 그릇을 놓아야 한다.","items":[]},{"no":"④","text":"④ 선장은 인화성 액체류의 하역을 하기 전에 다음 각 호의 사항을 확인하여야 한다.","items":[{"no":"1.","text":"1. 하역에 위험을 미칠 우려가 있는 수리나 그 밖의 작업이 없을 것"},{"no":"2.","text":"2. 화물유의 하역장치가 양호한 상태에 있을 것"}]},{"no":"⑤","text":"⑤ 선장은 인화성 액체류의 하역 중 다음 각 호의 사항을 감시하여야 한다.","items":[{"no":"1.","text":"1. 화물유 하역장치 밸브의 작동 상황"},{"no":"2.","text":"2. 화물유 하역장치의 작동 압력"},{"no":"3.","text":"3. 기름의 누출유무"},{"no":"4.","text":"4. 화물을 싣는 상황"},{"no":"5.","text":"5. 보일러나 조리실 등으로부터 불꽃이 튀어 나오는지의 유무"}]},{"no":"⑥","text":"⑥ 인화성 액체류의 하역을 종료한 경우에는 즉시 하역에 관계되는 밸브를 닫아야 한다.","items":[]}]},"제161조":{"title":"하역의 금지","head":"제161조(하역의 금지) 다음 각 호의 어느 하나에 해당될 경우에는 인화성 액체류(제3호의 경우에는 저인화점인화성액체등만 해당한다)를 하역해서는 아니 된다.","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 자기풍(磁氣風)이 뚜렷한 경우"},{"no":"2.","text":"2. 부근에 화재가 발생한 경우"},{"no":"3.","text":"3. 다른 선박(위험하지 않은 소형선박은 제외한다)이 이선(離船) 또는 접선(接船)할 경우"}]}]},"제162조":{"title":"다른 화물 등의 하역","head":"제162조(다른 화물 등의 하역) 선장은 위험의 우려가 없다고 인정할 때를 제외하고는 인화성 액체류의 하역 중 다른 화물 또는 상용위험물을 하역해서는 아니 된다.","paras":[]},"제163조":{"title":"인화성 액체류와 타 위험물과의 관계","head":"제163조(인화성 액체류와 타 위험물과의 관계) 인화성 액체류를 적재한 유탱커에는 다른 위험물을 적재해서는 아니 된다. 다만, 관할지방해양수산청장등의 허가를 받은 경우에는 그러하지 아니하다. <개정 2020.6.1>","paras":[]},"제164조":{"title":"유탱커 밀폐구역의 출입제한","head":"제164조(유탱커 밀폐구역의 출입제한) 유탱커 밀폐구역에 출입하려는 사람은 선박소유자 또는 선장에게 유탱커 밀폐구역이 다음 각 호의 요건을 모두 충족함을 확인받아야 한다. <개정 2013.3.24>","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 산소가스 검지장치(檢知裝置)로 측정된 유탱커 밀폐구역의 산소 부피가 21퍼센트일 것"},{"no":"2.","text":"2. 인화성 가스 검지장치로 측정된 인화성 가스의 부피가 그 최저인화한계(Lower Flammable Limit)의 1퍼센트 이하일 것"},{"no":"3.","text":"3. 독성가스의 부피가 해양수산부장관이 정하여 고시하는 기준을 충족할 것"}]}]},"제165조":{"title":"","head":"제165조 삭제 <1992.7.15>","paras":[]},"제166조":{"title":"","head":"제166조 삭제 <1992.7.15>","paras":[]},"제167조":{"title":"","head":"제167조 삭제 <1992.7.15>","paras":[]},"제168조":{"title":"","head":"제168조 삭제 <1992.7.15>","paras":[]},"제169조":{"title":"","head":"제169조 삭제 <1992.7.15>","paras":[]},"제170조":{"title":"","head":"제170조 삭제 <1992.7.15>","paras":[]},"제171조":{"title":"","head":"제171조 삭제 <1992.7.15>","paras":[]},"제172조":{"title":"","head":"제172조 삭제 <1992.7.15>","paras":[]},"제173조":{"title":"","head":"제173조 삭제 <1992.7.15>","paras":[]},"제174조":{"title":"","head":"제174조 삭제 <1992.7.15>","paras":[]},"제175조":{"title":"","head":"제175조 삭제 <1992.7.15>","paras":[]},"제176조":{"title":"","head":"제176조 삭제 <1992.7.15>","paras":[]},"제177조":{"title":"","head":"제177조 삭제 <1992.7.15>","paras":[]},"제178조":{"title":"","head":"제178조 삭제 <1992.7.15>","paras":[]},"제179조":{"title":"","head":"제179조 삭제 <1992.7.15>","paras":[]},"제180조":{"title":"","head":"제180조 삭제 <1992.7.15>","paras":[]},"제181조":{"title":"","head":"제181조 삭제 <1992.7.15>","paras":[]},"제182조":{"title":"","head":"제182조 삭제 <1992.7.15>","paras":[]},"제183조":{"title":"","head":"제183조 삭제 <1992.7.15>","paras":[]},"제184조":{"title":"","head":"제184조 삭제 <1992.7.15>","paras":[]},"제185조":{"title":"","head":"제185조 삭제 <1992.7.15>","paras":[]},"제186조":{"title":"","head":"제186조 삭제 <1992.7.15>","paras":[]},"제187조":{"title":"","head":"제187조 삭제 <1992.7.15>","paras":[]},"제188조":{"title":"","head":"제188조 삭제 <1992.7.15>","paras":[]},"제189조":{"title":"","head":"제189조 삭제 <1992.7.15>","paras":[]},"제190조":{"title":"","head":"제190조 삭제 <1992.7.15>","paras":[]},"제191조":{"title":"","head":"제191조 삭제 <1992.7.15>","paras":[]},"제192조":{"title":"","head":"제192조 삭제 <1992.7.15>","paras":[]},"제193조":{"title":"","head":"제193조 삭제 <1992.7.15>","paras":[]},"제194조":{"title":"","head":"제194조 삭제 <1992.7.15>","paras":[]},"제195조":{"title":"","head":"제195조 삭제 <2005.12.5>","paras":[]},"제196조":{"title":"적재의 방법","head":"제196조(적재의 방법)","paras":[{"no":"①","text":"① 면화를 적재하는 장소는 적재하기 전에 청소하여야 한다.","items":[]},{"no":"②","text":"② 유성의 화물이 적재되었던 장소에 면화를 적재할 경우에는 해당 적재장소의 유성분을 충분히 제거하여야 한다.","items":[]},{"no":"③","text":"③ 칠을 한 장소에 면화를 적재할 경우에는 도료가 충분히 건조된 후에 적재하여야 한다.","items":[]},{"no":"④","text":"④ 면화의 적재장소로 통하는 갑판간의 창구는 이것을 닫은 후 덮개 등으로 씌우고 적당히 방호(防護)하여야 한다.","items":[]},{"no":"⑤","text":"⑤ 선장은 창구를 개방한 채로 면화의 하역을 일시 중지할 경우에는 화재를 예방하기 위하여 감시원을 두어야 한다.","items":[]},{"no":"⑥","text":"⑥ 면화의 적재장소와 통하는 통풍통의 끝단에는 가늘고 촘촘한 철망을 부착하여야 한다.","items":[]},{"no":"⑦","text":"⑦ 면화는 보일러실 또는 기관실과 인접한 화물창이나 구획에 적재할 경우에는 기관실과의 격벽으로부터 50밀리미터 이상, 보일러실의 격벽으로부터 150밀리미터 이상의 거리를 유지하고, 적당히 방호조치를 마련하여야 한다.","items":[]},{"no":"⑧","text":"⑧ 면화를 적재한 화물창이나 구획의 폭로갑판상의 창구는 완전히 닫고 필요에 따라 덮개 등으로 씌워야 한다. <개정 2018.3.12>","items":[]}]},"제197조":{"title":"소화장치","head":"제197조(소화장치) 소화장치가 없는 장소에 면화를 적재하는 경우는 면화를 적재하기 전에 적당한 소화기를 갖춰 두어야 한다. 다만, 관할지방해양수산청장등이 지장이 없다고 인정하는 경우에는 그러하지 아니하다. <개정 2020.6.1>","paras":[]},"제198조":{"title":"화재예방장치","head":"제198조(화재예방장치) 면화를 하역하는 동안에는 다음 각 호의 사항을 준수해야 한다. <개정 2021.6.30>","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 굴뚝에는 불꽃의 토출을 방지하는 데에 충분한 장치를 하여 둘 것"},{"no":"2.","text":"2. 면화를 하역하는 장소 또는 이를 적재하고 있는 장소 및 그 부근에서는 흡연, 화기취급, 성냥 또는 그 밖에 불꽃을 내기 쉬운 물품을 지니지 아니할 것. 다만, 선장이 이러한 행위가 특히 필요하다고 인정한 경우로서 위험을 방지하는 데에 충분한 조치를 마련한 경우에는 그러하지 아니하다."},{"no":"3.","text":"3. 다른 선박이 접선할 경우에는 그 선박에서 사용하는 화기를 충분히 감시할 것"}]}]},"제199조":{"title":"","head":"제199조 삭제 <1992.7.15>","paras":[]},"제200조":{"title":"운송금지","head":"제200조(운송금지) 다음 각 호의 산화성 물질류는 선박으로 운송해서는 아니 된다.","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 과망간산암모늄"},{"no":"2.","text":"2. 과염소산[농도가 72퍼센트(질량 퍼센트)를 넘는 것만 해당한다]"},{"no":"3.","text":"3. 터티어리(TERTIARY) 부틸퍼옥시아세테이트[농도가 76퍼센트(질량 퍼센트)를 넘는 것만 해당한다]"},{"no":"4.","text":"4. 메틸이소부틸케톤퍼옥시드[농도가 62퍼센트(질량 퍼센트)를 넘는 것만 해당한다]"},{"no":"5.","text":"5. 아세틸벤조일퍼옥시드[농도가 45퍼센트(질량 퍼센트)를 넘는 것만 해당한다]"},{"no":"6.","text":"6. 아세틸퍼옥시드[농도가 27퍼센트(질량 퍼센트)를 넘는 것만 해당한다]"}]}]},"제201조":{"title":"적재방법","head":"제201조(적재방법) 유기과산화물을 적재할 경우에는 다음 각 호에 따라야 한다.","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 이동, 전도, 충격, 마찰 등이 발생하지 아니하도록 고정할 것"},{"no":"2.","text":"2. 중량물을 포개어 쌓지 말 것"},{"no":"3.","text":"3. 가스를 빼는 구멍이 있는 용기는 가스 빼는 구멍이 상부에 오도록 적재할 것"},{"no":"4.","text":"4. 화기나 열기의 우려가 없고 거주 장소로부터 떨어진 곳에 적재할 것"},{"no":"5.","text":"5. 석탄고, 석탄을 적재한 화물창이나 이들 바로 위의 갑판부분에 적재하지 말 것"}]}]},"제201조의2":{"title":"","head":"제201조의2 삭제 <2005.12.5>","paras":[]},"제202조":{"title":"준용규정","head":"제202조(준용규정) 유기과산화물에 대해서는 제50조, 제146조제1항, 제148조 및 제154조를 준용한다.","paras":[]},"제203조":{"title":"","head":"제203조 삭제 <2007.11.6>","paras":[]},"제204조":{"title":"적재검사","head":"제204조(적재검사)","paras":[{"no":"①","text":"① 선장은 다음 각 호의 위험물을 운송하려는 경우에는 위험물의 적재방법, 해당 위험물에 적합한 용기ㆍ포장의 사용여부와 표시 및 표찰의 적합여부에 관하여 관할지방해양수산청장등의 검사를 받아야 한다. <개정 2013.3.24, 2020.6.1>","items":[{"no":"1.","text":"1. 해양수산부장관이 정하는 화약류"},{"no":"2.","text":"2. 용적(섭씨 0도에서 0메가파스칼의 상태로 환산한 용적을 말한다) 300세제곱미터 이상의 액화가스 외의 고압가스 또는 질량 3천킬로그램 이상의 액화가스"},{"no":"3.","text":"3. 해양수산부장관이 정하는 독물"},{"no":"4.","text":"4. 해양수산부장관이 정하는 유기과산화물"}]},{"no":"②","text":"② 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 경우에는 검사를 받지 아니할 수 있다. <개정 2013.1.23>","items":[{"no":"1.","text":"1. 외국항에서 선적하여 운송하는 경우"},{"no":"2.","text":"2. 위험물을 자동차에 적재하여 운송하는 경우로서 해당 자동차를 롤온ㆍ오프화물구역에 적재하여 운송하는 경우"},{"no":"3.","text":"3. 컨테이너를 전용으로 적재하기 위한 설비를 갖춘 장소에 위험물을 컨테이너에 수납하여 운송하는 경우"},{"no":"4.","text":"4. 제1항제2호의 위험물을 탱커 또는 탱크선에 적재하여 운송하는 경우"},{"no":"5.","text":"5. 포경(捕鯨)을 위하여 필요한 위험물을 해당 선박으로 운송하는 경우"},{"no":"6.","text":"6. 조난선박의 구조 또는 해체업무에 필요한 위험물을 해당 업무를 수행하는 선박으로 운송하는 경우"},{"no":"7.","text":"7. 해양경찰청 소속 선박에 갖춰 놓고 있는 무기의 사용에 필요한 위험물을 해당 선박으로 운송하는 경우"},{"no":"8.","text":"8. 기상청이 하는 기상관측에 필요한 위험물을 기상업무를 수행하는 선박에서 사용하기 위하여 해당 선박으로 운송하는 경우"},{"no":"9.","text":"9. 평수구역에서 위험물을 운송하는 경우"}]},{"no":"③","text":"③ 제1항의 검사를 받으려는 자는 별지 제2호서식의 위험물적재검사신청서를 관할지방해양수산청장등에게 제출하여야 한다. <개정 2020.6.1>","items":[]},{"no":"④","text":"④ 관할지방해양수산청장등은 제1항의 검사에 합격한 사람에게 별지 제2호서식의 위험물적재검사증을 발급하여야 한다. <개정 2020.6.1>","items":[]},{"no":"⑤","text":"⑤ 선장은 제1항의 위험물을 운송하는 경우에는 제4항의 위험물적재검사증을 선내에 갖춰 두어야 한다.","items":[]},{"no":"⑥","text":"⑥ 선장이 제3항에 따라 검사신청을 하는 경우와 관할지방해양수산청장등이 제4항에 따라 위험물적재검사증을 발급하는 경우에는 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」 제2조제1항제5호에 따른 전자문서로 할 수 있다. <개정 2020.6.1>","items":[]}]},"제205조":{"title":"컨테이너수납검사","head":"제205조(컨테이너수납검사)","paras":[{"no":"①","text":"① 송하인이나 선박소유자는 해양수산부장관이 정하는 위험물을 컨테이너에 수납하여 운송하려는 경우에는 컨테이너 수납방법, 해당 위험물에 적합한 용기ㆍ포장의 사용 여부와 표시 및 표찰의 적합 여부에 관하여 관할지방해양수산청장등에게 검사를 받아야 한다. <개정 2013.3.24, 2020.6.1>","items":[]},{"no":"②","text":"② 제1항에도 불구하고, 다음 각 호의 어느 하나에 해당하는 경우에는 컨테이너수납검사를 받지 아니할 수 있다. <개정 2013.1.23>","items":[{"no":"1.","text":"1. 외국항에서 위험물을 컨테이너에 수납하는 경우"},{"no":"2.","text":"2. 위험물을 탱크컨테이너에 수납하여 운송하는 경우"}]},{"no":"③","text":"③ 제1항에 따른 검사를 받으려는 자는 별지 제4호서식의 위험물컨테이너수납검사신청서를 관할지방해양수산청장등에게 제출하여야 한다. <개정 2020.6.1>","items":[]},{"no":"④","text":"④ 관할지방해양수산청장등은 제1항의 검사에 합격한 자에게 별지 제4호서식의 위험물컨테이너수납검사증을 발급하여야 한다. <개정 2020.6.1>","items":[]},{"no":"⑤","text":"⑤ 제4항에 따른 위험물컨테이너수납검사증을 발급받은 자는 선적 전에 해당 위험물컨테이너수납검사증을 선장에게 제출하여야 한다.","items":[]},{"no":"⑥","text":"⑥ 제1항에 따른 위험물을 운송할 경우에는 선장은 제5항의 위험물컨테이너수납검사증을 선내에 갖춰 두어야 한다.","items":[]},{"no":"⑦","text":"⑦ 제1항에 따른 위험물이 수납되어 있는 컨테이너를 다른 선박에 옮겨 실을 때에는 옮겨 주는 선박의 선장은 해당 위험물컨테이너수납검사증을 옮겨 실을 선박의 선장에게 내주어야 한다.","items":[]},{"no":"⑧","text":"⑧ 송하인 또는 선박소유자가 제3항에 따라 검사신청을 하는 경우와 관할지방해양수산청장등이 제4항에 따라 위험물컨테이너수납검사증을 발급하는 경우 제204조제6항을 준용한다. <개정 2020.6.1>","items":[]},{"no":"⑨","text":"⑨ 송하인이나 선박소유자는 해양수산부장관이 정하는 위험물 외의 위험물을 컨테이너에 수납하여 운송하려는 경우에도 컨테이너 수납방법, 해당 위험물에 적합한 용기ㆍ포장의 사용 여부와 표시 및 표찰의 적합 여부에 관하여 관할지방해양수산청장등의 검사를 받을 수 있다. 이 경우 검사에 관하여는 제3항부터 제8항까지의 규정을 준용한다. <신설 2015.3.10, 2020.6.1>","items":[]}]},"제205조의2":{"title":"용기ㆍ포장검사","head":"제205조의2(용기ㆍ포장검사)","paras":[{"no":"①","text":"① 위험물을 운송하는 용기 및 포장은 그 용기 및 포장의 안전성을 관할지방해양수산청장등에게 검사받아야 한다. <개정 2020.6.1>","items":[]},{"no":"②","text":"② 제1항의 검사를 받으려는 자는 별지 제5호의2서식의 위험물용기검사신청서를 관할지방해양수산청장등에게 제출하여야 한다. <개정 2020.6.1>","items":[]},{"no":"③","text":"③ 관할지방해양수산청장등은 제1항의 검사에 합격한 용기 및 포장에 별지 제3호도식에 따른 표시를 하여야 하고, 별지 제5호의3서식의 위험물용기검사증을 그 검사를 받은 자에게 발급하여야 한다. <개정 2020.6.1>","items":[]},{"no":"④","text":"④ 제1항에 따른 용기 및 포장의 검사를 위한 안전기준 등은 해양수산부장관이 정하여 고시한다. <개정 2013.3.24>","items":[]},{"no":"⑤","text":"⑤ 용기 및 포장에 다음 각 호의 어느 하나에 해당하는 사유가 발생한 경우에는 제1항에 따른 검사의 효력이 상실된다. <개정 2013.3.24>","items":[{"no":"1.","text":"1. 검사표시 후 용기 및 포장에 중대한 손상이 발생한 경우"},{"no":"2.","text":"2. 검사표시 후 수납되는 위험물의 안전성에 영향을 미칠 우려가 있는 개조를 한 경우"},{"no":"3.","text":"3. 중형산적용기(금속중형용기, 경질 플라스틱중형용기 및 플라스틱내용기복합중형용기만 해당한다) 및 대형금속용기가 검사표시 후 2년 6개월이 지난 경우"},{"no":"4.","text":"4. 플라스틱드럼, 플라스틱제리캔, 경질 플라스틱중형용기(액체용만 해당한다) 및 플라스틱내용기복합중형용기(액체용만 해당한다)가 제조 후 5년(부식성이 강한 물질 등 해양수산부장관이 정하여 고시하는 물질을 수납하는 용기의 경우 2년을 말한다)이 지나거나 화이버보드상자가 검사 후 사용된 경우"}]},{"no":"⑥","text":"⑥ 제1항의 검사를 받으려는 자가 제2항에 따라 검사신청하는 경우와 관할지방해양수산청장등이 제3항에 따라 위험물용기검사증을 발급하는 경우 제204조제6항을 준용한다. <신설 2013.1.23, 2020.6.1>","items":[]}]},"제206조":{"title":"용기ㆍ포장검사의 면제","head":"제206조(용기ㆍ포장검사의 면제)","paras":[{"no":"①","text":"① 다음 각 호의 어느 하나에 해당하는 용기가 「고압가스 안전관리법」 제17조에 따른 검사에 합격한 경우에는 제205조의2에 따른 검사를 면제한다. <개정 2013.1.23>","items":[{"no":"1.","text":"1. 대형금속용기(국내항 사이에 운송되는 경우에만 해당한다)"},{"no":"2.","text":"2. 압력용기"},{"no":"3.","text":"3. 집합형압력용기(국내항 사이에 운송되는 경우에만 해당한다)"}]},{"no":"②","text":"② 다음 각 호에 해당하는 용기로서 국내항 사이에 운송되는 경우에는 제205조의2에 따른 검사를 면제한다.","items":[{"no":"1.","text":"1. 「고압가스 안전관리법」 제17조에 따라 검사가 생략된 경우"},{"no":"2.","text":"2. 액화석유가스가 들어 있는 가스라이터 등 500그램 이하의 용기로서 다음 각 목의 기준에 적합한 경우 가. 금속재 또는 플라스틱재(내용적이 100세제곱센티미터 이하의 것만 해당한다)일 것\n 나. 1.47메가파스칼(MEGA PASCAL)의 압력으로 수압시험을 하여도 누출이나 큰 변형이 없는 것\n 다. 내용적이 30세제곱센티미터를 초과하는 용기는 액화석유가스의 품명과 가연성가스라는 내용이 표시되어 있을 것"},{"no":"3.","text":"3. 100세제곱센티미터 이하의 액화탄산가스가 들어 있는 용기로서 다음 각 목의 기준에 적합한 경우 가. 강재(鋼材)일 것\n 나. 40.5메가파스칼의 압력으로 수압시험을 하여도 누출이나 큰 변형이 없는 것"}]}]},"제207조":{"title":"","head":"제207조 삭제 <1999.1.9>","paras":[]},"제208조":{"title":"위험물검사등대행기관의 지정신청","head":"제208조(위험물검사등대행기관의 지정신청)","paras":[{"no":"①","text":"① 법 제65조제1항에 따른 위험물검사등대행기관은 영리를 목적으로 하지 아니하는 법인이어야 한다. 다만, 제205조의2에 따라 용기ㆍ포장검사를 할 수 있는 위험물검사등대행기관은 「국가표준기본법」 제23조에 따라 인정받은 시험ㆍ검사기관 또는 같은 법 제24조에 따른 품질경영체제(ISO 9000 표준시리즈)의 인증을 받은 기관이어야 한다. <개정 2020.6.1>","items":[]},{"no":"②","text":"② 제1항에 따른 위험물검사등대행기관의 지정을 받으려는 자는 다음의 서류를 첨부하여 해양수산부장관에게 신청하여야 한다. <개정 2013.3.24>","items":[{"no":"1.","text":"1. 주된 사무소와 출장소의 명칭 및 소재지"},{"no":"2.","text":"2. 법인의 정관"},{"no":"3.","text":"3. 임원의 성명"},{"no":"4.","text":"4. 종사원의 성명 및 이력"},{"no":"5.","text":"5. 검사절차 등에 관한 기준"}]}]},"제209조":{"title":"위험물검사등대행기관의 지정ㆍ고시","head":"제209조(위험물검사등대행기관의 지정ㆍ고시)","paras":[{"no":"①","text":"① 해양수산부장관은 제208조제2항의 신청을 받은 경우에는 이를 심사하여 신청인이 법 제65조제1항에 따른 검사 또는 승인업무의 대행(이하 \"검사대행\"이라 한다)을 할 능력이 있다고 인정될 경우에는 해당 신청인이 행할 검사대행의 범위 등을 정하여 신청인에게 통지하고 고시하여야 한다. <개정 2013.3.24>","items":[]},{"no":"②","text":"② 위험물검사등대행기관은 분기별 검사대행실적을 매 분기 종료일부터 10일 이내에 해양수산부장관에게 보고하여야 한다. <개정 2013.3.24>","items":[]}]},"제210조":{"title":"변경사항 등의 인가","head":"제210조(변경사항 등의 인가) 위험물검사등대행기관은 검사원을 선임할 경우나 검사대행에 필요한 기준을 새로 정하거나 변경할 경우에는 해양수산부장관의 인가를 받아야 한다. <개정 2013.3.24>","paras":[]},"제211조":{"title":"","head":"제211조 삭제 <2007.11.6>","paras":[]},"제212조":{"title":"검사원","head":"제212조(검사원) 제210조에 따른 검사원의 선임인가 등에 관한 기준은 해양수산부장관이 정한다. <개정 2013.3.24, 2019.11.20>","paras":[]},"제213조":{"title":"위험물컨테이너 등 점검","head":"제213조(위험물컨테이너 등 점검)","paras":[{"no":"①","text":"① 해양수산부장관은 항만으로 반입되는 위험물을 수납한 컨테이너 및 용기에 대하여 이 규칙 및 국제해상위험물규칙에 적합한지 점검할 수 있다. <개정 2013.1.23, 2013.3.24, 2020.6.1>","items":[]},{"no":"②","text":"② 제1항에 따른 위험물을 수납한 컨테이너 및 용기에 대한 점검항목ㆍ방법, 점검 후 조치사항 등은 해양수산부장관이 정하여 고시한다. 다만, 해당 컨테이너 또는 용기에 수납한 위험물이 「관세법」 제154조에 따른 보세구역에 반입된 경우에는 미리 관세청장과 협의하여 정하여야 한다. <개정 2013.3.24>","items":[]}]},"제214조":{"title":"용기 및 포장의 수리금지","head":"제214조(용기 및 포장의 수리금지) 위험물을 저장하는 선박(이하 \"저장선\"이라 한다) 안에서는 위험물의 용기 및 포장을 수리해서는 아니 된다.","paras":[]},"제215조":{"title":"표지","head":"제215조(표지) 화약류, 고압가스 독물, 인화성 액체류, 방사성 물질 또는 유기과산화물을 저장하는 저장선에는 마스트(MAST)나 그 밖에 보기 쉬운 장소에 주간은 적기를 내걸고 야간에는 적등을 켜두어야 한다.","paras":[]},"제216조":{"title":"저장선의 상용위험물","head":"제216조(저장선의 상용위험물) 저장선의 상용위험물은 필요하다고 인정되는 최소한의 수준으로 제한하여야 한다.","paras":[]},"제217조":{"title":"유등 등의 보관","head":"제217조(유등 등의 보관) 저장선 안에서 유등(油燈) 등과 그 연료는 금속재 상자에 넣어두고, 재해의 우려가 없는 갑판상의 장소에 보관하여야 한다. <개정 2018.3.12>","paras":[]},"제218조":{"title":"구명설비","head":"제218조(구명설비)","paras":[{"no":"①","text":"① 저장선에는 저장선의 전 종업원을 수용할 수 있는 소형 구명정을 갖춰 두어야 한다.","items":[]},{"no":"②","text":"② 화약류, 인화성 액체류와 그 밖에 발화되기 쉬운 위험물을 저장하는 저장선에는 제1항에 따른 소형 구명정 외에 저장선에 탑승하는 종업원 수만큼의 구명조끼를 갖춰 두어야 한다.","items":[]},{"no":"③","text":"③ 제1항과 제2항은 저장선이 접안하고 있는 경우에는 적용하지 아니한다.","items":[]}]},"제219조":{"title":"저장의 특례","head":"제219조(저장의 특례) 이 장(제3절은 제외한다)에서 순화약질량 5킬로그램 이하의 화약류를 선박에 저장할 경우에는 해당 화약류의 저장에 대해서는 적용하지 아니한다. <개정 2018.3.12>","paras":[]},"제220조":{"title":"저장의 특례","head":"제220조(저장의 특례)","paras":[{"no":"①","text":"① 화약류 외의 위험물을 3일 이내로 선박에 저장할 경우에는 해당 위험물 대해 제217조, 제218조, 제232조, 제235조를 적용하지 아니한다.","items":[]},{"no":"②","text":"② 제1항의 경우에는 위험물의 용기, 포장 및 표찰은 저장위탁자(타인에게 저장을 위탁하지 아니하고 저장할 경우에는 그 자를 말한다. 이하 같다)는 계류(繫留) 장소의 관할지방해양수산청장등의 지시에 따라야 한다. <개정 2020.6.1>","items":[]}]},"제221조":{"title":"용기 및 포장 등","head":"제221조(용기 및 포장 등) 화약류를 선박에 저장하는 경우에는 그 용기, 포장 및 표찰은 해양수산부장관이 정하는 바에 따라야 한다. <개정 2013.3.24>","paras":[]},"제222조":{"title":"저장선의 구조 및 설비","head":"제222조(저장선의 구조 및 설비)","paras":[{"no":"①","text":"① 화약류의 저장선은 단층 갑판을 가진 구조의 선박이어야 한다.","items":[]},{"no":"②","text":"② 화약류의 저장선에는 가장 높은 곳에 피뢰침을 설치하여야 한다.","items":[]},{"no":"③","text":"③ 화약류의 저장선에는 방현재(防舷材)를 설치하여야 한다.","items":[]}]},"제223조":{"title":"저장선의 구조 및 설비","head":"제223조(저장선의 구조 및 설비) 화약류 저장선의 화약류를 저장하는 화물창이나 구획은 다음 각 호에 따라야 한다. <개정 2021.6.30>","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 수밀 구조로 할 것. 다만, 창구 및 갑판에 부착되지 아니한 출입구의 문은 풍우밀(風雨密) 구조도 가능하다."},{"no":"2.","text":"2. 출입구의 문은 강철 재질로 만들고 견고한 잠금장치를 갖추어 둘 것"},{"no":"3.","text":"3. 창을 설치할 경우에는 필요한 최소한도에 국한하고, 10센티미터 이하의 간격으로 지름 1센티미터 이상의 철봉을 끼워두며, 안쪽에는 불투명한 유리를 사용하고 바깥쪽에는 외부에서 쉽게 열 수 없는 강철 재질로 만든 문을 갖춰 둘 것"},{"no":"4.","text":"4. 내면은 목판으로 편평하게 내장하고, 철제 못 등은 못머리가 안보이게 구리판, 시멘트 등으로 덮을 것"},{"no":"5.","text":"5. 통기 구멍은 파랑 등이 침입할 우려가 없는 구조로 하고, 또한 가늘고 촘촘한 철망을 부착시킬 것"},{"no":"6.","text":"6. 내부에 있는 강철 재질의 기둥 등은 목판으로 덮을 것"},{"no":"7.","text":"7. 천장은 방열재로 덮을 것"}]}]},"제224조":{"title":"거주 장소","head":"제224조(거주 장소) 화약류 저장선의 거주 장소는 다음 각 호에 따라야 한다.","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 내면은 아스베스트나 그 밖의 내화재료로 내장할 것"},{"no":"2.","text":"2. 조명설비는 고정시켜 놓을 것"},{"no":"3.","text":"3. 난방 또는 조리용으로 쓰는 난로류는 화약류가 저장된 장소로부터 수평거리 6미터 이상의 간격을 두어 고정시킬 것"},{"no":"4.","text":"4. 난로류의 굴뚝이 천장을 관통하는 부분은 아스베스트나 그 밖의 내화재료로 덮고, 또한 천장의 목판부분으로부터 75밀리미터 이상의 공간을 둘 것"},{"no":"5.","text":"5. 난로류 배기관의 배기구는 화약류를 조정하는 화물창이나 구획에 재해를 미칠 우려가 없는 장소에 돌출시켜 둘 것"},{"no":"6.","text":"6. 화약류를 저장하는 화물창이나 구획과 연결되는 문이 없는 출입구나 창호는 설치하지 말 것"}]}]},"제225조":{"title":"저장선의 위치","head":"제225조(저장선의 위치) 화약류의 저장선은 항로, 정박지, 선장(船場), 가옥, 가스탱크와 그 밖의 건조물, 철도, 궤도, 국도와 지방도로부터 700미터 이상의 거리를 두고 계류하여야 한다. 다만, 지형과 저장하는 화약류의 종류 또는 수량 등의 조건을 고려하여 관할지방해양수산청장등이 위험의 우려가 없다고 인정하는 경우에 한정하여, 그 정도에 따라 일정 거리 이상으로 할 수 있다. <개정 2020.6.1>","paras":[]},"제226조":{"title":"화약류와 다른 위험물과의 관계","head":"제226조(화약류와 다른 위험물과의 관계) 화약류 저장선에는 화약류 외의 위험물을 저장해서는 아니 된다.","paras":[]},"제227조":{"title":"준용","head":"제227조(준용) 화약류의 저장에 대해서는 제44조부터 제48조제1항까지, 제49조제3항 및 제51조를 준용한다.","paras":[]},"제228조":{"title":"저장의 방법","head":"제228조(저장의 방법) 화약류를 저장선에 저장할 경우에는 다음 각 호에 따라야 한다. <개정 2013.3.24, 2018.3.12>","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 화약류는 화물창이나 구획에 저장할 것"},{"no":"2.","text":"2. 순화약질량 10톤을 초과하는 수량의 화약류를 동일 저장선 안에 저장하지 말 것"},{"no":"3.","text":"3. 1천개 이상의 공업뇌관 또는 전기뇌관과 해양수산부장관이 정하는 화약류와는 동일 저장선에 저장하지 말 것"},{"no":"4.","text":"4. 해양수산부장관이 정하는 기폭약과 그 밖의 폭약과는 동일 화물창이나 구획에 저장하지 말 것"},{"no":"5.","text":"5. 공업뇌관 또는 전기뇌관과 그 밖의 화약류는 동일한 화물창이나 구획에 저장하지 말 것"},{"no":"6.","text":"6. 공업뇌관이나 전기뇌관을 그 밖에 다른 화약류가 저장되어 있는 화물창이나 구획에 인접한 화물창이나 구획에 저장할 경우에는 인접하고 있는 격벽으로부터 65센티미터 이상 격리시킬 것"},{"no":"7.","text":"7. 해양수산부장관이 정하는 화약류로서 순화약질량 2,250 킬로그램 이상의 것은 갑판 아래에 저장할 것"}]}]},"제229조":{"title":"조명의 제한","head":"제229조(조명의 제한)","paras":[{"no":"①","text":"① 화약류의 저장선에는 항해등, 정박등, 표지등(標識燈) 및 거주 장소의 조명등을 제외하고는 기름 또는 화학약품을 사용하는 조명등을 설치해서는 아니 된다.","items":[]},{"no":"②","text":"② 화약류를 저장하는 화물창이나 구획 안에서는 휴대전등 외의 조명을 사용해서는 아니 된다.","items":[]}]},"제230조":{"title":"소방 설비","head":"제230조(소방 설비) 화약류의 저장선에는 9리터용 액체소화기 또는 포말소화기와 8리터용 모래상자를 각각 4개 이상 감시인의 거주 장소에 갖춰 두어야 한다.","paras":[]},"제231조":{"title":"정기자체검사","head":"제231조(정기자체검사) 화약류 저장선의 정기 자체검사는 다음 각 호에 따라야 한다.","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 연 2회 이상 매년 정해진 기간에 정기 자체검사를 수행하되 성수기가 있는 저장선의 경우에는 성수기 직전에 1회 이상 시행 할 것."},{"no":"2.","text":"2. 화약류를 저장하는 화물창이나 구획을 청소할 것"},{"no":"3.","text":"3. 제222조부터 제225조까지, 제229조제1항 및 제230조에 따른 기술기준의 적합여부를 검사할 것"}]}]},"제232조":{"title":"용기, 포장","head":"제232조(용기, 포장)","paras":[{"no":"①","text":"① 저장선에 화약류 외의 위험물을 저장하는 경우에는 저장위탁자는 그 용기, 포장 및 표찰에 대하여 각각 해양수산부장관이 정하는 바에 따라야 한다. 다만, 탱커, 탱크선 또는 부선으로서 고압가스, 부식성 물질, 독물 또는 인화성 액체류를 적재하여 운송할 수 있는 탱크에 해당 위험물을 저장할 경우에는 그러하지 아니하다. <개정 2013.3.24>","items":[]},{"no":"②","text":"② 저장선에 병독을 옮기기 쉬운 물질을 저장하는 경우 저장위탁자는 해당 물질에 정표찰 6.2를 붙이고 용기 및 포장의 적합여부에 대하여 관할지방해양수산청장등의 확인을 받아야 한다. <개정 2020.6.1>","items":[]}]},"제233조":{"title":"저장선의 구조등","head":"제233조(저장선의 구조등)","paras":[{"no":"①","text":"① 저장선에 화약류 외의 위험물을 저장할 경우에는 사전에 해당 저장선의 구조와 설비, 저장방법에 대하여 사전에 관할지방해양수산청장등에게 신고하여야 한다. 신고한 사항들을 변경할 때에도 또한 같다. <개정 2020.6.1>","items":[]},{"no":"②","text":"② 관할지방해양수산청장등은 재해의 발생을 방지하는데 필요하다고 인정될 경우에는 제1항에 따라 신고하는 사항에 대하여 필요한 지시를 할 수 있다. <개정 2020.6.1>","items":[]}]},"제234조":{"title":"화기취급의 제한 등","head":"제234조(화기취급의 제한 등) 화약류 외의 위험물 저장선에서는 위험물의 성질에 따라 다음 각 호에 따라야 한다.","paras":[{"no":"","text":"","items":[{"no":"1.","text":"1. 안전성냥 외의 성냥이나 쇠굽이 붙어있는 신발류를 착용하거나 피복(被服)으로 싸지 아니한 철제공구와 같이 불꽃을 유발하기 쉬운 물품을 소지하지 말고 안전하지 않는 장소에서 화기를 취급하거나 흡연하지 말 것"},{"no":"2.","text":"2. 하역을 할 경우에는 화기를 취급하거나 흡연하지 말 것"},{"no":"3.","text":"3. 하역 전에 소방에 필요한 준비를 완료할 것"},{"no":"4.","text":"4. 하역을 마친 경우에는 위험물을 취급하였던 장소를 청소할 것"}]}]},"제235조":{"title":"기록대장","head":"제235조(기록대장) 화약류 외의 위험물 저장선의 선박소유자는 출납한 위험물의 품명과 수량, 출납 연월일을 기재한 기록대장을 갖춰 두고, 이것을 기재한 날로부터 1년간 육상의 사무소에 보존하여야 한다.","paras":[]},"제236조":{"title":"용기, 포장 등","head":"제236조(용기, 포장 등) 상용위험물의 용기, 포장 및 적재방법에 대하여는 해양수산부장관이 정하는 기준에 따라야 한다. <개정 2013.3.24>","paras":[]},"제237조":{"title":"상용화약류의 저장","head":"제237조(상용화약류의 저장)","paras":[{"no":"①","text":"① 순화약질량 25킬로그램을 초과하는 상용화약류(상용위험물인 화약류를 말한다. 이하 같다)를 선박에 저장할 경우에는 제236조의 적재방법에도 불구하고 화약고에 저장하여야 한다. <개정 2018.3.12>","items":[]},{"no":"②","text":"② 제1항의 화약고의 구조와 위치, 설비는 제55조부터 제58조까지에서 규정하는 기술상의 기준에 적합한 것이어야 한다.","items":[]},{"no":"③","text":"③ 상용 화약류를 저장하는 화약고에 대해서는 제231조를 준용한다. 이 경우에 같은 조 제3호 중 \"제222조부터 제225조까지, 제229조제1항 및 제230조의 기술상의 기준\"은 \"제237조제2항 기술상의 기준\"으로 한다.","items":[]}]},"제238조":{"title":"여객선의 연료사용 제한","head":"제238조(여객선의 연료사용 제한) 인화점이 섭씨 43도 이하인 기름은 국제항해에 종사하는 여객선의 기관연료로 사용해서는 아니 된다.","paras":[]},"제239조":{"title":"전문교육기관의 지정기준 등","head":"제239조(전문교육기관의 지정기준 등)","paras":[{"no":"①","text":"① 법 제41조의2제2항에 따라 위험물 안전운송 전문교육기관(이하 \"전문교육기관\"이라 한다)으로 지정받으려는 자는 다음 각 호의 서류를 구비하여 해양수산부장관에게 신청하여야 한다. <개정 2013.3.24>","items":[{"no":"1.","text":"1. 사무소의 명칭과 소재지"},{"no":"2.","text":"2. 법인의 정관(법인의 경우만 해당한다)"},{"no":"3.","text":"3. 성명(법인의 경우 대표자의 성명을 말한다)"},{"no":"4.","text":"4. 다음 각 목의 사항이 포함된 교육계획서 가. 교육과정과 교육방법\n 나. 교육전담요원의 자격, 경력, 정원 등의 현황\n 다. 교육시설 및 교육장비의 개요\n 라. 교육평가의 방법\n 마. 연간 교육계획\n 바. 제4항제2호에 따른 자체 교육규정"}]},{"no":"②","text":"② 법 제41조의2제3항에 따른 전문교육기관의 지정기준은 별표 1과 같다.","items":[]},{"no":"③","text":"③ 해양수산부장관은 제1항에 따른 신청을 받은 경우 제2항의 지정기준에 적합하다고 인정하는 때에는 신청인을 전문교육기관으로 지정 및 통지하고 공고하여야 한다. <개정 2013.3.24>","items":[]},{"no":"④","text":"④ 제3항에 따라 지정된 전문교육기관은 다음 각 호에 따라 교육을 실시하여야 한다. <개정 2013.3.24>","items":[{"no":"1.","text":"1. 교육은 초기교육과 재교육으로 구분하여 실시할 것"},{"no":"2.","text":"2. 법 제41조의2제6항에 따라 고시하는 교육내용 등을 반영하여 자체 교육규정을 제정ㆍ운영할 것"},{"no":"3.","text":"3. 연간 교육계획을 수립하여 해양수산부장관에게 보고할 것"}]},{"no":"⑤","text":"⑤ 전문교육기관은 교육 이수자의 명단을 보관하고, 해양수산부장관이 요청할 때에는 제출하여야 한다. <개정 2013.3.24>","items":[]},{"no":"⑥","text":"⑥ 해양수산부장관은 전문교육기관이 제2항의 지정기준에 적합한지 여부를 매년 심사해야 한다. <개정 2013.3.24>","items":[]},{"no":"⑦","text":"⑦ 전문교육기관이 별표 1에 따른 교육시설, 장비 및 인력 등에 관한 사항을 변경한 경우에는 즉시 해양수산부장관에게 보고하여야 한다. <개정 2013.3.24>","items":[]}]},"제240조":{"title":"전문교육기관의 지정의 취소 등","head":"제240조(전문교육기관의 지정의 취소 등)","paras":[{"no":"①","text":"① 법 제41조의2제5항에 따른 전문교육기관의 지정 취소 및 업무정지 처분기준은 별표 2와 같다.","items":[]},{"no":"②","text":"② 해양수산부장관은 위반행위의 정도, 횟수 등을 고려하여 별표 2에서 정한 업무정지 기간을 2분의 1의 범위에서 가중 또는 경감할 수 있다. 다만, 가중하는 경우 그 기간은 6개월을 초과할 수 없다. <개정 2013.3.24>","items":[]}]}}}},"cases":[{"id":"B1","set":"B","law":"hazmat","item":"컨테이너 위험물 명세서","record":"컨테이너번호 있음 / 송하인 이름·주소 있음 / 수하인 이름·주소 칸 비어 있음 / 분류 제3급 인화성 액체류(저인화점) UN1263 페인트 / 수량 200kg","claim":"적합. 수하인 주소가 없어도 접수한다.","ref":"제34조제1항제3호","planted":true,"plantedType":"semantic"},{"id":"B2","set":"B","law":"hazmat","item":"위험물 명세서","record":"국내 항 간(인천→부산) 운송 / 제8급 부식성 물질 / 송하인 명세서 미작성","claim":"국내 항 간 운송이라 위험물 명세서 제출은 면제된다.","ref":"제16조제1항 단서","planted":false,"plantedType":null},{"id":"B3","set":"B","law":"hazmat","item":"위험물 명세서","record":"국제 운송 / 제6.1급 독물 UN2810 / 송하인 주소 있음 / 수하인 칸 비어 있음","claim":"독물은 수하인 이름·주소를 적어야 하므로 보완 요구한다.","ref":"제16조제1항제2호","planted":false,"plantedType":null},{"id":"B4","set":"B","law":"hazmat","item":"위험물 명세서","record":"국제 운송 / 해양오염물질로 분류되는 제9급 물질 UN3082 / 명세서에 해양오염물질 표기 없음","claim":"해양오염물질 표기가 없어 'MARINE POLLUTANT' 기재를 보완 요구한다.","ref":"제16조제6항","planted":false,"plantedType":null},{"id":"B5","set":"B","law":"hazmat","item":"위험물 명세서","record":"국제 운송 / 소량의 위험물(limited quantity) 포장 / 명세서에 소량 표기 없이 일반 품명만 기재","claim":"소량의 위험물은 별도 표기 없이 일반 화물처럼 적어도 된다.","ref":"제16조제6항","planted":true,"plantedType":"semantic"},{"id":"B6","set":"B","law":"hazmat","item":"위험물 명세서","record":"국제 운송 / 제4.1급 자체반응 물질(운송 중 온도관리 필요) / 제어온도·비상온도 칸 비어 있음","claim":"제어온도와 비상온도는 적지 않아도 된다.","ref":"제16조제7항제1호","planted":true,"plantedType":"semantic"},{"id":"B7","set":"B","law":"hazmat","item":"컨테이너 선적 전 확인","record":"컨테이너 외부 UN번호 표시 UN1950 / 컨테이너 위험물 명세서 UN1170","claim":"선장은 표시와 명세서가 일치하는지 확인해야 하고, 둘이 달라 선적 전 확인이 필요하다.","ref":"제35조제1항","planted":false,"plantedType":null},{"id":"B8","set":"B","law":"hazmat","item":"컨테이너 선적 전 확인","record":"훈증소독 컨테이너 / 훈증제 투입 후 12시간 경과 / 훈증소독주의 부표찰 부착됨","claim":"부표찰이 붙어 있으므로 선적 가능하다.","ref":"제35조제3항","planted":true,"plantedType":"semantic"},{"id":"B9","set":"B","law":"hazmat","item":"컨테이너 선적 전 확인","record":"훈증소독 컨테이너 / 훈증제 투입 후 30시간 경과 / 훈증소독주의 부표찰 부착됨","claim":"24시간이 지났고 부표찰도 있어 선적 가능하다.","ref":"제35조제3항","planted":false,"plantedType":null},{"id":"B10","set":"B","law":"hazmat","item":"컨테이너 위험물 명세서","record":"한 컨테이너에 격리가 필요한 두 위험물(서로 격리해야 하는 분류 조합) 수납","claim":"서로 격리해야 하는 위험물도 같은 컨테이너에 수납할 수 있다.","ref":"제32조제2항","planted":true,"plantedType":"semantic"},{"id":"B11","set":"B","law":"hazmat","item":"위험물운송적합증 재발급 신청서","record":"적합증 기재 내용 변경 사유 발생일 10월 1일 / 신청일 10월 18일","claim":"변경 사유가 생긴 날부터 20일 안이므로 기한 안 신청이다.","ref":"제24조의4제1항","planted":false,"plantedType":null},{"id":"B12","set":"B","law":"hazmat","item":"위험물운송적합증 반납","record":"선박 해체 사유 발생 / 반납 기한 문의","claim":"사유 발생일부터 20일 안에 반납해야 한다.","ref":"제24조의5","planted":true,"plantedType":"number"},{"id":"B13","set":"B","law":"hazmat","item":"위험물 적하일람표","record":"연해구역 국내항간 운송 / 선장이 적하일람표 미작성","claim":"국내항간 연해구역 운송은 적하일람표 작성 대상에서 제외된다.","ref":"제21조제1항","planted":false,"plantedType":null},{"id":"B14","set":"B","law":"hazmat","item":"위험물 적하일람표","record":"국제 운송 완료 / 선박소유자가 육상 사무소에 일람표 보관","claim":"선박소유자는 일람표를 육상 사무소에 1년간 보관해야 한다.","ref":"제21조제3항","planted":false,"plantedType":null},{"id":"B15","set":"B","law":"hazmat","item":"컨테이너 위험물 명세서","record":"선박소유자가 직접 위험물을 컨테이너에 수납 / 선장에게 컨테이너 위험물 명세서만 발급(위험물 명세서 미첨부)","claim":"선박소유자 수납이면 위험물 명세서 첨부가 필요하다.","ref":"제34조제3항","planted":false,"plantedType":null},{"id":"B16","set":"B","law":"hazmat","item":"위험물 명세서","record":"국제 운송 / 위험물 명세서 제출 없음","claim":"선장은 명세서가 없으면 해당 위험물 선적을 거부할 수 있다.","ref":"제16조제5항","planted":false,"plantedType":null},{"id":"A13","set":"A","law":"portact","item":"입출항·항만 안전 업무","record":"예선 선령이 30년인 예선의 정기 예항력검사 유효기간을 따진다.","claim":"유효기간은 5년이다.","ref":"제13조제1항제2호","planted":true,"plantedType":"number"},{"id":"A14","set":"A","law":"portact","item":"입출항·항만 안전 업무","record":"선령이 10년인 예선의 정기 예항력검사 유효기간을 따진다.","claim":"유효기간은 5년이다.","ref":"제13조제1항제1호","planted":false,"plantedType":null},{"id":"A15","set":"A","law":"portact","item":"입출항·항만 안전 업무","record":"자체안전관리계획의 변경승인을 신청하려 한다. 변경사유가 3월 1일에 발생했다.","claim":"변경사유 발생일부터 15일 안에 신청해야 한다.","ref":"제16조제1항제2호","planted":true,"plantedType":"number"},{"id":"A16","set":"A","law":"portact","item":"입출항·항만 안전 업무","record":"자체안전관리계획 승인 신청서가 접수됐다.","claim":"관청은 접수일부터 15일 안에 결과를 통보해야 한다.","ref":"제16조제2항","planted":false,"plantedType":null},{"id":"A17","set":"A","law":"portact","item":"입출항·항만 안전 업무","record":"어느 부두에서 위험물 하역 중지를 긴급히 지시해야 한다.","claim":"긴급한 경우에는 구두로 통보할 수 있다.","ref":"제17조제1항","planted":false,"plantedType":null},{"id":"A18","set":"A","law":"portact","item":"입출항·항만 안전 업무","record":"선박에서 불이 나 경보를 울린다.","claim":"기적이나 사이렌을 단음으로 3회 울린다.","ref":"제29조제1항","planted":true,"plantedType":"number"},{"id":"A19","set":"A","law":"portact","item":"입출항·항만 안전 업무","record":"총톤수 1,500톤 산적액체위험물 운송선박이 부두에 접안한다.","claim":"법 제35조제1항제2호의 위험물 운송선박에 해당한다.","ref":"제19조제2항","planted":false,"plantedType":null},{"id":"A20","set":"A","law":"portact","item":"입출항·항만 안전 업무","record":"위험물 하역 부두에 자동차단밸브를 설치한다.","claim":"육상구역의 관로마다 1개 이상 설치해야 한다.","ref":"제19조의3제3항","planted":false,"plantedType":null},{"id":"A21","set":"A","law":"portact","item":"입출항·항만 안전 업무","record":"해양시설에서 용접 수리 공사의 허가를 신청하는 작업자가 해당 시설 소속 직원이다.","claim":"작업자 자격증 사본은 첨부하지 않아도 된다.","ref":"제25조제1항제2호","planted":true,"plantedType":"semantic"},{"id":"A22","set":"A","law":"portact","item":"입출항·항만 안전 업무","record":"구두로 출항 중지를 통보받은 선박이 있다.","claim":"관청은 지체 없이 선박 출항 중지 통지서를 선장에게 발급해야 한다.","ref":"제30조제2항","planted":false,"plantedType":null},{"id":"A23","set":"A","law":"portact","item":"입출항·항만 안전 업무","record":"선박이 고장으로 조종할 수 없어 지정된 정박지가 아닌 곳에 정박했다.","claim":"정박지 지정 예외 사유에 해당한다.","ref":"제6조제2항제2호","planted":false,"plantedType":null},{"id":"A24","set":"A","law":"portact","item":"입출항·항만 안전 업무","record":"선박을 계선하려는 자가 신고서를 낸다.","claim":"별지 제4호서식 선박계선 신고서를 지방해양수산청장 또는 시ㆍ도지사에게 제출한다.","ref":"제7조제1항","planted":false,"plantedType":null}]};